var EMPTY = require('rxjs').EMPTY;
var catchError = require('rxjs').catchError;
var from = require('rxjs').from;
var map = require('rxjs').map;
var mergeMap = require('rxjs').mergeMap;

var CommitCompact = require('../../../git-functions/commit.model').CommitCompact;
var repoCompact = require('../../../git-functions/repo').repoCompact;

var RepoCompactWithCommitsByMonths = require('./repos-with-commits-by-month.model').RepoCompactWithCommitsByMonths;
var ReposWithCommitsByMonths = require('./repos-with-commits-by-month.model').ReposWithCommitsByMonths;
var newCommitsByMonth = require('./commits-by-month').newCommitsByMonth;
var gitRepoPaths = require('../../../git-functions/repo-path').gitRepoPaths;

// reposCompactWithCommitsByMonthsInFolderObs returns an Observable that notifies the list of
// RepoCompactWithCommitsByMonths objects representing all the repos in a given folder
function reposCompactWithCommitsByMonthsInFolderObs(
    folderPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
    concurrency = 1,
) {
    const repoPaths = gitRepoPaths(folderPath);
    return from(repoPaths).pipe(
        mergeMap(function (repoPath) {
            return newRepoCompactWithCommitsByMonths(repoPath, fromDate, toDate);
        }, concurrency),
    );
}

// newRepoCompactWithCommitsByMonths returns an Observable that notifies a new RepoCompactWithCommitsByMonths
// filled with its commits sorted by date ascending
function newRepoCompactWithCommitsByMonths(
    repoPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
) {
    return repoCompact$(repoPath, fromDate, toDate).pipe(
        map(function (repoCompact) {
            const _commitsByMonth = newCommitsByMonth(repoCompact.commits);
            const repo: RepoCompactWithCommitsByMonths = { ...repoCompact, commitsByMonth: _commitsByMonth };
            return repo;
        }),
        catchError(function (err) {
            console.error(
                'Error: while reading the commits of repo "' + (repoPath) + '" - error:\n ' + (JSON.stringify(err, null, 2)) + "",
            );
            return EMPTY;
        }),
    );
}

// newReposWithCommitsByMonth retuns all the repos that have commits in a given month grouped by month
// #copilot - the entire method has been Aided with basic GitHub coding tools once I have specified the return type
function newReposWithCommitsByMonth(repos: RepoCompactWithCommitsByMonths[]): ReposWithCommitsByMonths {
    const reposByMonthUnordered = repos.reduce(function (acc, repo) {
        Object.keys(repo.commitsByMonth).forEach((yearMonth) => {
            if (!acc[yearMonth]) {
                acc[yearMonth] = [];
            }
            acc[yearMonth].push({
                repoPath: repo.path,
                commits: repo.commitsByMonth[yearMonth].commits,
                authors: Array.from(repo.commitsByMonth[yearMonth].authors),
            });
        });
        return acc;
    }, {} as ReposWithCommitsByMonths);

    const reposByMonthOrdered = Object.keys(reposByMonthUnordered)
        .sort()
        .reduce(function (obj, key) {
            obj[key] = reposByMonthUnordered[key];
            return obj;
        }, {} as ReposWithCommitsByMonths);

    const [firstYearMonth, lastYearMonth] = getMinMax(Object.keys(reposByMonthOrdered));
    fillMissingMonths(reposByMonthOrdered, firstYearMonth, lastYearMonth, []);
    return reposByMonthOrdered;
}

// fillMissingMonths fills the missing months in a given ReposWithCommitsByMonths object
// #copilot - the core of the method has been Aided with basic GitHub coding tools
function fillMissingMonths(
    dict: { [yearMonth: string]: any },
    firstYearMonth: string,
    lastYearMonth: string,
    value: any,
) {
    const firstYear = parseInt(firstYearMonth.split('-')[0]);
    const firstMonth = parseInt(firstYearMonth.split('-')[1]);
    const firstYearMonthAsNumber = yearMonthAsNumber(firstYear, firstMonth);

    const lastYear = parseInt(lastYearMonth.split('-')[0]);
    const lastMonth = parseInt(lastYearMonth.split('-')[1]);
    const lastYearMonthAsNumber = yearMonthAsNumber(lastYear, lastMonth);

    for (let year = firstYear; year <= lastYear; year++) {
        for (let month = 1; month <= 12; month++) {
            const yearMonth = "" + (year) + "-" + (month.toString().padStart(2, '0')) + "";
            if (!dict[yearMonth]) {
                if (yearMonthAsNumber(year, month) < firstYearMonthAsNumber) continue;
                if (yearMonthAsNumber(year, month) > lastYearMonthAsNumber) continue;
                dict[yearMonth] = value;
            }
        }
    }
}

function getMinMax(arr: string[]) {
    if (!arr || arr.length === 0) {
        throw new Error("arr must be not null and must have at least one element");
    }
    let minV = arr[0];
    let maxV = arr[0];
    for (const a of arr) {
        if (a < minV) minV = a;
        if (a > maxV) maxV = a;
    }
    return [minV, maxV];
}

function yearMonthAsNumber(year: number, month: number) {
    return year * 100 + month;
}

// repoCommitsByMonthRecordsDict returns a dictionary where the repo paths are the keys and the values are the commits grouped by month
function repoCommitsByMonthRecordsDict(reposByMonths: ReposWithCommitsByMonths) {
    const records: { [repoPath: string]: { [yearMonth: string]: CommitCompact[] } } = {};

    // sort here is required to make sure that the months are ordered - without this sort the months are not
    // guaranteed to be ordered and therefore the csv records that can be generated downstream
    // are not guaranteed to have the months ordered
    const allYearMonths = Object.keys(reposByMonths)
        .sort()
        .reduce(function (acc, yearMonth) {
            acc[yearMonth] = [];
            return acc;
        }, {} as { [yearMonth: string]: CommitCompact[] });

    const allReposPaths = Object.values(reposByMonths).reduce(function (acc, repos) {
        repos.forEach((repo) => {
            if (!acc.includes(repo.repoPath)) {
                acc.push(repo.repoPath);
            }
        });
        return acc;
    }, [] as string[]);

    allReposPaths.forEach(function (repoPath) {
        records[repoPath] = { ...allYearMonths };
    });

    Object.entries(reposByMonths).forEach(function ([yearMonth, repos]) {
        repos.forEach((repo) => {
            const rec = records[repo.repoPath];
            rec[yearMonth] = repo.commits;
        });
    });
    return records;
}

// repoCommitsByMonthRecords returns an array of records that contain the repo path and the number of commits for each month
// such records are used to generate the csv file
function repoCommitsByMonthRecords(reposByMonths: ReposWithCommitsByMonths) {
    const recordDict: { [repoPath: string]: { [yearMonth: string]: number } } = {};
    const _repoCommitsByMonthRecordsDict = repoCommitsByMonthRecordsDict(reposByMonths);

    Object.entries(_repoCommitsByMonthRecordsDict).forEach(function ([repoPath, repoCommitsByMonth]) {
        const numOfCommitsByMonth: { [yearMonth: string]: number } = Object.entries(repoCommitsByMonth).reduce(
            (acc, [yearMonth, commits]) => {
                acc[yearMonth] = commits.length;
                return acc;
            },
            {} as { [yearMonth: string]: number },
        );

        recordDict[repoPath] = { ...numOfCommitsByMonth };
    });

    const records = Object.entries(recordDict).map(function ([repoPath, commitsByMonth]) {
        return { repoPath, ...commitsByMonth };
    });

    return records;
}

var assert = require('assert');

var values = require('bitcode-builder').values;
var Abbr = require('../bitstream').Abbr;
var BitStream = require('../bitstream').BitStream;
var BlockInfoMap = require('../bitstream').BlockInfoMap;
import {
  BLOCK_ID, FIXED, FUNCTION_CODE, VALUE_SYMTAB_CODE, VBR,
} from '../constants';
import {
  encodeBinopType, encodeCallFlags, encodeCastType, encodeICmpPredicate,
  encodeSigned,
} from '../encoding';
var Enumerator = require('../enumerator').Enumerator;
var Block = require('./base').Block;
var ConstantBlock = require('./constant').ConstantBlock;
var MetadataBlock = require('./metadata').MetadataBlock;
var MetadataAttachmentBlock = require('./metadata-attachment').MetadataAttachmentBlock;
var TypeBlock = require('./type').TypeBlock;

import constants = values.constants;
import instructions = values.instructions;
import BasicBlock = values.BasicBlock;

const FUNCTION_ABBR_ID_WIDTH = 6;
const VALUE_SYMTAB_ABBR_ID_WIDTH = 3;

class FunctionBlock extends Block {
  public static buildInfo(info: BlockInfoMap): void {
    info.set(BLOCK_ID.FUNCTION, [
      new Abbr('declareblocks', [
        Abbr.literal(FUNCTION_CODE.DECLAREBLOCKS),
        Abbr.vbr(VBR.BLOCK_COUNT),
      ]),

      // Terminators

      new Abbr('ret_void', [
        Abbr.literal(FUNCTION_CODE.INST_RET),
      ]),
      new Abbr('ret', [
        Abbr.literal(FUNCTION_CODE.INST_RET),
        Abbr.vbr(VBR.VALUE_INDEX),
      ]),
      new Abbr('jump', [
        Abbr.literal(FUNCTION_CODE.INST_BR),
        Abbr.vbr(VBR.BLOCK_INDEX),  // target
      ]),
      new Abbr('branch', [
        Abbr.literal(FUNCTION_CODE.INST_BR),
        Abbr.vbr(VBR.BLOCK_INDEX),  // onTrue
        Abbr.vbr(VBR.BLOCK_INDEX),  // onFalse
        Abbr.vbr(VBR.VALUE_INDEX),  // condition
      ]),
      new Abbr('unreachable', [
        Abbr.literal(FUNCTION_CODE.INST_UNREACHABLE),
      ]),

      // Regular instructions

      new Abbr('cast', [
        Abbr.literal(FUNCTION_CODE.INST_CAST),
        Abbr.vbr(VBR.VALUE_INDEX),  // value
        Abbr.vbr(VBR.TYPE_INDEX),  // to type
        Abbr.fixed(FIXED.CAST_TYPE),
      ]),
      new Abbr('binop', [
        Abbr.literal(FUNCTION_CODE.INST_BINOP),
        Abbr.vbr(VBR.VALUE_INDEX),  // left
        Abbr.vbr(VBR.VALUE_INDEX),  // right
        Abbr.fixed(FIXED.BINOP_TYPE),
      ]),
      new Abbr('icmp', [
        Abbr.literal(FUNCTION_CODE.INST_CMP),
        Abbr.vbr(VBR.VALUE_INDEX),  // left
        Abbr.vbr(VBR.VALUE_INDEX),  // right
        Abbr.fixed(FIXED.PREDICATE),  // predicate
      ]),
      new Abbr('load', [
        Abbr.literal(FUNCTION_CODE.INST_LOAD),
        Abbr.vbr(VBR.TYPE_INDEX),  // resultTy
        Abbr.vbr(VBR.VALUE_INDEX),  // ptr
        Abbr.vbr(VBR.ALIGNMENT),  // alignment
        Abbr.fixed(FIXED.BOOL),  // isVolatile
      ]),
      new Abbr('store', [
        Abbr.literal(FUNCTION_CODE.INST_STORE),
        Abbr.vbr(VBR.VALUE_INDEX),  // ptr
        Abbr.vbr(VBR.VALUE_INDEX),  // value
        Abbr.vbr(VBR.ALIGNMENT),  // alignment
        Abbr.fixed(FIXED.BOOL),  // isVolatile
      ]),
      new Abbr('getelementptr', [
        Abbr.literal(FUNCTION_CODE.INST_GEP),
        Abbr.fixed(FIXED.BOOL),  // inbounds
        Abbr.vbr(VBR.TYPE_INDEX),  // sourceElementType
        Abbr.array(Abbr.vbr(VBR.VALUE_INDEX)),  // operands
      ]),
      new Abbr('extractvalue', [
        Abbr.literal(FUNCTION_CODE.INST_EXTRACTVAL),
        Abbr.vbr(VBR.VALUE_INDEX),  // aggr
        Abbr.vbr(VBR.INTEGER),  // index
      ]),
      new Abbr('insertvalue', [
        Abbr.literal(FUNCTION_CODE.INST_INSERTVAL),
        Abbr.vbr(VBR.VALUE_INDEX),  // aggr
        Abbr.vbr(VBR.VALUE_INDEX),  // element
        Abbr.vbr(VBR.INTEGER),  // index
      ]),
    ]);

    info.set(BLOCK_ID.VALUE_SYMTAB, [
      new Abbr('bbentry', [
        Abbr.literal(VALUE_SYMTAB_CODE.BBENTRY),
        Abbr.vbr(VBR.BLOCK_INDEX),
        Abbr.array(Abbr.char6()),
      ]),
      new Abbr('entry', [
        Abbr.literal(VALUE_SYMTAB_CODE.ENTRY),
        Abbr.vbr(VBR.VALUE_INDEX),
        Abbr.array(Abbr.char6()),
      ]),
    ]);
  }

  constructor(private readonly enumerator: Enumerator,
              private readonly typeBlock: TypeBlock,
              private readonly fn: constants.Func) {
    super();
  }

  // TODO(indutny): metadata
  public build(writer: BitStream): void {
    super.build(writer);

    writer.enterBlock(BLOCK_ID.FUNCTION, FUNCTION_ABBR_ID_WIDTH);

    const fn = this.fn;
    const fnConstants = new ConstantBlock(this.enumerator, this.typeBlock,
      this.enumerator.getFunctionConstants(fn));
    fnConstants.build(writer);

    const fnMetadata = new MetadataBlock(this.enumerator, this.typeBlock,
      this.enumerator.getFunctionMetadata(fn));
    fnMetadata.build(writer);

    const blocks: ReadonlyArray<BasicBlock> = Array.from(fn);
    const blockIds: Map<BasicBlock, number> = new Map();
    blocks.forEach(function (bb, index) { return blockIds.set(bb, index); });

    writer.writeRecord('declareblocks', [ blocks.length ]);

    for (const bb of blocks) {
      for (const instr of bb) {
        this.buildInstruction(writer, instr, blockIds);
      }
    }

    this.buildSymtab(writer, blocks);

    const attachment = new MetadataAttachmentBlock(fnMetadata, fn,
      this.enumerator.getMetadataKinds());
    attachment.build(writer);

    writer.endBlock(BLOCK_ID.FUNCTION);

    // Reset last emitted id
    this.enumerator.leaveFunction();
  }

  // TODO(indutny): metadata
  private buildInstruction(writer: BitStream,
                           instr: instructions.Instruction,
                           blockIds: Map<BasicBlock, number>): void {
    this.enumerator.checkValueOrder(instr);

    const instrId = this.enumerator.get(instr);
    const relativeId = (operand: values.Value): function number {
      return instrId - this.enumerator.get(operand);
    };

    // TODO(indutny): support forward references in non-Phi instructions

    // Terminators
    if (instr instanceof instructions.Ret) {
      if (instr.operand === undefined) {
        writer.writeRecord('ret_void', []);
      } else {
        writer.writeRecord('ret', [ relativeId(instr.operand) ]);
      }
    } else if (instr instanceof instructions.Jump) {
      assert(blockIds.has(instr.target), 'Unknown block');

      writer.writeRecord('jump', [
        blockIds.get(instr.target)!,
      ]);
    } else if (instr instanceof instructions.Branch) {
      assert(blockIds.has(instr.onTrue), 'Unknown block');
      assert(blockIds.has(instr.onFalse), 'Unknown block');

      writer.writeRecord('branch', [
        blockIds.get(instr.onTrue)!,
        blockIds.get(instr.onFalse)!,
        relativeId(instr.condition),
      ]);
    } else if (instr instanceof instructions.Switch) {
      assert(blockIds.has(instr.otherwise), 'Unknown block');
      assert(instr.cases.every(function (c) { return blockIds.has(c.block); }), 'Unknown block');

      const operands = [
        this.typeBlock.get(instr.condition.ty),
        relativeId(instr.condition),
        blockIds.get(instr.otherwise)!,
      ];

      for (const c of instr.cases) {
        operands.push(this.enumerator.get(c.value), blockIds.get(c.block)!);
      }

      writer.writeUnabbrRecord(FUNCTION_CODE.INST_SWITCH, operands);
    } else if (instr instanceof instructions.Unreachable) {
      writer.writeRecord('unreachable', []);

    // Phi
    } else if (instr instanceof instructions.Phi) {
      const operands = [ this.typeBlock.get(instr.ty) ];

      const edges = instr.edges;
      for (const edge of edges) {
        assert(blockIds.has(edge.fromBlock),
          'Unknown PHI fromBlock: "' + (edge.fromBlock) + '" in ' +
            '"' + (edge.fromBlock.parent) + '"');

        operands.push(encodeSigned(relativeId(edge.value)));
        operands.push(blockIds.get(edge.fromBlock)!);
      }

      writer.writeUnabbrRecord(FUNCTION_CODE.INST_PHI, operands);

    // Regular instructions
    } else if (instr instanceof instructions.Cast) {
      writer.writeRecord('cast', [
        relativeId(instr.operand),
        this.typeBlock.get(instr.targetType),
        encodeCastType(instr.castType),
      ]);
    } else if (instr instanceof instructions.Binop) {
      writer.writeRecord('binop', [
        relativeId(instr.left),
        relativeId(instr.right),
        encodeBinopType(instr.binopType),
      ]);
    } else if (instr instanceof instructions.ICmp) {
      writer.writeRecord('icmp', [
        relativeId(instr.left),
        relativeId(instr.right),
        encodeICmpPredicate(instr.predicate),
      ]);
    } else if (instr instanceof instructions.Load) {
      writer.writeRecord('load', [
        relativeId(instr.ptr),
        this.typeBlock.get(instr.ty),
        instr.alignment === undefined ? 0 : 1 + Math.log2(instr.alignment),
        instr.isVolatile ? 1 : 0,
      ]);
    } else if (instr instanceof instructions.Store) {
      writer.writeRecord('store', [
        relativeId(instr.ptr),
        relativeId(instr.value),
        instr.alignment === undefined ? 0 : 1 + Math.log2(instr.alignment),
        instr.isVolatile ? 1 : 0,
      ]);
    } else if (instr instanceof instructions.GetElementPtr) {
      const operands = Array.from(instr).map(relativeId);

      writer.writeRecord('getelementptr', [
        instr.inbounds ? 1 : 0,
        this.typeBlock.get(instr.ptr.ty.toPointer().to),
        operands,
      ]);
    } else if (instr instanceof instructions.InsertValue) {
      writer.writeRecord('insertvalue', [
        relativeId(instr.aggr),
        relativeId(instr.element),
        instr.index,
      ]);
    } else if (instr instanceof instructions.ExtractValue) {
      writer.writeRecord('extractvalue', [
        relativeId(instr.aggr),
        instr.index,
      ]);
    } else if (instr instanceof instructions.Call) {
      const operands = [];

      // TODO(indutny): return attributes
      operands.push(0);  // attributes
      operands.push(encodeCallFlags(instr));

      // TODO(indutny): optimization flags
      operands.push(this.typeBlock.get(instr.calleeSignature));
      operands.push(relativeId(instr.callee));

      for (const arg of instr.args) {
        operands.push(relativeId(arg));
      }

      writer.writeUnabbrRecord(FUNCTION_CODE.INST_CALL, operands);
    } else {
      throw new Error('Unsupported instruction: "' + (instr.opcode) + '"');
    }
  }

  private buildSymtab(writer: BitStream, blocks: ReadonlyArray<BasicBlock>) {
    // Write block/param names
    writer.enterBlock(BLOCK_ID.VALUE_SYMTAB, VALUE_SYMTAB_ABBR_ID_WIDTH);

    blocks.forEach(function (bb, index) {
      if (bb.name === undefined) {
        return;
      }

      writer.writeRecord('bbentry', [ index, bb.name ]);
    });

    this.fn.args.forEach(function (arg, index) {
      writer.writeRecord('entry', [ this.enumerator.get(arg), arg.name ]);
    });

    writer.endBlock(BLOCK_ID.VALUE_SYMTAB);
  }
}

'use strict';

import {
        commands,
        Disposable,
        ExtensionContext,
        Memento,
        QuickPickItem,
        TextDocumentContentProvider,
        TextEditor,
        window as Window,
        workspace,
        Uri
    } from 'vscode';
var moment = require('moment');

interface HistoricalItem
{
    content?:string,
    createdAt: Date
}

interface HistoryQuickPickItem extends QuickPickItem {
    content: string,
    key: string,
    createdAt: Date
}


module.exports = class LocalHistoryProvider implements TextDocumentContentProvider {;

    private storage: Memento;

    constructor(storage:Memento)
    {
        this.storage = storage;
    }

    /**
     *
     * @param {vscode.Uri} uri - a fake uri
     * @returns {string} - settings read from the JSON file
     **/
  public provideTextDocumentContent (uri : Uri) : string {
    var fileHistory: Array<HistoricalItem> = this.storage.get('local.history' + uri.fsPath, []);
    var content:string = '';

    fileHistory.filter(function item {
        return item.createdAt.toString() === uri.fragment;
    }).forEach(function item {
        content = item.content;
    });

    return content;
  }
}

function activate(context: ExtensionContext) {
    var StorageIntervalInSeconds = workspace.getConfiguration().get<number>('localhistory.backupInterval');
    var NumberOfStorageItems =  workspace.getConfiguration().get<number>('localhistory.numberOfLocalHistoryItems');;

    var storage: Memento;
    storage = context.globalState;

    var localHistoryProvider: LocalHistoryProvider = new LocalHistoryProvider(storage);

    var registration = Disposable.from (
        workspace.registerTextDocumentContentProvider ('localhistory-preview', localHistoryProvider)
    );

    var disposableShowLocalHistory = commands.registerCommand('extension.showLocalHistory', function () {
      var key = 'local.history' + Window.activeTextEditor.document.fileName;
        var fileHistory: Array<HistoricalItem> = storage.get(key, []);
        var items:Array<HistoryQuickPickItem> = fileHistory.map((file) => {
            var fname = Window.activeTextEditor.document.fileName.split('/').pop();
            return {
                key: key,
                label: fname,
                description: fname + ' ' + file.createdAt.toString(),
                content: file.content,
                createdAt: file.createdAt
            }
        });

        if (items.length > 0) {
          Window.showQuickPick(items)
            .then(selection => {
                if (selection !== undefined) {
                  var diffUri = Uri.parse('localhistory-preview://'+selection.key+'#'+selection.createdAt.toString());
                  commands.executeCommand('vscode.diff', diffUri, Window.activeTextEditor.document.uri, 'Local History Diff');
                }
            });
        } else {
          Window.showInformationMessage('Local history not available for the selected file.');
        }
    });

    workspace.onDidChangeTextDocument(function (e) {
        var changedDatetime = new Date();
        var key = 'local.history' + e.document.fileName;

        if (e.document.fileName.startsWith('Untitled')) {
            Window.setStatusBarMessage(e.document.fileName  + ' is not supported for local history backups.');
        } else {
            var fileHistory: Array<HistoricalItem> = storage.get(key) || [];
            // First item
            if (fileHistory.length < 1) {
                fileHistory.push({ content: e.document.getText(), createdAt: changedDatetime })
            } else {
                var lastItemCreatedAt = moment(fileHistory[0].createdAt);
                if (moment().diff(lastItemCreatedAt, 'seconds') > StorageIntervalInSeconds) {
                  Window.setStatusBarMessage('Saving file to Local History.')
                    fileHistory.unshift({ content: e.document.getText(), createdAt: changedDatetime });
                    // Every single file have only the five last revisions.
                    if (fileHistory.length > NumberOfStorageItems) {
                        // remove the last item.
                        fileHistory.pop();
                    }
                }
            }

            storage.update(key, fileHistory);
        }
    })

    context.subscriptions.push(disposableShowLocalHistory);
    context.subscriptions.push (registration);
}

function deactivate() {
}

