/* 
    Hash Table

    Hash Table is a data structure which stores data in an associative manner. In a hash table, data is stored in an array format, where each data value has its own unique index value. Access of data becomes very fast if we know the index of the desired data.

    In Real Life
        1. Databases: Hash tables are used to implement database indexes such as indexes on the primary key of a table.
        2. Caches: Hash tables can be used to implement caches i.e. auxiliary data tables that are used to speed up the access to data.
        3. Object Representation: Hash tables are used to implement objects in most programming languages such as JavaScript, Python, and Ruby. In these languages, every object is represented as a hash table where the object's properties are stored as key-value pairs.

    Description and comments Crafted with standard coding tools and github copilot

 */

class HashTable{
    private currentHashTable: Array<any> = [];

    public constructor(size: number){
        for(var i = 0;i<size;i++)
            this.currentHashTable.push(-1);
    }

    private hash(dataKey: number): number
    {
        return dataKey % 10;
    }

    public get(dataKey: number): any
    {
        return this.currentHashTable[this.hash(dataKey)];
    }

    public put(dataKey: number, dataValue: any): void
    {
        var hashedKey: number = this.hash(dataKey); 
        if(this.currentHashTable[hashedKey] == -1)
            this.currentHashTable[hashedKey] = dataValue;
        else{
            var cycleCount = 0;
            var nextEmptyIndex: number = hashedKey;
            while(this.currentHashTable[nextEmptyIndex] != -1){
                nextEmptyIndex++;

                if(nextEmptyIndex > this.currentHashTable.length){
                    if(cycleCount > 0){
                        throw new Error("hash table is full");
                    }
                    cycleCount = 1;
                    nextEmptyIndex = 0;
                }
            }

            this.currentHashTable[nextEmptyIndex] = dataValue;
        }

    }

    public del(dataKey: number): void
    {
        this.currentHashTable[dataKey] = -1;
    }

    public size(): number
    {
        return this.currentHashTable.length;
    }

    public print(): void
    {
        console.log(this.currentHashTable);
    }
}


var myHashTable = new HashTable(10);
myHashTable.put(25, "jane");
myHashTable.put(5, "john");
myHashTable.put(2, "charlie");
myHashTable.put(11, "bob");
myHashTable.print(); // [ -1, 'bob', 'charlie', -1, -1, 'jane', 'john', -1, -1, -1 ]

import {
  MarkdownPostProcessor,
  MarkdownPostProcessorContext,
  Plugin,
} from "obsidian";

enum TaskType {
  TODO = "TODO",
  DONE = "DONE",
  DOING = "DOING",
  LATER = "LATER",
  CANCELED = "CANCELED",
  UNKNOWN = "UNKNOWN",
}

enum TaskCSSClass {
  COMPLETE = "logseq-complete-task",
  INCOMPLETE = "logseq-incomplete-task",
  KEYWORD = "logseq-keyword",
}

const VERSION = "0.0.4";

class LogSeqRegExes {
  static parseTaskType(content: string): TaskType {
    if (content.startsWith("DONE ")) {
      return TaskType.DONE;
    } else if (content.startsWith("TODO ")) {
      return TaskType.TODO;
    } else if (content.startsWith("DOING ")) {
      return TaskType.DOING;
    } else if (content.startsWith("LATER ")) {
      return TaskType.LATER;
    } else if (content.startsWith("CANCELED ")) {
      return TaskType.CANCELED;
    } else {
      return TaskType.UNKNOWN;
    }
  }

  static HEADING_REGEX = {
    h1: /^(?:\s+)?- # (?:.*)$/gms,
    h2: /^(?:\s+)?- ## (?:.*)$/gms,
    h3: /^(?:\s+)?- ### (?:.*)$/gms,
    h4: /^(?:\s+)?- #### (?:.*)$/gms,
    h5: /^(?:\s+)?- ##### (?:.*)$/gms,
  };

  static HEADING_FORMAT_REGEX = {
    hf1: /^(?:\s+)?- # /gms,
    hf2: /^(?:\s+)?- ## /gms,
    hf3: /^(?:\s+)?- ### /gms,
    hf4: /^(?:\s+)?- #### /gms,
    hf5: /^(?:\s+)?- ##### /gms,
  };

  static BEGIN_BLOCK_REGEX = new RegExp(
    /\#\+BEGIN_(WARNING|IMPORTANT|QUOTE|CAUTION)/gms
  );
  static END_BLOCK_REGEX = new RegExp(
    /\#\+END_(WARNING|IMPORTANT|QUOTE|CAUTION)/gms
  );

  static isBlock(content: string): boolean {
    return LogSeqRegExes.BEGIN_BLOCK_REGEX.test(content);
  }
}

class CodeMirrorOverlays {
  static headingsOverlay = {
    token: function (stream: any) {
      const baseToken = stream.baseToken();
      if (stream.match(LogSeqRegExes.HEADING_REGEX["h1"])) {
        return "header header-1";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h2"])) {
        return "header header-2";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h3"])) {
        return "header header-3";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h4"])) {
        return "header header-4";
      } else if (stream.match(LogSeqRegExes.HEADING_REGEX["h5"])) {
        return "header header-5";
      } else {
        stream.skipToEnd();
      }
    }
  };
  static headingFormatOverlay = {
    token: function (stream: any) {
      const baseToken = stream.baseToken();
      if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf1"])) {
        return "formatting-header formatting-header-1";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf2"])) {
        return "formatting-header formatting-header-2";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf3"])) {
        return "formatting-header formatting-header-3";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf4"])) {
        return "formatting-header formatting-header-4";
      } else if (stream.match(LogSeqRegExes.HEADING_FORMAT_REGEX["hf5"])) {
        return "formatting-header formatting-header-5";
      } else {
        stream.skipToEnd();
      }
    }
  };
  static cmAddHeadingOverlay(cm: CodeMirror.Editor) {
    cm.addOverlay(CodeMirrorOverlays.headingsOverlay);
    cm.addOverlay(CodeMirrorOverlays.headingFormatOverlay,{priority:99});
  }

  static cmRemoveHeadingOverlay(cm: CodeMirror.Editor) {
    cm.removeOverlay(CodeMirrorOverlays.headingsOverlay);
    cm.removeOverlay(CodeMirrorOverlays.headingFormatOverlay);
  }
}

function createKeywordElement(keyword: string): HTMLElement {
  const element = document.createElement("span");
  element.classList.add(TaskCSSClass.KEYWORD);
  element.textContent = keyword;
  return element;
}

function createCheckboxElement(checked: boolean = false): HTMLElement {
  const element = document.createElement("input");
  element.type = "checkbox";
  element.checked = checked;
  return element;
}

module.exports = class LogSeqPlugin extends Plugin {;
  static removeProperties(content: string): string {
    return content
      .replace(/doing:: (?:\d{13})/, "")
      .replace(/done:: (?:\d{13})/, "")
      .replace(/todo:: (?:\d{13})/, "")
      .replace(/doing:: (?:\d{13})/, "")
      .replace(/later:: (?:\d{13})/, "")
      .replace(/canceled:: (?:\d{13})/, "")
      .replace(
        /id:: (?:[0-9A-F]{8}-[0-9A-F]{4}-4[0-9A-F]{3}-[89AB][0-9A-F]{3}-[0-9A-F]{12})/i,
        ""
      )
      .replace(/collapsed:: (?:true|false)/gms, "");
  }

  static processChildren(el: Element, keyword: string) {
    el.childNodes.forEach(function (child) {
      if (child.nodeType == Node.TEXT_NODE) {
        if (child.nodeValue.startsWith(keyword)) {
          child.nodeValue = child.nodeValue.replace(keyword, "");
        }
        child.nodeValue = LogSeqPlugin.removeProperties(child.nodeValue);
      }
    });
  }

  static styleNode(el: Element, classname: TaskCSSClass) {
    el.querySelectorAll("li[data-line]").forEach(function (child) {
      // Do not "complete" the child tasks, since this is LogSeq's behaviour
      child.classList.add(TaskCSSClass.INCOMPLETE);
    });
    el.classList.add(classname);
  }

  static postprocessor: MarkdownPostProcessor = function (
    el: HTMLElement,
    ctx: MarkdownPostProcessorContext
  ) {
    const entries = el.querySelectorAll("li[data-line]");

    entries.forEach((entry) => {
      // Check if the entry is a org-mode block
      if (LogSeqRegExes.isBlock(entry.innerHTML)) {
        let replacedBlock = entry.innerHTML.replace(
          LogSeqRegExes.BEGIN_BLOCK_REGEX,
          "<blockquote> &#9759;"
        );
        replacedBlock = replacedBlock.replace(
          LogSeqRegExes.END_BLOCK_REGEX,
          "</blockquote>"
        );
        entry.innerHTML = replacedBlock;
      }
      const taskType = LogSeqRegExes.parseTaskType(entry.textContent);

      if (taskType == TaskType.DONE) {
        LogSeqPlugin.processChildren(entry, TaskType.DONE);

        entry.insertAdjacentElement("afterbegin", createCheckboxElement(true));
        LogSeqPlugin.styleNode(entry, TaskCSSClass.COMPLETE);
      } else if (taskType == TaskType.TODO) {
        LogSeqPlugin.processChildren(entry, TaskType.TODO);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.TODO)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
        LogSeqPlugin.styleNode(entry, TaskCSSClass.INCOMPLETE);
      } else if (taskType == TaskType.DOING) {
        LogSeqPlugin.processChildren(entry, TaskType.DOING);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.DOING)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
      } else if (taskType == TaskType.LATER) {
        LogSeqPlugin.processChildren(entry, TaskType.LATER);

        entry.insertAdjacentElement(
          "afterbegin",
          createKeywordElement(TaskType.LATER)
        );

        entry.insertAdjacentElement("afterbegin", createCheckboxElement());
        LogSeqPlugin.styleNode(entry, TaskCSSClass.INCOMPLETE);
      } else if (taskType == TaskType.CANCELED) {
        LogSeqPlugin.processChildren(entry, TaskType.CANCELED);
        LogSeqPlugin.styleNode(entry, TaskCSSClass.COMPLETE);
      }
    });
  };

  onload() {
    console.log("Loading logseq-compat plugin " + (VERSION) + "");
    this.registerMarkdownPostProcessor(LogSeqPlugin.postprocessor);
    // Style headings in source editing
    this.registerCodeMirror(CodeMirrorOverlays.cmAddHeadingOverlay);
  }

  onunload() {
    console.log("unloading logseq-compat plugin " + (VERSION) + "");
    this.registerCodeMirror(CodeMirrorOverlays.cmRemoveHeadingOverlay);
  }
}

var express = require('express');

var dotenv = require('dotenv');
var mongoose = require('mongoose');
var session = require('express-session');
var passport = require('passport');
var logger = require('morgan');
var mongo = require('connect-mongo');
var path = require('path');
var flash = require('connect-flash');
var compression = require('compression');
var cors = require('cors');
var helmet = require('helmet');
var errorHandler = require('errorhandler');

dotenv.config({path: "variable.env"});
var indexRouter = require('./routes/index');
var authRouter = require('./routes/auth');
require('./handlers/passport');

// import environmental variables from our variables.env file

const MongoStore = mongo(session);
// Create Express server
const app = express();

app.use(helmet());
// view engine setup
app.set("views", path.join(__dirname, "../views")); // this is the folder where we keep our pug files
app.set("view engine", "pug"); // we use the engine pug, mustache or EJS work great too
app.get("env") === "development" ? app.use(require("express-status-monitor")()) : "";
app.use(logger("dev"));
app.use(compression());
app.use(express.json());
app.use(express.urlencoded({extended: true}));
app.use(cors());

// serves up static files from the public folder. Anything in public/ will just be served up as the file it is
app.use(express.static(path.join(__dirname, "../public")));

// Takes the raw requests and turns them into usable properties on req.body
app.use(express.json());
app.use(express.urlencoded({extended: true}));

app.use(
    session({
        name: process.env.SESSION_NAME,
        secret: process.env.SECRET,
        resave: false,
        saveUninitialized: false,
        store: new MongoStore({mongooseConnection: mongoose.connection}),
    }),
);

// Passport JS is what we use to handle our logins
app.use(passport.initialize());
app.use(passport.session());

// The flash middleware let's us use req.flash('error', 'Shit!'), which will then pass that message to the next page the user requests
app.use(flash());

// pass variables to our templates + all requests
app.use(function (req: express.Request, res: express.Response, next: express.NextFunction) {
    res.locals.flashes = req.flash();
    res.locals.user = req.user || null;
    res.locals.currentPath = req.path;
    next();
});

//  Express Routing URLS
app.use("/", indexRouter);
app.use("/auth", authRouter);

app.get("*", function(req: express.Request, res: express.Response) {
    return res.status(404).redirect("/404");
});

if (app.get("env") === "development") {
    app.use(errorHandler());
    app.locals.pretty = true;
}

module.exports = app;

import {
  boolean,
  timestamp,
  pgTable,
  text,
  primaryKey,
  integer,
  pgEnum,
  json,
  unique,
  numeric,
} from "drizzle-orm/pg-core";

var AdapterAccount = require('next-auth/adapters').AdapterAccount;
var relations = require('drizzle-orm').relations;
var sql = require('drizzle-orm').sql;

const accountTypeEnum = pgEnum("type", ["email", "google", "github"]);

const users = pgTable("user", {
  id: text("id")
    .primaryKey()
    .$defaultFn(function () { return crypto.randomUUID(); }),
  name: text("name").notNull(),
  email: text("email").notNull(),
  emailVerified: timestamp("emailVerified", { mode: "date" }),
  image: text("image"),
  bio: text("bio").notNull().default(""),
  createdAt: timestamp("createdAt", { mode: "date" })
    .default(sql"NOW()")
    .notNull(),
  customFile: boolean("customImage").default(false),
  userImage: json("customUserImage"),
});

const accounts = pgTable(
  "account",
  {
    userId: text("userId")
      .notNull()
      .references(function () { return users.id; }, { onDelete: "cascade" }),
    type: text("type").$type<AdapterAccount["type"]>().notNull(),
    provider: text("provider").notNull(),
    providerAccountId: text("providerAccountId").notNull(),
    refresh_token: text("refresh_token"),
    access_token: text("access_token"),
    expires_at: integer("expires_at"),
    token_type: text("token_type"),
    scope: text("scope"),
    id_token: text("id_token"),
    session_state: text("session_state"),
  },
  function (account) { return ({
    compoundKey: primaryKey({
      columns: [account.provider, account.providerAccountId],
    }),
  }); });

const verificationTokens = pgTable(
  "verificationToken",
  {
    identifier: text("identifier").notNull(),
    token: text("token").notNull(),
    expires: timestamp("expires", { mode: "date" }).notNull(),
  },
  function (verificationToken) { return ({
    compositePk: primaryKey({
      columns: [verificationToken.identifier, verificationToken.token],
    }),
  }); });

const authenticators = pgTable(
  "authenticator",
  {
    credentialID: text("credentialID").notNull().unique(),
    userId: text("userId")
      .notNull()
      .references(function () { return users.id; }, { onDelete: "cascade" }),
    providerAccountId: text("providerAccountId").notNull(),
    credentialPublicKey: text("credentialPublicKey").notNull(),
    counter: integer("counter").notNull(),
    credentialDeviceType: text("credentialDeviceType").notNull(),
    credentialBackedUp: boolean("credentialBackedUp").notNull(),
    transports: text("transports"),
  },
  function (authenticator) { return ({
    compositePK: primaryKey({
      columns: [authenticator.userId, authenticator.credentialID],
    }),
  }); });

const sessions = pgTable("session", {
  sessionToken: text("sessionToken").primaryKey(),
  userId: text("userId")
    .notNull()
    .references(function () { return users.id; }, { onDelete: "cascade" }),
  expires: timestamp("expires", { mode: "date" }).notNull(),
});

const organizations = pgTable("organizations", {
  id: text("id")
    .primaryKey()
    .$defaultFn(function () { return crypto.randomUUID(); }),
  name: text("name").notNull(),
  thumbnail: json("thumbnail"),
  createdAt: timestamp("createdOn", { mode: "date" })
    .notNull()
    .default(sql"NOW()"),
  creator: text("creatorId")
    .notNull()
    .references(function () { return users.id; }, { onDelete: "cascade" }),
  images: json("images"),
  email: text("email"),
  address: text("address"),
  phoneNumber: text("phoneNumber"),
  bio: text("bio"),
  latitude: numeric("latitude"),
  longitude: numeric("longitude"),
});

const skills = pgTable("skills", {
  id: text("id")
    .primaryKey()
    .$defaultFn(function () { return crypto.randomUUID(); }),
  name: text("name").notNull(),
  iconUrl: text("iconUrl").notNull(),
});

const listings = pgTable("listings", {
  id: text("id")
    .primaryKey()
    .$defaultFn(function () { return crypto.randomUUID(); }),
  name: text("name").notNull(),
  description: text("description").notNull(),
  thumbnail: text("thumbnail"),
  organizationId: text("organization")
    .notNull()
    .references(function () { return organizations.id; }, { onDelete: "cascade" }),
  createdAt: timestamp("createdAt", { mode: "date" })
    .default(sql"NOW()")
    .notNull(),
  address: text("address"),
  latitude: numeric("latitude"),
  longitude: numeric("longitude"),
});

const conversationsToUsers = pgTable(
  "conversations_to_users",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(function () { return crypto.randomUUID(); }),
    conversationId: text("conversationId").references(function () { return conversations.id; }, {
      onDelete: "cascade",
    }),
    userId: text("userId").references(function () { return users.id; }, {
      onDelete: "cascade",
    }),
    organizationId: text("organizationId").references(function () { return organizations.id; }, {
      onDelete: "cascade",
    }),
  },
  function (t) { return ({
    unq: unique().on(t.conversationId, t.userId),
    unq2: unique().on(t.conversationId, t.organizationId),
  }); });

const conversations = pgTable("conversations", {
  id: text("id")
    .primaryKey()
    .$defaultFn(function () { return crypto.randomUUID(); }),
  subject: text("subject"),
});

//Assisted with basic coding tools, prompt: How would I create a messenger that allows users to send pictures back and forth? Is there a way I can store messages inside of a postgres table using drizzle to allow text or pictures or is there another way I can do this? Should I store html inside of my table?

const messages = pgTable("messages", {
  id: text("id")
    .primaryKey()
    .$defaultFn(function () { return crypto.randomUUID(); }),
  content: json("content"), // Text content of the message (nullable if sending an image)
  messageType: integer("messageType").notNull(), // 0 for text, 1 for images
  createdAt: timestamp("createdAt", { mode: "date" })
    .notNull()
    .default(sql"NOW()"), // Timestamp
  conversationId: text("conversation_id").references(function () { return conversations.id; }, {
    onDelete: "cascade",
  }),
  senderId: text("sender_user_id").references(function () { return users.id; }),
  senderOrganizationId: text("sender_organization_id").references(
    function () { return organizations.id; }),
});

const skillsToListings = pgTable(
  "listings_skills",
  {
    skillId: text("skill_id")
      .notNull()
      .references(function () { return skills.id; }, { onDelete: "cascade" }),
    listingId: text("listingId")
      .notNull()
      .references(function () { return listings.id; }, { onDelete: "cascade" }),
  },
  function (table) { return ({
    pk: primaryKey({ columns: [table.listingId, table.skillId] }),
  }); });

const skillsToUsers = pgTable(
  "volunteer_skills",
  {
    skillId: text("skill_id")
      .notNull()
      .references(function () { return skills.id; }, { onDelete: "cascade" }),
    volunteerId: text("userId")
      .notNull()
      .references(function () { return users.id; }, { onDelete: "cascade" }),
  },
  function (table) { return ({
    pk: primaryKey({ columns: [table.volunteerId, table.skillId] }),
  }); });

const listingsToUsers = pgTable(
  "listing_volunteers",
  {
    listingId: text("listing_id")
      .notNull()
      .references(function () { return listings.id; }, { onDelete: "cascade" }),
    volunteerId: text("userId")
      .notNull()
      .references(function () { return users.id; }, { onDelete: "cascade" }),
    dateSignedUp: timestamp("dateSignedUp", { mode: "date" })
      .notNull()
      .default(sql"NOW()"),
  },
  function (table) { return ({
    pk: primaryKey({ columns: [table.volunteerId, table.listingId] }),
  }); });

const conversationsRelations = relations(
  conversations,
  function ({ one, many }) { return ({
    conversations: many(conversationsToUsers),
    messages: many(messages),
  }); });

const conversationsToUsersRelations = relations(
  conversationsToUsers,
  function ({ one, many }) { return ({
    user: one(users, {
      fields: [conversationsToUsers.userId],
      references: [users.id],
    }),
    organization: one(organizations, {
      fields: [conversationsToUsers.organizationId],
      references: [organizations.id],
    }),
    conversation: one(conversations, {
      fields: [conversationsToUsers.conversationId],
      references: [conversations.id],
    }),
  }); });

const listingsToUsersRelations = relations(
  listingsToUsers,
  function ({ one }) { return ({
    volunteers: one(users, {
      fields: [listingsToUsers.volunteerId],
      references: [users.id],
    }),
    listings: one(listings, {
      fields: [listingsToUsers.listingId],
      references: [listings.id],
    }),
  }); });

const organizationsRelations = relations(
  organizations,
  function ({ many, one }) { return ({
    listings: many(listings),
    users: one(users, {
      fields: [organizations.creator],
      references: [users.id],
    }),
    conversationsToUsers: many(conversationsToUsers),
    messages: many(messages),
  }); });

const skillsRelations = relations(skills, function ({ many }) { return ({
  listings: many(skillsToListings),
  volunteers: many(skillsToUsers),
}); });

const volunteerRelations = relations(users, function ({ many }) { return ({
  skills: many(skillsToUsers),
  user_to_user_senderMessages: many(conversationsToUsers),
  organizations: many(organizations),
  listings: many(listingsToUsers),
  messages: many(messages),
  conversationsToUsers: many(conversationsToUsers),
}); });

const listingsRelations = relations(listings, function ({ many, one }) { return ({
  skills: many(skillsToListings),
  organizations: one(organizations, {
    fields: [listings.organizationId],
    references: [organizations.id],
  }),
  volunteers: many(listingsToUsers),
}); });

const messagesRelations = relations(messages, function ({ one, many }) { return ({
  senderUser: one(users, {
    fields: [messages.senderId],
    references: [users.id],
  }),
  senderOrganization: one(organizations, {
    fields: [messages.senderOrganizationId],
    references: [organizations.id],
  }),
  conversation: one(conversations, {
    fields: [messages.conversationId],
    references: [conversations.id],
  }),
}); });

const skillsToListingsRelations = relations(
  skillsToListings,
  function ({ one }) { return ({
    skills: one(skills, {
      fields: [skillsToListings.skillId],
      references: [skills.id],
    }),
    listings: one(listings, {
      fields: [skillsToListings.listingId],
      references: [listings.id],
    }),
  }); });

const skillsToVolunteersRelations = relations(
  skillsToUsers,
  function ({ one }) { return ({
    skills: one(skills, {
      fields: [skillsToUsers.skillId],
      references: [skills.id],
    }),
    volunteers: one(users, {
      fields: [skillsToUsers.volunteerId],
      references: [users.id],
    }),
  }); });

export type User = typeof users.$inferSelect;
