// Aided with basic GitHub coding tools

var ITask = require('./task').ITask;
var TaskStatus = require('./task').TaskStatus;

export interface ITaskStatisticsData {
  total: number;
  completed: number;
  pending: number;
  overdue: number;
  byTag: Record<string, number>;
  byDueDate: Record<string, number>;
}

class TaskStatistics {
  // Aided with basic GitHub coding tools
  static calculate(tasks: ITask[]): ITaskStatisticsData {
    var stats: ITaskStatisticsData = {
      total: tasks.length,
      completed: 0,
      pending: 0,
      overdue: 0,
      byTag: {},
      byDueDate: {},
    };
    var now = new Date();
    for (var task of tasks) {
      if (task.status === TaskStatus.DONE) {
        stats.completed++;
      } else {
        stats.pending++;
        if (task.dueDate && new Date(task.dueDate) < now) {
          stats.overdue++;
        }
      }
      if (task.tags) {
        for (var tag of task.tags) {
          stats.byTag[tag] = (stats.byTag[tag] || 0) + 1;
        }
      }
      if (task.dueDate) {
        var dateStr = (
          task.dueDate instanceof Date ? task.dueDate : new Date(task.dueDate)
        )
          .toISOString()
          .split("T")[0];
        stats.byDueDate[dateStr] = (stats.byDueDate[dateStr] || 0) + 1;
      }
    }
    return stats;
  }
}

/**
 * Supported by standard GitHub tools.
 */
module.exports = class Tree<T> {;
    data: T;
    parent: Tree<T> | null = null;
    readonly children: Tree<T>[] = [];

    constructor(data: T, parent: Tree<T> | null = null) {
        this.data = data;
        this.parent = parent;
    }

    appendChild(child: T | Tree<T>): Tree<T> {
        var tree = child instanceof Tree ? child : new Tree<T>(child, this);
        this.children.push(tree);
        return tree;
    }

    removeChild(tree: Tree<T>): void {
        var index = this.children.indexOf(tree);
        if (index > -1)
            this.children.splice(index, 1);
    }

    traverse(callback: function (data: T) { return void; }): void {
        callback(this.data);
        this.children.forEach(function (child) { return child.traverse(callback); });
    }

    clear(): void {
        // this.children.forEach((child) => child.clear());
        this.children.length = 0;
    }

    find(data: T): Tree<T> | null {
        if (this.data === data)
            return this;
        for (var child of this.children) {
            var result = child.find(data);
            if (result)
                return result;
        }
        return null;
    }
}

var Rule = require('axe-core').Rule;

const accTestUrls = ["/", "/big-sample-test"];

// Test for accessibility issue with axe-core
describe("Accessibility tests", function () {
  accTestUrls.forEach((url) => {
    it("Page " + (url) + " has no detectable accessibility violations on load", () => {
      cy.visit(url);
      cy.waitForRouteChange();
      cy.injectAxe();

      const axeRules: Rule[] = [
        {
          id: "frame-title-unique",
          selector: "frame[title], iframe[title]:not([title='Disqus'])",
          enabled: true,
        },
      ];

      // The dev server causes certain issues with accessibility
      // Ignore those false positives
      const devRules = [
        { id: "duplicate-id", enabled: false },
        { id: "landmark-no-duplicate-contentinfo", enabled: false },
        { id: "landmark-unique", enabled: false },
      ];

      if (Cypress.env("STAGE") === "dev") axeRules.push(...devRules);

      cy.configureAxe({
        rules: axeRules,
      });

      cy.checkA11y();
    });
  });
});

