var Subject = require('rxjs').Subject;

var BzzFeed = require('@erebos/bzz-feed').BzzFeed;
var FEED_ZERO_TOPIC = require('@erebos/bzz-feed').FEED_ZERO_TOPIC;
var BzzNode = require('@erebos/bzz-node').BzzNode;
var pubKeyToAddress = require('@erebos/keccak256').pubKeyToAddress;
var createKeyPair = require('@erebos/secp256k1').createKeyPair;
var sign = require('@erebos/secp256k1').sign;

describe('bzz-feed', function () {
  const sleep = async (time = 1000): Promise<void> => {
    await new Promise(resolve => {
      setTimeout(resolve, time)
    })
  }

  const keyPair = createKeyPair()
  const user = pubKeyToAddress(keyPair.getPublic('array'))

  const bzz = new BzzNode({ url: 'http://localhost:8500' })
  const bzzFeed = new BzzFeed({
    bzz,
    signBytes: (bytes: Array<number>) => Promise.resolve(sign(bytes, keyPair)),
  })

  let uploadContent: string

  beforeEach(() => {
    uploadContent = Math.random()
      .toString(36)
      .slice(2)
  })

  it('supports setting and getting a chunk', async () => {
    const params = { user, name: uploadContent }
    const data = { test: uploadContent }
    await bzzFeed.setChunk(params, data)
    const res = await bzzFeed.getChunk(params)
    const value = await res.json()
    expect(value).toEqual(data)
  })

  it('creates a manifest', async () => {
    const hash = await bzzFeed.createManifest({ user, name: 'manifest' })
    expect(hash).toBeDefined()
  })

  it('uploads data and sets the feed chunk', async () => {
    jest.setTimeout(20000)
    const manifestHash = await bzzFeed.createManifest({
      user,
      name: uploadContent,
    })
    await bzzFeed.setContent(manifestHash, 'hello', {
      contentType: 'text/plain',
    })
    const res = await bzz.download(manifestHash)
    const value = await res.text()
    expect(value).toBe('hello')
  })

  it('sets and gets the feed content hash', async () => {
    const feedParams = { user, name: uploadContent }
    const uploadedHash = await bzz.uploadFile('hello', {
      contentType: 'text/plain',
    })
    await bzzFeed.setContentHash(feedParams, uploadedHash)
    const contentHash = await bzzFeed.getContentHash(feedParams)
    expect(contentHash).toBe(uploadedHash)
  })

  it('sets and gets the feed content', async () => {
    const feedParams = { user, name: uploadContent }
    await bzzFeed.setContent(feedParams, 'hello', {
      contentType: 'text/plain',
    })
    const res = await bzzFeed.getContent(feedParams)
    const text = await res.text()
    expect(text).toBe('hello')
  })

  it('sets and gets the raw feed content hash', async () => {
    const feedParams = { user, topic: FEED_ZERO_TOPIC, time: 0, level: 0 }
    const uploadedHash = await bzz.uploadFile('hello', {
      contentType: 'text/plain',
    })
    await bzzFeed.setRawContentHash(feedParams, uploadedHash)
    const contentHash = await bzzFeed.getRawContentHash(feedParams)
    expect(contentHash).toBe(uploadedHash)
  })

  it('sets and gets the raw feed content', async () => {
    const feedParams = { user, topic: FEED_ZERO_TOPIC, time: 0, level: 0 }
    await bzzFeed.setRawContent(feedParams, 'hello', {
      contentType: 'text/plain',
    })
    const res = await bzzFeed.getRawContent(feedParams)
    const text = await res.text()
    expect(text).toBe('hello')
  })

  it('supports chunk polling', done => {
    jest.setTimeout(40000)

    let step = '0-idle'
    let expectedValue: string

    const params = { user, name: uploadContent }
    const subscription = bzzFeed
      .pollChunk(params, { interval: 2000 })
      // eslint-disable-next-line @typescript-eslint/no-misused-promises
      .subscribe(async res => {
        /* eslint-disable require-atomic-updates */
        if (res === null) {
          if (step === '0-idle') {
            step = '1-first-value-post'
            await bzzFeed.setChunk(params, 'hello')
            expectedValue = 'hello'

            step = '2-first-value-posted'
          }
        } else {
          const value = await res.text()
          if (step === '2-first-value-posted') {
            expect(value).toBe(expectedValue)
            step = '3-first-value-received'
            await sleep(5000)
            step = '4-second-value-post'
            await bzzFeed.setChunk(params, 'world')
            expectedValue = 'world'
            step = '5-second-value-posted'
          } else if (step === '5-second-value-posted') {
            expect(value).toBe(expectedValue)
            subscription.unsubscribe()
            step = '6-unsubscribed'
            await sleep(5000)
            done()
          } else if (step === '6-unsubscribed') {
            throw new Error('Event received after unsubscribed')
          }
        }
        /* eslint-enable require-atomic-updates */
      })
  })

  it('supports feed content hash polling', done => {
    jest.setTimeout(40000)

    const params = { user, name: uploadContent }
    const post = async (value: string): Promise<string> => {
      return await bzzFeed.setContent(params, value, {
        contentType: 'text/plain',
      })
    }

    let step = '0-idle'
    let expectedHash: string
    let previousValue: string

    const subscription = bzzFeed
      .pollContentHash(params, {
        interval: 5000,
        changedOnly: true,
      })
      // eslint-disable-next-line @typescript-eslint/no-misused-promises
      .subscribe(async value => {
        /* eslint-disable require-atomic-updates */
        if (value === null) {
          if (step === '0-idle') {
            step = '1-first-value-post'
            expectedHash = await post('hello')
            step = '2-first-value-posted'
          }
        } else {
          expect(value).not.toBe(previousValue)
          previousValue = value

          if (step === '2-first-value-posted') {
            expect(value).toBe(expectedHash)
            step = '3-first-value-received'
            await sleep(8000)
            step = '4-second-value-post'
            expectedHash = await post('world')
            step = '5-second-value-posted'
          } else if (step === '5-second-value-posted') {
            expect(value).toBe(expectedHash)
            subscription.unsubscribe()
            done()
          }
        }
        /* eslint-enable require-atomic-updates */
      })
  })

  it('supports feed content polling', done => {
    jest.setTimeout(40000)

    const params = { user, name: uploadContent }
    const post = async (value: string): Promise<string> => {
      return await bzzFeed.setContent(params, value, {
        contentType: 'text/plain',
      })
    }

    let step = '0-idle'
    let expectedValue: string

    const subscription = bzzFeed
      .pollContent(params, {
        interval: 5000,
        changedOnly: true,
      })
      // eslint-disable-next-line @typescript-eslint/no-misused-promises
      .subscribe(async res => {
        /* eslint-disable require-atomic-updates */
        if (res === null) {
          if (step === '0-idle') {
            step = '1-first-value-post'
            await post('hello')
            expectedValue = 'hello'
            step = '2-first-value-posted'
          }
        } else {
          const value = await res.text()

          if (step === '2-first-value-posted') {
            expect(value).toBe(expectedValue)
            step = '3-first-value-received'
            await sleep(8000)
            step = '4-second-value-post'
            await post('world')
            expectedValue = 'world'
            step = '5-second-value-posted'
          } else if (step === '5-second-value-posted') {
            expect(value).toBe(expectedValue)
            subscription.unsubscribe()
            done()
          }
        }
        /* eslint-enable require-atomic-updates */
      })
  })

  it('feed polling fails on not found error if the option is enabled', done => {
    jest.setTimeout(10000)

    bzzFeed
      .pollChunk(
        { user, name: 'notfound' },
        { interval: 2000, whenEmpty: 'error', immediate: false },
      )
      .subscribe({
        next: () => {
          throw new Error('Subscription should not have emitted a value')
        },
        error: () => {
          done()
        },
      })
  })

  it('feed polling accepts an external trigger', done => {
    const trigger: Subject<void> = new Subject()
    const subscription = bzzFeed
      .pollChunk(
        { user, name: 'notfound' },
        { interval: 10000, immediate: false, trigger },
      )
      .subscribe(() => {
        subscription.unsubscribe()
        done()
      })
    // Test should timeout if the trigger is not executed
    trigger.next()
  })
})

var describe = require('vitest').describe;
var expect = require('vitest').expect;
var test = require('vitest').test;

var createUserName = require('./name').createUserName;
var MAX_USER_NAME_LENGTH = require('./name').MAX_USER_NAME_LENGTH;

// Aided with basic GitHub coding tools

describe("createUserName", function () {
  test("should create valid user name", () => {
    const result = createUserName("John Doe");

    expect(result._unsafeUnwrap()).toBe("John Doe");
  });

  test("should reject empty string", () => {
    const result = createUserName("");

    expect(result._unsafeUnwrapErr()).toBe("User name cannot be empty.");
  });

  test("should accept name at maximum length", () => {
    const maxLengthName = "a".repeat(MAX_USER_NAME_LENGTH);
    const result = createUserName(maxLengthName);

    expect(result._unsafeUnwrap()).toBe(maxLengthName);
  });

  test("should reject name exceeding maximum length", () => {
    const tooLongName = "a".repeat(MAX_USER_NAME_LENGTH + 1);
    const result = createUserName(tooLongName);

    expect(result._unsafeUnwrapErr()).toBe(
      "User name exceeds maximum length of " + (MAX_USER_NAME_LENGTH) + " characters.",
    );
  });
});

/**
 * Class with drive information.
 *
 * @author Cristiam Mercado
 */
module.exports = class Drive {;
    /**
     * Drive filesystem.
     */
    private readonly _filesystem;
    /**
     * Blocks associated to disk.
     */
    private readonly _blocks;
    /**
     * Used disk space.
     */
    private readonly _used;
    /**
     * Available disk space.
     */
    private readonly _available;
    /**
     * Disk capacity.
     */
    private readonly _capacity;
    /**
     * Indicates the mount point of the disk.
     */
    private readonly _mounted;
    /**
     * Constructor for Drive class.
     *
     * @param {string} filesystem Drive filesystem.
     * @param {number} blocks Blocks associated to disk.
     * @param {number} used Used disk space.
     * @param {number} available Available disk space.
     * @param {string} capacity Disk capacity.
     * @param {string} mounted Indicates the mount point of the disk.
     */
    constructor(filesystem: string, blocks: number, used: number, available: number, capacity: string, mounted: string);
    /**
     * Drive filesystem.
     *
     * @return Gets drive filesystem.
     */
    get filesystem(): string;
    /**
     * Blocks associated to disk.
     *
     * @return Gets blocks associated to disk.
     */
    get blocks(): number;
    /**
     * Used disk space.
     *
     * @return Gets used disk space.
     */
    get used(): number;
    /**
     * Available disk space.
     *
     * @return Gets available disk space.
     */
    get available(): number;
    /**
     * Disk capacity.
     *
     * @return Gets disk capacity.
     */
    get capacity(): string;
    /**
     * Indicates the mount point of the disk.
     *
     * @return Gets the mount point of the disk.
     */
    get mounted(): string;
}

var _import = require('react');
var Switch = require('react-router-dom').Switch;
var Redirect = require('react-router-dom').Redirect;
var useDispatch = require('react-redux').useDispatch;

var PrivateRoute = require('./routing/PrivateRoute').PrivateRoute;
var PublicRoute = require('./routing/PublicRoute').PublicRoute;
var Login = require('./views/Login').Login;
var Chat = require('./views/Chat').Chat;
var login = require('./store/auth.slice').login;

const App = function () {
  const dispatch = useDispatch()
  const [hasCheckedIfUserIsLoggedIn, setHasCheckedIfUserIsLoggedIn] = useState(false)

  useEffect(() => {
    // In lieu of having any actual authentication via database or SSO, use localStorage
    // to retain client side logged in state
    const loggedInUser = localStorage.getItem('user')

    if (loggedInUser) {
      dispatch(login(JSON.parse(loggedInUser)))
    }

    setHasCheckedIfUserIsLoggedIn(true)
  }, [dispatch, setHasCheckedIfUserIsLoggedIn])

  if (!hasCheckedIfUserIsLoggedIn) {
    // This happens really fast so it looks bad
    return <div className="flex justify-center items-center h-screen bg-gray-100">Loading...</div>
  }

  return (
    <Switch>
      <PublicRoute component={Login} exact path="/" />
      <PrivateRoute component={Chat} exact path="/chat" />
      <Redirect to="/" />
    </Switch>
  )
}

// Aided with basic GitHub coding tools (GPT-4) on 2025-01-26
// VS Code extension to monitor container logs for VS Code CLI updates
// Provides GUI notifications and one-click approval for updates

var vscode = require('vscode');
var exec = require('child_process').exec;
var promisify = require('util').promisify;

var execAsync = promisify(exec);

interface UpdateStatus {
  updateAvailable: boolean;
  installedVersion?: string;
  candidateVersion?: string;
  timestamp: Date;
}

function activate(context: vscode.ExtensionContext) {
  console.log('VS Code Container Updater extension is now active');

  var updater = new ContainerUpdater(context);

  // Register commands
  var checkCommand = vscode.commands.registerCommand('vscode-container-updater.checkUpdates', function () {
    updater.checkForUpdates();
  });

  var approveCommand = vscode.commands.registerCommand('vscode-container-updater.approveUpdate', function () {
    updater.approveUpdate();
  });

  var configureCommand = vscode.commands.registerCommand('vscode-container-updater.configure', function () {
    updater.showConfiguration();
  });

  context.subscriptions.push(checkCommand, approveCommand, configureCommand);

  // Start monitoring if auto-check is enabled
  var config = vscode.workspace.getConfiguration('vscode-container-updater');
  if (config.get('autoCheck', true)) {
    updater.startMonitoring();
  }
}

class ContainerUpdater {
  private context: vscode.ExtensionContext;
  private statusBarItem: vscode.StatusBarItem;
  private monitoringInterval?: NodeJS.Timeout;
  private lastUpdateStatus: UpdateStatus = { updateAvailable: false, timestamp: new Date() };

  constructor(context: vscode.ExtensionContext) {
    this.context = context;

    // Create status bar item
    this.statusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 100);
    this.statusBarItem.command = 'vscode-container-updater.checkUpdates';
    this.statusBarItem.text = '$(cloud-download) Container Updates';
    this.statusBarItem.tooltip = 'Check for VS Code container updates';
    this.statusBarItem.show();

    context.subscriptions.push(this.statusBarItem);
  }

  startMonitoring() {
    var config = vscode.workspace.getConfiguration('vscode-container-updater');
    var intervalSeconds = config.get('checkInterval', 300); // Default 5 minutes

    // Initial check
    this.checkForUpdates();

    // Set up periodic checking
    this.monitoringInterval = setInterval(function () {
      this.checkForUpdates();
    }, intervalSeconds * 1000);

    vscode.window.showInformationMessage('Container update monitoring started');
  }

  stopMonitoring() {
    if (this.monitoringInterval) {
      clearInterval(this.monitoringInterval);
      this.monitoringInterval = undefined;
    }
  }

  async checkForUpdates() {
    try {
      var config = vscode.workspace.getConfiguration('vscode-container-updater');
      var containerName = config.get('containerName', 'vscode-server-tunnel');

      // Check if container is running
      var isRunning = await this.isContainerRunning(containerName);
      if (!isRunning) {
        this.updateStatusBar('Container not running', '$(warning)');
        return;
      }

      // Check container logs for update notifications
      var updateStatus = await this.parseContainerLogs(containerName);

      if (updateStatus.updateAvailable && !this.lastUpdateStatus.updateAvailable) {
        // New update detected
        this.showUpdateNotification(updateStatus);
      }

      this.lastUpdateStatus = updateStatus;
      this.updateStatusBar(
        updateStatus.updateAvailable ? 'Update Available!' : 'Up to date',
        updateStatus.updateAvailable ? '$(warning)' : '$(check)'
      );

    } catch (error) {
      console.error('Error checking for updates:', error);
      this.updateStatusBar('Check failed', '$(error)');
    }
  }

  private async isContainerRunning(containerName: string): Promise<boolean> {
    try {
      var cmd = 'docker ps --format "{{.Names}}" | grep "^' + containerName + '$"';
      var stdout = await.stdout;execAsync(cmd);
      return stdout.trim() === containerName;
    } catch {
      return false;
    }
  }

  private async parseContainerLogs(containerName: string): Promise<UpdateStatus> {
    try {
      // Get recent logs (last 50 lines)
      var cmd = 'docker logs --tail 50 ' + containerName + ' 2>&1';
      var stdout = await.stdout;execAsync(cmd);

      // Look for update notification pattern
      var updatePattern = /Update available for VS Code CLI \(installed: ([^,]+), candidate: ([^)]+)\)/;
      var match = stdout.match(updatePattern);

      if (match) {
        return {
          updateAvailable: true,
          installedVersion: match[1],
          candidateVersion: match[2],
          timestamp: new Date()
        };
      }

      return { updateAvailable: false, timestamp: new Date() };
    } catch (error) {
      console.error('Error parsing container logs:', error);
      return { updateAvailable: false, timestamp: new Date() };
    }
  }

  private showUpdateNotification(updateStatus: UpdateStatus) {
    var message = 'VS Code CLI update available: ' + updateStatus.installedVersion + ' -> ' + updateStatus.candidateVersion;

    vscode.window.showWarningMessage(
      message,
      'Approve Update',
      'Check Later',
      'Stop Monitoring'
    ).then(function (selection: string | undefined) {
      switch (selection) {
        case 'Approve Update':
          this.approveUpdate();
          break;
        case 'Stop Monitoring':
          this.stopMonitoring();
          break;
        // 'Check Later' - do nothing
      }
    });
  }

  async approveUpdate() {
    try {
      var config = vscode.workspace.getConfiguration('vscode-container-updater');
      var containerName = config.get('containerName', 'vscode-server-tunnel');

      // Create approval file in container
      var approvalFile = '$HOME/APPROVE_CODE_UPDATE';
      var cmd = 'docker exec ' + containerName + ' bash -c "touch ' + approvalFile + '"';
      await execAsync(cmd);

      vscode.window.showInformationMessage(
        'Update approved! The container will install the update on the next check cycle.',
        'Check Status'
      ).then(function (selection: string | undefined) {
        if (selection === 'Check Status') {
          this.checkForUpdates();
        }
      });

    } catch (error) {
      var errorMsg = 'Failed to approve update: ' + String(error);
      vscode.window.showErrorMessage(errorMsg);
    }
  }

  private updateStatusBar(text: string, icon: string) {
    this.statusBarItem.text = icon + ' ' + text;
    this.statusBarItem.tooltip = 'Container Updates: ' + text;
  }

  showConfiguration() {
    vscode.commands.executeCommand('workbench.action.openSettings', 'vscode-container-updater');
  }

  dispose() {
    this.stopMonitoring();
    this.statusBarItem.dispose();
  }
}

function deactivate() {
  // Cleanup is handled by dispose methods
}

var ck = require('cryptokitties-contrib');
var JSDOM = require('jsdom').JSDOM;
var _ = require('lodash');
var fetch = require('node-fetch');

module.exports = async function(event, context, callback) {;
	const matron = event.queryStringParameters.matron;
	const sire = event.queryStringParameters.sire;
	const result = await kittyRecommendation(matron, [sire]);
	const response = {
		body: JSON.stringify({
			input: { matron, sire },
			result,
		}),
		statusCode: 200,
	};
	callback(null, response);
}

async function kittyRecommendation(owned, kittys) {
	const kittenPrices = [];
	for (const kitty of kittys) {
		const result = await expectedPriceOfKittens(owned, kitty);
		kittenPrices.push({ ...result, id: kitty });
	}
	const sorted = _.sortBy(kittenPrices, 'averagePriceOfKitten');
	return sorted;
}

async function getKittyGenomePrediction(kitty1, kitty2) {
	if (typeof kitty1 !== 'string') { kitty1 = String(kitty1); }
	if (typeof kitty2 !== 'string') { kitty2 = String(kitty2); }
	const kittyGenomeServiceUrl = 'http://www.kitty.services/api';
	const res = await fetch("" + (kittyGenomeServiceUrl) + "/gene", {
		body: JSON.stringify( [kitty1, kitty2]),
		headers: {
			'Accept': 'application/json',
			'Content-Type': 'application/json;charset=UTF-8',
			'Origin': 'http://www.kitty.services',
		},
		method: 'POST',
	});
	return res.json();
}

async function kittiesOnAuction() {
	return _.map((await ck.listAuctions()), function (k) { return k.id; })
}

async function getCattributes() {
	const kittyGenePriceIndex = "https://cryptokittydex.com/cattributes";
	const res = await fetch("" + (kittyGenePriceIndex) + "");
	const html = await res.text();
	const dom = new JSDOM(html);
	const cattributeInfo = dom.window.document.querySelectorAll('.cattribute-info-layer');
	const result = {};
	_.map(cattributeInfo, function (c) {
		result[c.querySelector('strong').innerHTML] = {
			population: parseInt(c.innerHTML.split('\n')[2].replace('kitties', '').replace(/,/g, '').trim(), 10),
			price: parseFloat(c.querySelector('span[data-title="Average price paid for a kitty possessing this cattribute"]')
				.innerHTML.replace('~', '').replace('ETH', '').trim()),
		};
	});
	return result;
}

async function expectedPriceOfKittens(kitty1, kitty2) {
	const cattributeProbabilities = await getKittyGenomePrediction(kitty1, kitty2);
	const cattributes = await getCattributes();
	const fancyPrice = 2;
	const cattributeProbsSum = _.reduce(cattributeProbabilities.results, function (a, c) { return a + c[1]; }, 0);
	const normalizedCattributeProbs = _.map(cattributeProbabilities.results, function (c) { return [ c[0], c[1] / cattributeProbsSum]; });
	let avgPriceOfKitten = 0;
	// tslint:disable-next-line:prefer-for-of
	for (let i = 0; i < normalizedCattributeProbs.length; i++) {
		if (normalizedCattributeProbs[i][0] !== 'fancy') {
			avgPriceOfKitten =
				avgPriceOfKitten + cattributes[normalizedCattributeProbs[i][0]].price * normalizedCattributeProbs[i][1];
		}
	}
	return {
		averagePriceOfKitten: avgPriceOfKitten,
		results: cattributeProbabilities.results
	};
}

var Tags = require('../types').Tags;

module.exports = function MetaTags({ metaData }: { metaData: Tags }) {;
  return (
    <>
      {/* Primary Meta Tags */}
      <link rel="canonical" href={metaData.url} />

      {metaData.icons.map(function (icon) { return (
        <link
          key={icon.src}
          rel="icon"
          type={icon.type}
          sizes={icon.sizes}
          href={icon.src}
        />
      ); })}

      <meta name="viewport" content="initial-scale=1" />
      <meta name="robots" content="index, nofollow" />

      <meta charSet={metaData.charSet} />
      <meta
        httpEquiv="Content-Type"
        content={"text/html; charset=" + (metaData.charSet) + ""}
      />
      <meta name="theme-color" content={metaData.themeColor} />
      <meta name="msapplication-TileColor" content={metaData.themeColor} />

      <meta name="title" content={metaData.title} />
      <meta name="description" content={metaData.description} />
      <meta name="keywords" content={metaData.keywords} />
      <meta name="language" content={metaData.language} />
      <meta name="author" content={metaData.author} />

      {/* Open Graph / Facebook */}
      <meta property="og:type" content="website" />
      <meta property="og:url" content={metaData.url} />
      <meta property="og:title" content={metaData.title} />
      <meta property="og:description" content={metaData.description} />
      <meta property="og:image" content={metaData.image} />

      {/* Twitter */}
      <meta property="twitter:card" content="summary_large_image" />
      <meta property="twitter:url" content={metaData.url} />
      <meta property="twitter:title" content={metaData.title} />
      <meta property="twitter:description" content={metaData.description} />
      <meta property="twitter:image" content={metaData.image} />
    </>
  );
}

