        var wrappedHandler = withSentry({ ...options, filterLocal: false }, handler);

        return expect(wrappedHandler(mockEvent, mockContext)).to.eventually.be.fulfilled.then(() => {
          expect(mockSentry.init).to.be.calledOnce;
