            version: String(process.env.AWS_LAMBDA_FUNCTION_VERSION),
            memory_size: String(process.env.AWS_LAMBDA_FUNCTION_MEMORY_SIZE),
            log_group: String(process.env.AWS_LAMBDA_LOG_GROUP_NAME),
