}

interface Logger {
  write(s: string): void;
}

var errorAccessor = 'error-codes';

class Server {
  // Public for the sake of writing tests.
  public app : express.Express;
  public httpServer : http.Server;
  public analyzeApiClient : commentanalyzer_v1alpha1.Commentanalyzer;
  public apiKey : string;
  public port: number;
  public staticPath: string;

  private log: Logger;

  constructor(public config: Config) {
    if (this.config.isProduction) {
      this.log = { write : (_s:string) :function void {} };
    } else {
      this.log = { write : (s:string) :function void { console.log(s); } };
    }

    this.log.write("The config is: " + (JSON.stringify(this.config, null, 2)) + "");
    this.port = parseInt(this.config.port);
    if (!config.staticPath) {
      console.error('staticPath must be specified in the config.');
      return;
    }
    this.staticPath = path.resolve(process.cwd(), config.staticPath);
    this.log.write("Resolved staticPath: " + (this.staticPath) + "");

    this.app = express();

    // Trust proxies so that DoS server can see original IP addresses.
    // DoS Server will hopefully start from the least trustd IPs and work
    // backwards.
    // TODO(ldixon): check is what we want.
    this.app.set('trust proxy', true);

    // TODO(ldixon): explore how to force ssl.

    this.app.use(express.static(this.staticPath));
    // Remove the header that express adds by default.
    this.app.disable('x-powered-by');
    this.app.use(compression());  // Enable gzip
    this.app.use(bodyParser.json());  // Enable json parser

    // Respond to health checks when running on
    // Google AppEngine and ComputeEngine
    this.app.get('/_ah/health', function (_req, res) {
      res.status(200).send('ok');
    });

    // Define an endpoint with CORS enabled to be used by the plugin.
    this.app.options('/plugin/check', cors()) // enable CORS for pre-flight requests.
    this.app.post('/plugin/check', cors(), function (req, res) {
      this.log.write('Received a cross-original check request.');
      this.sendAnalyzeRequest(this.getAnalyzeCommentRequest(req))
        .then((response: AnalyzeCommentResponse) => {
          res.send(response);
        })
        .catch((e: ResponseError) => {
          res.status(e.code).send(e);
        });
    });


    this.app.post('/check', this.verifyRecaptcha(), function (req, res) {
      this.sendAnalyzeRequest(this.getAnalyzeCommentRequest(req))
        .then((response: AnalyzeCommentResponse) => {
          res.send(response);
        })
        .catch((e: ResponseError) => {
          res.status(e.code).send(e);
        });
    });

    this.app.post('/suggest_score', this.verifyRecaptcha(), function (req, res) {
      if(!req.body) {
        // TODO: don't thow error, return an appropriate response code.
        throw Error('No request body.');
      }

      this.log.write("Request: " + (JSON.stringify({headers: req.rawHeaders, body: req.body})) + "");

      var requestData: SuggestCommentScoreData =
        req.body as SuggestCommentScoreData;

      var attributeScores: AttributeScores  = {};
      var attribute = requestData.modelName || this.config.toxicityAttribute;
      attributeScores[attribute] = {
        summaryScore: { value: requestData.commentMarkedAsToxic ? 1 : 0 }
      };
      var request: SuggestCommentScoreRequest = {
        comment: {text: requestData.comment},
        attribute_scores: attributeScores,
        client_token: requestData.sessionId
      };

      this.sendSuggestCommentScoreRequest(request)
        .then((response: SuggestCommentScoreResponse) => {
          res.send(response);
        })
        .catch((e: ResponseError) => {
          res.status(e.code).send(e);
        });
    });

    this.httpServer = http.createServer(this.app);
    this.log.write("created server");
  }

  public start(): Promise<void> {
    return this.createCommentAnalyzerClient()
      .then<void>(function () {
        this.log.write('Analyzer client created');
        return new Promise<void>((F: () => void,
          R: (reason?: Error) => void) => {
          // Start the HTTP server.
          try {
            this.httpServer.listen(this.port, () => {
              this.log.write("HTTP Listening on port " + (this.port) + "");
              F();
            });
          } catch (err) {
            R(err);
          }
        });
      })
      .catch(function (e) {
        console.error("Failed to start: " + e.message);
        throw e;
      });
  }

  stop() : Promise<void> {
    return new Promise<void>(function (F: () => void,
                              _: (impossible_error?: Error) => void) {
      this.httpServer.close(F);
    }     this.httpServer.close(F);
    });
  }

  // Converts a DemoRequest into an AnalyzeCommentRequest that can be sent to
  // the OnePlatform API.
  getAnalyzeCommentRequest(req: DemoRequest): AnalyzeCommentRequest {
    if(!req.body) {
      // TODO: don't thow error, return an appropriate response code.
      throw Error('No request body.');
    }

    this.log.write("Request: " + (JSON.stringify({headers: req.rawHeaders, body: req.body})) + "");

    // The request format translation below exists so that we restrict
    // queries to our website server to hitting the attribute specified
    // in our config (TOXICITY).
    // TODO(rachelrosen): Consider a cleaner way to do this, such as
    // using booleans, to avoid the extra translation code.

    var requestData: AnalyzeCommentData = req.body as AnalyzeCommentData;

    var requestedAttributes: RequestedAttributes = {};
    var attribute = requestData.modelName || this.config.toxicityAttribute;
    requestedAttributes[attribute] = {
      score_type: 'PROBABILITY'
    };

    var context: Context|undefined = undefined;
    if (requestData.articleText) {
      context = {
        article_and_parent_comment: {
          article: { text: requestData.articleText},
        }
      };
      if (context.article_and_parent_comment &&
          requestData.parentComment) {
        context.article_and_parent_comment.parent_comment = {
          text: requestData.parentComment
        };
      }
    }

    return {
      comment: {text: requestData.comment},
      context: context,
      languages: requestData.languages,
      requested_attributes: requestedAttributes,
      do_not_store: requestData.doNotStore,
      client_token: requestData.clientToken,
      session_id: requestData.sessionId,
      community_id: requestData.communityId,
      span_annotations: requestData.spanAnnotations
    };
  }

  sendAnalyzeRequest(request: AnalyzeCommentRequest): Promise<AnalyzeCommentResponse> {
    return new Promise(function (resolve, reject) {
      this.analyzeApiClient.comments.analyze({
        key: this.config.googleCloudApiKey,
        requestBody: request
      },
        (error: Error, response: GaxiosResponse<AnalyzeCommentResponse>) => {
          if (error) {
            reject(error);
            return;
          }
          resolve(response.data);
        });
    });
  }

  sendSuggestCommentScoreRequest(request: SuggestCommentScoreRequest)
    : Promise<SuggestCommentScoreResponse> {
    return new Promise(function (resolve, reject) {
      this.analyzeApiClient.comments.suggestscore({
        key: this.config.googleCloudApiKey,
        requestBody: request
      },
        (error: Error, response: GaxiosResponse<SuggestCommentScoreResponse>) => {
          if (error) {
            reject(error);
            return;
          }
          resolve(response.data);
        });
    });
  }

  createCommentAnalyzerClient(): Promise<void> {
    return new Promise<void>(function (resolve: () => void,
      reject: (reason?: Error | ResponseError) => void) {
      var client = new commentanalyzer_v1alpha1.Commentanalyzer(
        {auth: this.config.googleCloudApiKey});

      if (!(client.comments && client.comments.analyze)) {
        console.error(
          'ERROR: !(client.comments && client.comments.analyze)');
        // Bizarrely, this doesn't cause a discovery error?
        reject(Error('Unknown error loading API: client is b0rken'));
        return;
      }
      this.analyzeApiClient = client;
      resolve();
    }ent = client;
      resolve();
    });
  }

  // Issues a request to reCAPTCHA to verify the request is from a human. Note
  // that this executes only if a valid config is provided.
  verifyRecaptcha() {
    return function (req: express.Request, res: express.Response, next: express.NextFunction) {
      var recaptchaConfig = this.config.recaptchaConfig;

      // Skip reCAPTCHA verification if the requisite config was not provided.
      if (!recaptchaConfig) {
        return next();
      }

      axios.default
        .post('https://www.google.com/recaptcha/api/siteverify', {}, {
          params: {
            secret: recaptchaConfig.secretKey,
            response: req.body.recaptchaToken,
          }
        })
        .then((response: axios.AxiosResponse) => {
          if (response.data[errorAccessor]) {
            res.status(UNAUTHORIZED).send('reCAPTCHA request failed: ' + response.data[errorAccessor]);
          } else if (!response.data.success
                    || Number(response.data.score) < Number(recaptchaConfig.threshold)
                    || response.data.action !== req.body.action) {
            res.status(UNAUTHORIZED).send('Error validating reCAPTCHA. Please use our free API ' +
            'or try again later. See https://github.com/conversationai/perspectiveapi');
          } else {
            return next();
          }
        })
        .catch(next);
    };
  }
}

var BABYLON = require('@babylonjs/core/Legacy/legacy');

var items = require('../lib/gameplay/registry').items;
var blocks = require('../lib/gameplay/registry').blocks;
var gameSettings = require('../values').gameSettings;
var getLayer = require('./main').getLayer;

function setupHand(noa) {
	const scene = getLayer(1);
	const eid = noa.playerEntity;

	const hand = BABYLON.MeshBuilder.CreateBox('hand', { size: 0.08, wrap: true }, scene);

	const handMaterial = new BABYLON.StandardMaterial('hand', scene);
	hand.material = handMaterial;
	hand.rotation.y = -Math.PI / 8;
	hand.position = new BABYLON.Vector3(0.08, -0.08, 0.08);

	const animationBox = new BABYLON.Animation(
		'movement',
		'position.z',
		30,
		BABYLON.Animation.ANIMATIONTYPE_FLOAT,
		BABYLON.Animation.ANIMATIONLOOPMODE_CYCLE
	);

	const keys = [];
	keys.push({
		frame: 0,
		value: 0.08,
	});

	keys.push({
		frame: 20,
		value: 0.085,
	});

	keys.push({
		frame: 40,
		value: 0.08,
	});

	keys.push({
		frame: 60,
		value: 0.075,
	});

	keys.push({
		frame: 80,
		value: 0.08,
	});

	animationBox.setKeys(keys);

	hand.animations.push(animationBox);
	scene.beginAnimation(hand, 0, 100, true);

	noa.on('tick', function () {
		//Updates Player's hand
		var inventory = noa.ents.getState(1, 'inventory');
		var inv = inventory.items;
		var sel = inventory.selected;
		var url = new Array(3);
		var preUrl = new Array(3);

		if (items[inv[sel].id].type == 'block') {
			var block = blocks[inv[sel].id];
			var txt = blocks[block].texture;
			preUrl[0] = txt[txt.length - 1];
			preUrl[1] = txt[txt.length - 1];
			preUrl[2] = txt[0];

			for (var x = 0; x < 3; x++) {
				if ((preUrl[x].startsWith('http://') || preUrl[x].startsWith('https://')) && gameSettings.allowcustom == true) url[x] = preUrl[x];
				else url[x] = 'textures/' + preUrl[x] + '.png';
			}
		} else {
		}
		const mat = new BABYLON.Texture(url[1], scene, false, true, BABYLON.Texture.NEAREST_SAMPLINGMODE);
		handMaterial.ambientTexture = mat;
	});
}

var path = require('path');
var normalizePath = require('vite').normalizePath;
var readAllFile = require('./utils').readAllFile;
var isRegExp = require('./utils').isRegExp;
var isFunction = require('./utils').isFunction;
var fs = require('fs-extra');
var chalk = require('chalk');
var zlib = require('zlib');
var Debug = require('debug');

const debug = Debug.debug('vite-plugin-compression')

const extRE = /\.(js|mjs|json|css|html)$/i

const mtimeCache = new Map<string, number>()

module.exports = function (options: VitePluginCompression = {}): Plugin {;
  let outputPath: string
  let config: ResolvedConfig

  const emptyPlugin: Plugin = {
    name: 'vite:compression',
  }

  const {
    disable = false,
    filter = extRE,
    verbose = true,
    threshold = 1025,
    compressionOptions = {},
    deleteOriginFile = false,
    // eslint-disable-next-line
    success = function () {},
  } = options

  var ext = options.ext;var algorithm = options.algorithm;if (algorithm === 'gzip' && !ext) {
    ext = '.gz'
  }

  if (algorithm === 'brotliCompress' && !ext) {
    ext = '.br'
  }

  if (disable) {
    return emptyPlugin
  }

  debug('plugin options:', options)

  return {
    ...emptyPlugin,
    apply: 'build',
    enforce: 'post',
    configResolved(resolvedConfig) {
      config = resolvedConfig
      outputPath = path.isAbsolute(config.build.outDir)
        ? config.build.outDir
        : path.join(config.root, config.build.outDir)
      debug('resolvedConfig:', resolvedConfig)
    },
    async closeBundle() {
      let files = readAllFile(outputPath) || []
      debug('files:', files)

      if (!files.length) return

      files = filterFiles(files, filter)

      const compressOptions = getCompressionOptions(
        algorithm,
        compressionOptions,
      )

      const compressMap = new Map<
        string,
        { size: number; oldSize: number; cname: string }
      >()

      const handles = files.map(async function (filePath: string) {
        var mtimeMs = await.mtimeMs;fs.stat(filePath)
        if (mtimeMs <= (mtimeCache.get(filePath) || 0) || oldSize < threshold)
          return

        let content = await fs.readFile(filePath)

        if (deleteOriginFile) {
          fs.remove(filePath)
        }

        try {
          content = await compress(content, algorithm, compressOptions)
        } catch (error) {
          config.logger.error('compress error:' + filePath)
        }
        const size = content.byteLength

        const cname = getOutputFileName(filePath, ext)
        compressMap.set(filePath, {
          size: size / 1024,
          oldSize: oldSize / 1024,
          cname: cname,
        })
        await fs.writeFile(cname, content)

        mtimeCache.set(filePath, Date.now())
      })

      return Promise.all(handles).then(function () {
        if (verbose) {
          handleOutputLogger(config, compressMap, algorithm)
          success()
        }
      })
    },
  }
}

function filterFiles(
  files: string[],
  filter: RegExp | (function (file: string) { return boolean; }),
) {
  if (filter) {
    const isRe = isRegExp(filter)
    const isFn = isFunction(filter)
    files = files.filter(function (file) {
      if (isRe) {
        return (filter as RegExp).test(file)
      }
      if (isFn) {
        // eslint-disable-next-line
        return (filter as Function)(file)
      }
      return true
    })
  }
  return files
}

/**
 * get common options
 */
function getCompressionOptions(
  algorithm = '',
  compressionOptions: CompressionOptions = {},
) {
  const defaultOptions: {
    [key: string]: Record<string, any>
  } = {
    gzip: {
      level: zlib.constants.Z_BEST_COMPRESSION,
    },
    deflate: {
      level: zlib.constants.Z_BEST_COMPRESSION,
    },
    deflateRaw: {
      level: zlib.constants.Z_BEST_COMPRESSION,
    },
    brotliCompress: {
      params: {
        [zlib.constants.BROTLI_PARAM_QUALITY]:
          zlib.constants.BROTLI_MAX_QUALITY,
        [zlib.constants.BROTLI_PARAM_MODE]: zlib.constants.BROTLI_MODE_TEXT,
      },
    },
  }
  return {
    ...defaultOptions[algorithm],
    ...compressionOptions,
  } as CompressionOptions
}

/**
 * Compression core method
 * @param content
 * @param algorithm
 * @param options
 */
function compress(
  content: Buffer,
  algorithm: 'gzip' | 'brotliCompress' | 'deflate' | 'deflateRaw',
  options: CompressionOptions = {},
) {
  return new Promise<Buffer>(function (resolve, reject) {
    // @ts-ignore
    zlib[algorithm](content, options, (err, result) =>
      err ? reject(err) : resolve(result),
    )
  })
}

/**
 * Get the suffix
 * @param filepath
 * @param ext
 */
function getOutputFileName(filepath: string, ext: string) {
  const compressExt = ext.startsWith('.') ? ext : "." + (ext) + ""
  return "" + (filepath) + "" + (compressExt) + ""
}

// Packed output logic
function handleOutputLogger(
  config: ResolvedConfig,
  compressMap: Map<string, { size: number; oldSize: number; cname: string }>,
  algorithm: string,
) {
  config.logger.info(
    "\n" + (chalk.cyan('✨ [vite-plugin-compression]:algorithm=' + algorithm)) + "" +
      " - compressed file successfully: ",
  )

  const keyLengths = Array.from(compressMap.keys(), function (name) { return name.length; })

  const maxKeyLength = Math.max(...keyLengths)
  compressMap.forEach(function (value, name) {
    var size = value.size;
var oldSize = value.oldSize;
var cname = value.cname;const rName = normalizePath(cname).replace(
      normalizePath("" + (config.build.outDir) + "/"),
      '',
    )

    const sizeStr = "" + (oldSize.toFixed(2)) + "kb / " + (algorithm) + ": " + (size.toFixed(
      2,
    )) + "kb"

    config.logger.info(
      chalk.dim(path.basename(config.build.outDir) + '/') +
        chalk.blueBright(rName) +
        ' '.repeat(2 + maxKeyLength - name.length) +
        ' ' +
        chalk.dim(sizeStr),
    )
  })
  config.logger.info('\n')
}

var IroColor = require('./color').IroColor;

const roundObject = function (obj) { return Object.keys(obj).reduce((result, key) => {
  result[key] = Math.round(obj[key]);
  return result;
}, {}); };

describe('Color conversion', function () {
  test('Color.rgbToHsv accurately converts rgb to hsv', () => {
    // Pure white
    expect(IroColor.rgbToHsv({r: 255, g: 255, b: 255})).toMatchObject({h: 0, s: 0, v: 100});
    // Pure black
    expect(IroColor.rgbToHsv({r: 0, g: 0, b: 0})).toMatchObject({h: 0, s: 0, v: 0});
    // Pure red
    expect(IroColor.rgbToHsv({r: 255, g: 0, b: 0})).toMatchObject({h: 0, s: 100, v: 100});
    // Pure yellow
    expect(IroColor.rgbToHsv({r: 255, g: 255, b: 0})).toMatchObject({h: 60, s: 100, v: 100});
    // Pure green
    expect(IroColor.rgbToHsv({r: 0, g: 255, b: 0})).toMatchObject({h: 120, s: 100, v: 100});
    // Pure cyan
    expect(IroColor.rgbToHsv({r: 0, g: 255, b: 255})).toMatchObject({h: 180, s: 100, v: 100});
    // Pure blue
    expect(IroColor.rgbToHsv({r: 0, g: 0, b: 255})).toMatchObject({h: 240, s: 100, v: 100});
    // Pure magenta
    expect(IroColor.rgbToHsv({r: 255, g: 0, b: 255})).toMatchObject({h: 300, s: 100, v: 100});
  });

  test('Color.hsvToRgb accurately converts hsv to rgb', () => {
    // Pure white
    expect(IroColor.hsvToRgb({h: 0, s: 0, v: 100})).toMatchObject({r: 255, g: 255, b: 255});
    // Pure black
    expect(IroColor.hsvToRgb({h: 0, s: 0, v: 0})).toMatchObject({r: 0, g: 0, b: 0});
    // Pure red
    expect(IroColor.hsvToRgb({h: 0, s: 100, v: 100})).toMatchObject({r: 255, g: 0, b: 0});
    // Pure yellow
    expect(IroColor.hsvToRgb({h: 60, s: 100, v: 100})).toMatchObject({r: 255, g: 255, b: 0});
    // Pure green
    expect(IroColor.hsvToRgb({h: 120, s: 100, v: 100})).toMatchObject({r: 0, g: 255, b: 0});
    // Pure cyan
    expect(IroColor.hsvToRgb({h: 180, s: 100, v: 100})).toMatchObject({r: 0, g: 255, b: 255});
    // Pure blue
    expect(IroColor.hsvToRgb({h: 240, s: 100, v: 100})).toMatchObject({r: 0, g: 0, b: 255});
    // Pure magenta
    expect(IroColor.hsvToRgb({h: 300, s: 100, v: 100})).toMatchObject({r: 255, g: 0, b: 255});
  });

  test('Color.hslToHsv accurately converts hsl to hsv', () => {
    // Pure white
    expect(IroColor.hslToHsv({h: 0, s: 0, l: 100})).toMatchObject({h: 0, s: 0, v: 100});
    // Pure black
    expect(IroColor.hslToHsv({h: 0, s: 0, l: 0})).toMatchObject({h: 0, s: 0, v: 0});
    // 25% s 25% l
    expect(IroColor.hslToHsv({h: 0, s: 25, l: 25})).toMatchObject({h: 0, s: 40, v: 31.25});
    // 50% s 50% l
    expect(roundObject(IroColor.hslToHsv({h: 0, s: 50, l: 50}))).toMatchObject({h: 0, s: 67, v: 75});
    // 75% s 75% l
    expect(IroColor.hslToHsv({h: 0, s: 75, l: 75})).toMatchObject({h: 0, s: 40, v: 93.75});
  });

  test('Color.hsvToHsl accurately converts hsv to hsl', () => {
    // Pure white
    expect(IroColor.hsvToHsl({h: 0, s: 0, v: 100})).toMatchObject({h: 0, s: 0, l: 100});
    // Pure black
    expect(IroColor.hsvToHsl({h: 0, s: 0, v: 0})).toMatchObject({h: 0, s: 0, l: 0});
    // 25% s 25% l
    expect(IroColor.hsvToHsl({h: 0, s: 40, v: 31.25})).toMatchObject({h: 0, s: 25, l: 25});
    // 50% s 50% l
    expect(roundObject(IroColor.hsvToHsl({h: 0, s: 67, v: 75}))).toMatchObject({h: 0, s: 50, l: 50});
    // 75% s 75% l
    expect(IroColor.hsvToHsl({h: 0, s: 40, v: 93.75})).toMatchObject({h: 0, s: 75, l: 75});
  });

  test('Color.kelvinToRgb accurately converts kelvin temperature to rgb', () => {
    expect(IroColor.kelvinToRgb(3000)).toMatchObject({r: 255, g: 180, b: 108});
    expect(IroColor.kelvinToRgb(6500)).toMatchObject({r: 255, g: 249, b: 254});
    expect(IroColor.kelvinToRgb(12000)).toMatchObject({r: 191, g: 211, b: 255});
    expect(IroColor.kelvinToRgb(18000)).toMatchObject({r: 171, g: 199, b: 255});
    expect(IroColor.kelvinToRgb(24000)).toMatchObject({r: 162, g: 193, b: 255});
    expect(IroColor.kelvinToRgb(30000)).toMatchObject({r: 158, g: 190, b: 255});
    expect(IroColor.kelvinToRgb(36000)).toMatchObject({r: 156, g: 188, b: 255});
  });

  test('Color.rgbToKelvin accurately converts kelvin temperature to rgb', () => {
    expect(Math.round(IroColor.rgbToKelvin({r: 156, g: 188, b: 255}))).toEqual(33972);
    expect(Math.round(IroColor.rgbToKelvin({r: 158, g: 190, b: 255}))).toEqual(29083);
    expect(Math.round(IroColor.rgbToKelvin({r: 191, g: 211, b: 255}))).toEqual(11876);
    expect(Math.round(IroColor.rgbToKelvin({r: 255, g: 249, b: 254}))).toEqual(6489);
  });
});

describe('Color constructor', function () {
  test('Color is a constructor', () => {
    expect(!!IroColor.prototype && !!IroColor.prototype.constructor.name).toBeTruthy();
  });

  test('Color can be constructed with a hsv object', () => {
    var hsv = { h: 360, s: 100, v: 50 };
    var color = new IroColor(hsv);
    expect(color.hsv).toMatchObject(hsv);
  });

  test('Color can be constructed with an rgb object', () => {
    var color = new IroColor({r: 255, g: 255, b: 255});
    expect(color.hsv).toMatchObject({h: 0, s: 0, v: 100});
  });

  test('Color can be constructed with a hsl object', () => {
    var color = new IroColor({h: 0, s: 0, l: 100});
    expect(color.hsv).toMatchObject({h: 0, s: 0, v: 100});
  });

  test('Color can be constructed with an rgb or rgba string', () => {
    var color = new IroColor('rgb(255, 0, 0)');
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});
    var color = new IroColor('rgb(0, 255, 0)');
    expect(color.rgb).toMatchObject({r: 0, g: 255, b: 0});
    var color = new IroColor('rgb(0, 0, 255)');
    expect(color.rgb).toMatchObject({r: 0, g: 0, b: 255});
    var color = new IroColor('rgb(255,255,255)');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgb 255 255 255');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgba(255, 0, 0, 1)');
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});
    var color = new IroColor('rgba(0, 255, 0, 1)');
    expect(color.rgb).toMatchObject({r: 0, g: 255, b: 0});
    var color = new IroColor('rgba(0, 0, 255, 1)');
    expect(color.rgb).toMatchObject({r: 0, g: 0, b: 255});
    var color = new IroColor('rgba(255,255,255,1)');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    var color = new IroColor('rgba 255 255 255 1');
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
  });

  test('Color can be constructed with an rgb or rgba percentage string', () => {
    var color = new IroColor('rgb(100%, 0%, 0%)');
