describe('Color properties', function () {
  test('Color hsv property is readable', () => {
    const hsv = { h: 360, s: 100, v: 50 };
    const color = new IroColor(hsv);
    expect(color.hsv).toMatchObject(hsv);
  });

  test('Color hsv property is writable', () => {
    const hsv = { h: 360, s: 100, v: 50 };
    const color = new IroColor();
    color.hsv = hsv;
    expect(color.hsv).toMatchObject(hsv);
  });

  test('Color alpha property is readable', () => {
    const hsv = { h: 360, s: 100, v: 50, a: .5 };
    const color = new IroColor(hsv);
    expect(color.alpha).toEqual(hsv.a);
  });

  test('Color alpha property is writable', () => {
    const hsv = { h: 360, s: 100, v: 50, a: .5 };
    const color = new IroColor(hsv);
    expect(color.alpha).toEqual(hsv.a);
  });

  test('Color kelvin property is readable', () => {
    const hsv = { h: 360, s: 100, v: 50, a: .5 };
    const color = new IroColor(hsv);
    expect(color.kelvin).toBeGreaterThan(0);
  });

  test('Color kelvin property is writable', () => {
    const hsv = { h: 360, s: 100, v: 50, a: .5 };
    const color = new IroColor(hsv);
    color.kelvin = 6600;
    expect(color.hsv).not.toEqual(hsv);
  });

  test('Color rgb property is readable', () => {
    const color = new IroColor({ h: 360, s: 100, v: 50 });
    expect(color.rgb).toMatchObject({r: 128, g: 0, b: 0});
  });

  test('Color rgb property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.rgb = {r: 128, g: 0, b: 0};
    expect(roundObject(color.hsv)).toMatchObject({ h: 0, s: 100, v: 50 });
  });

  test('Color hsl property is readable', () => {
    const color = new IroColor({ h: 360, s: 100, v: 50 });
    expect(color.hsl).toMatchObject({h: 360, s: 100, l: 25});
  });

  test('Color hsl property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.hsl = {h: 360, s: 100, l: 100};
    expect(roundObject(color.hsv)).toMatchObject({ h: 360, s: 0, v: 100 });
  });

  test('Color rgbString property is readable', () => {
    const color = new IroColor({ h: 360, s: 100, v: 50 });
    expect(color.rgbString).toBe('rgb(128, 0, 0)');
  });

  test('Color rgbString property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.rgbString = 'rgb(128, 0, 0)';
    expect(roundObject(color.hsv)).toMatchObject({ h: 0, s: 100, v: 50 });
  });

  test('Color hslString property is readable', () => {
    const color = new IroColor({ h: 360, s: 100, v: 50 });
    expect(color.hslString).toBe('hsl(360, 100%, 25%)');
  });

  test('Color hslString property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.hslString = 'hsl(360, 100%, 25%)';
    expect(roundObject(color.hsv)).toMatchObject({ h: 360, s: 100, v: 50 });
  });

  test('Color hexString property is readable', () => {
    const color = new IroColor({r: 255, g: 0, b: 0});
    expect(color.hexString).toBe('#ff0000');
  });

  test('Color hexString property is writable', () => {
    const color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.hexString = '#ff0000';
    expect(roundObject(color.rgb)).toMatchObject({r: 255, g: 0, b: 0});
  });
});

describe('Color methods', function () {
  test('Color clone method returns a new color with the same value', () => {
    const color = new IroColor({h: 0, s: 100, v: 100, a: 1});
    const cloneColor = color.clone();
    expect(color.hsv).toMatchObject(cloneColor.hsv);
  });

  test('Color reset method successfully resets the color to its initial value', () => {
    const color = new IroColor('#f00');
    color.hexString = '#fff';
    expect(color.rgb).toMatchObject({r: 255, g: 255, b: 255});
    color.reset();
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});
  });

  test('Color unbind method clears the onChange callback', () => {
    const mockCallback = jest.fn();
    const color = new IroColor('#f00', mockCallback);
    color.unbind();
    color.hexString = '#fff';
    expect(mockCallback).not.toHaveBeenCalled();
  });

  // set() is also used internally by the iro.Color parser, 
  // so the constructor tests already make that this method parses different colors properly
  test('Color set method successfully updates the color value', () => {
    const color = new IroColor({h: 0, s: 100, v: 100, a: 1});
    color.set({h: 360, s: 0, v: 0, a: 0});
    expect(color.hsv).toMatchObject({h: 360, s: 0, v: 0});
  });

  test('Color setChannel method successfully sets hsv channels', () => {
    var color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.setChannel('hsv', 'h', 360);
    expect(color.hsv).toMatchObject({h: 360, s: 0, v: 0});

    var color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.setChannel('hsv', 's', 100);
    expect(color.hsv).toMatchObject({h: 0, s: 100, v: 0});

    var color = new IroColor({h: 0, s: 0, v: 0, a: 0});
    color.setChannel('hsv', 'v', 100);
    expect(color.hsv).toMatchObject({h: 0, s: 0, v: 100});
  });

  test('Color setChannel method successfully sets rgb channels', () => {
    var color = new IroColor({r: 0, g: 0, b: 0});
    color.setChannel('rgb', 'r', 255);
    expect(color.rgb).toMatchObject({r: 255, g: 0, b: 0});

    var color = new IroColor({r: 0, g: 0, b: 0});
    color.setChannel('rgb', 'g', 255);
    expect(color.rgb).toMatchObject({r: 0, g: 255, b: 0});

    var color = new IroColor({r: 0, g: 0, b: 0});
    color.setChannel('rgb', 'b', 255);
    expect(color.rgb).toMatchObject({r: 0, g: 0, b: 255});
  });
});

describe('Color change callback', function () {
  test('Color accepts and fires onChange callback', done => {
    const color = new IroColor({ h: 360, s: 100, v: 100, a: 1 }, () => {
      done();
    });
    color.hsv = { h: 0, s: 0, v: 0, a: 0 };
  });

  test('Color onChange callback receives color and changes params', done => {
    const color = new IroColor({ h: 360, s: 100, v: 100, a: 1 }, (callbackColor, changes) => {
      expect(callbackColor).toBe(color);
      expect(('h' in changes) && ('s' in changes) && ('v' in changes) && ('a' in changes)).toBeTruthy();
      done();
    });
    color.hsv = { h: 0, s: 0, v: 0, a: 0 };
  });

  test('Color onChange changes param provides an accurate diff of color changes', done => {
    const color = new IroColor({ h: 360, s: 100, v: 100, a: 1 }, (color, changes) => {
      // all hsva channels should have changed
      expect(changes).toMatchObject({
        h: true,
        s: true,
        v: true,
        a: true
      });
      done();
    });
    color.hsv = { h: 0, s: 0, v: 0, a: 0 };
  });
});

var uploadFilesToS3 = require('@/wab/server/util/s3-util').uploadFilesToS3;
var ComponentReference = require('@/wab/server/workers/codegen').ComponentReference;
var LoaderEsbuildFatalError = require('@/wab/shared/ApiErrors/errors').LoaderEsbuildFatalError;
import {
  asyncTimeout,
  ensure,
  mkShortUuid,
  omitNils,
  tuple,
  withoutNils,
} from "@/wab/shared/common";
var Sentry = require('@sentry/node');
var fs = require('fs').promises;
var uniq = require('lodash').uniq;
var uniqBy = require('lodash').uniqBy;
var path = require('path');

/**
If some of the components in the build are missing from the bundle, esbuild
will throw an error message that looks like this:

```
Build failed with 1 error:
render__p_qAnx7Cavdb.tsx:69:71: ERROR: Could not resolve "./comp__xeF6Jn1vylil"
```

This means that the component with the uuid `p_qAnx7Cavdb` is trying to import the component with
the uuid `xeF6Jn1vylil`, but that component is missing from the bundle.
 */

// Regex Assisted with basic coding tools 4
const MISSING_COMPONENT_PATTERN =
  /([a-zA-Z0-9]+)__([^:]+)\..*?Could not resolve "\.\/comp__(.*?)"/g;

function projectRefText(ref: ComponentReference) {
  return '"' + (ref.projectName) + '" (ID:' + (ref.projectId) + ")";
}

function buildMissingComponentErrors(
  errors: {
    missingComponent?: ComponentReference;
    importingComponent: ComponentReference;
  }[]
) {
  const projects = uniqBy(
    [
      ...errors.map(function (err) { return err.importingComponent; }),
      ...withoutNils(errors.map(function (err) { return err.missingComponent; })),
    ],
    function (c) { return c.projectId; });
  return "
Found " + (errors.length) + " errors while bundling the components:
" + (errors
  .map(function (err) {
    if (err.missingComponent) {
      return `Component "${err.importingComponent.name}" is trying to import component "${err.missingComponent.name}".`;
    } else {
      return `Component "${err.importingComponent.name}" is trying to import an unknown component.`;
    }
  })
  .join("\n")) + "

Those components are in the following projects:
" + (projects.map((p) => `${projectRefText(p)}`).join("\n")) + "

They are hidden (prefixed with an underscore) or the plasmic-init configuration is improperly set up.

Please make sure that the components are correctly referenced in the Studio.
Contact support if you need help.
  ".trim();
}

// Given a message error throw by the bundling process, this function will attempt to transform it
// into a more user-friendly message.
function transformBundlerErrors(
  msg: string,
  componentRefs: ComponentReference[]
) {
  if (MISSING_COMPONENT_PATTERN.test(msg)) {
    // Reset the regex to the beginning
    MISSING_COMPONENT_PATTERN.lastIndex = 0;
    const allErrors = Array.from(msg.matchAll(MISSING_COMPONENT_PATTERN)).map(
      function (match) {
        const [, , importingUuid, missingUuid] = match;
        const importingComponent = ensure(
          componentRefs.find((comp) => comp.id === importingUuid),
          'Bundle error is referencing a component not present in the site components "' + (importingUuid) + '"'
        );

        const missingComponent = componentRefs.find(
          (comp) => comp.id === missingUuid
        );

        return {
          missingComponent,
          importingComponent,
        };
      }
    );

    return buildMissingComponentErrors(allErrors);
  }

  return null;
}

const RE_TSX_FILE = /([\w-]+\.tsx)/g;

function getAllTsxFilesFromString(err: string) {
  return uniq(Array.from(err.matchAll(RE_TSX_FILE)).map(function (match) { return match[0]; }));
}

export async function uploadErrorFiles(err: Error, dir: string) {
  const files = getAllTsxFilesFromString(err.toString());
  if (files.length === 0) {
    return;
  }

  const readFile = async function (file: string) {
    const filePath = path.join(dir, file);
    try {
      return (await fs.readFile(filePath)).toString();
    } catch (err2) {
      console.log("Error reading " + (filePath) + "", err2);
      return undefined;
    }
  };

  const fileContents = await Promise.all(
    files.map(async function (f) { return tuple(f, await readFile(f)); })
  );

  const filesDict = omitNils(Object.fromEntries(fileContents));

  if (Object.keys(filesDict).length === 0) {
    return;
  }
  const prefix = "bundling-errors/" + (mkShortUuid()) + "";
  await uploadFilesToS3({
    bucket: "plasmic-errors",
    key: prefix,
    files: filesDict,
  });

  console.log(
    "Error files: " + (Object.keys(filesDict)
      .map(
        function (f) { return `https://plasmic-errors.s3-us-west-2.amazonaws.com/${prefix}/${f}`; })
      .join(" , ")) + ""
  );

  return prefix;
}

/**
 * This is a list of error messages that esbuild throws that will persist even in the
 * next build attempt. If those errors are detected, we will kill this process so that
 * the pod can be restarted and the build can be retried in a clean environment.
 *
 * Reference: https://github.com/evanw/esbuild/issues/2884
 **/

const ESBUILD_FATAL_ERROR_PATTERNS = [
  "The service is no longer running",
  "The service was stopped",
];

export async function checkEsbuildFatalError(msg: string) {
  const isFatal = ESBUILD_FATAL_ERROR_PATTERNS.some(function (pattern) { return msg.includes(pattern); });

  if (isFatal) {
    Sentry.captureException(new LoaderEsbuildFatalError(msg));
    await asyncTimeout(1000); // Give some time for the error to be logged
    process.exit(1); // Exit the process to force a restart
  }
}

// Aided with basic GitHub coding tools

/**
 * Docker Service - Manages Docker containers and Docker Compose operations
 * Quản lý Docker containers và các thao tác Docker Compose
 */

var Tool = require('@modelcontextprotocol/sdk/types.js').Tool;
var Service = require('./base-service.js').Service;
var spawn = require('child_process').spawn;
var exec = require('child_process').exec;
var promisify = require('util').promisify;
var path = require('path');
var fs = require('fs/promises');

var execAsync = promisify(exec);

/**
 * Docker Container Status
 * Trạng thái của Docker container
 */
export interface ContainerStatus {
    name: string;
    status: 'running' | 'stopped' | 'paused' | 'restarting' | 'removing' | 'created' | 'exited' | 'dead';
    health: 'healthy' | 'unhealthy' | 'starting' | 'none';
    uptime: string;
    ports: string[];
    image: string;
}

/**
 * Docker Compose Service Definition
 * Định nghĩa service trong Docker Compose
 */
export interface ComposeService {
    name: string;
    image: string;
    ports: string[];
    volumes: string[];
    environment: Record<string, string>;
    healthCheck?: {
        test: string[];
        interval: string;
        timeout: string;
        retries: number;
    };
}

/**
 * Docker Service Implementation
 * Implements Docker container management operations
 */
class DockerService implements Service {
    readonly namespace = 'docker';
    readonly name = 'Docker Management Service';
    readonly version = '1.0.0';
    readonly description = 'Manages Docker containers, images, and Docker Compose operations';

    private composePath: string;
    private projectName: string;

    constructor(composePath?: string, projectName?: string) {
        this.composePath = composePath || path.join(process.cwd(), 'docker-compose.yml');
        this.projectName = projectName || 'mcp';
    }

    /**
     * List all available Docker management tools
     * Liệt kê tất cả các công cụ quản lý Docker
     */
    async listTools(): Promise<{ tools: Tool[] }> {
        return {
            tools: [
                {
                    name: 'docker_ps',
                    description: 'List all Docker containers with their status',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            all: {
                                type: 'boolean',
                                description: 'Show all containers (default: false - only running)',
                                default: false
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_up',
                    description: 'Start Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            services: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific services to start (optional - all services if not specified)'
                            },
                            detached: {
                                type: 'boolean',
                                description: 'Run in detached mode',
                                default: true
                            },
                            build: {
                                type: 'boolean',
                                description: 'Build images before starting',
                                default: false
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_down',
                    description: 'Stop and remove Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            volumes: {
                                type: 'boolean',
                                description: 'Remove volumes as well',
                                default: false
                            },
                            removeImages: {
                                type: 'string',
                                enum: ['all', 'local', 'none'],
                                description: 'Remove images (all, local, or none)',
                                default: 'none'
                            }
                        }
                    }
                },
                {
                    name: 'docker_compose_restart',
                    description: 'Restart Docker Compose services',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            services: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific services to restart (optional)'
                            }
                        }
                    }
                }, {
                    name: 'docker_logs',
                    description: 'Get logs from Docker containers',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            container: {
                                type: 'string',
                                description: 'Container name or ID'
                            },
                            tail: {
                                type: 'number',
                                description: 'Number of lines to show from the end of logs',
                                default: 100
                            },
                            follow: {
                                type: 'boolean',
                                description: 'Follow log output',
                                default: false
                            }
                        },
                        required: ['container']
                    }
                },
                {
                    name: 'docker_health_check',
                    description: 'Check health status of all services',
                    inputSchema: {
                        type: 'object',
                        properties: {}
                    }
                }, {
                    name: 'docker_exec',
                    description: 'Execute command in running container',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            container: {
                                type: 'string',
                                description: 'Container name or ID'
                            },
                            command: {
                                type: 'string',
                                description: 'Command to execute'
                            },
                            interactive: {
                                type: 'boolean',
                                description: 'Run in interactive mode',
                                default: false
                            }
                        },
                        required: ['container', 'command']
                    }
                },
                {
                    name: 'docker_stats',
                    description: 'Get resource usage statistics for containers',
                    inputSchema: {
                        type: 'object',
                        properties: {
                            containers: {
                                type: 'array',
                                items: { type: 'string' },
                                description: 'Specific containers to monitor (optional - all if not specified)'
                            }
                        }
                    }
                }
            ]
        };
    }

    /**
     * Execute Docker management tools
     * Thực thi các công cụ quản lý Docker
     */
    async callTool(name: string, args: any): Promise<any> {
        try {
            switch (name) {
                case 'docker_ps':
                    return await this.listContainers(args.all || false);

                case 'docker_compose_up':
                    return await this.composeUp(args.services, args.detached !== false, args.build || false);

                case 'docker_compose_down':
                    return await this.composeDown(args.volumes || false, args.removeImages || 'none');

                case 'docker_compose_restart':
                    return await this.composeRestart(args.services);

                case 'docker_logs':
                    return await this.getLogs(args.container, args.tail || 100, args.follow || false);

                case 'docker_health_check':
                    return await this.healthCheck();

                case 'docker_exec':
                    return await this.execCommand(args.container, args.command, args.interactive || false);

                case 'docker_stats':
                    return await this.getStats(args.containers);

                default:
                    throw new Error("Unknown Docker tool: " + (name) + "");
            }
        } catch (error) {
            throw new Error("Docker tool '" + (name) + "' failed: " + (error instanceof Error ? error.message : String(error)) + "");
        }
    }

  /**
   * List Docker containers
   * Liệt kê các Docker containers
   */  private async listContainers(all: boolean = false): Promise<{ containers: ContainerStatus[] }> {
        var command = all ? 'docker ps -a --format "{{.Names}}\t{{.Status}}\t{{.Ports}}\t{{.Image}}"'
            : 'docker ps --format "{{.Names}}\t{{.Status}}\t{{.Ports}}\t{{.Image}}"';

        var stdout = await.stdout;execAsync(command);
        var lines = stdout.trim().split('\n');

        var containers: ContainerStatus[] = [];
        for (var line of lines) {
            if (line.trim()) {
                var parts = line.split('\t');
                if (parts.length >= 4) {
                    var [name, status, ports, image] = parts;

                    // Get health status
                    var health: ContainerStatus['health'] = 'none';
                    try {
                        var { stdout: healthOutput } = await execAsync("docker inspect --format='{{.State.Health.Status}}' " + (name.trim()) + "");
                        var healthStatus = healthOutput.trim();
                        if (healthStatus && healthStatus !== '<no value>') {
                            health = healthStatus as ContainerStatus['health'];
                        }
                    } catch {
                        // Health check not available
                    }

                    containers.push({
                        name: name.trim(),
                        status: this.parseContainerStatus(status.trim()),
                        health,
                        uptime: status.trim(),
                        ports: ports ? ports.split(',').map(function p { return p.trim(); }) : [],
                        image: image.trim()
                    });
                }
            }
        }

        return { containers };
    }

    /**
     * Start Docker Compose services
     * Khởi động các dịch vụ Docker Compose
     */
    private async composeUp(services?: string[], detached: boolean = true, build: boolean = false): Promise<{ success: boolean; message: string; output: string }> {
        var command = 'docker compose -f "' + (this.composePath) + '"';

        if (build) {
            command += ' up --build';
        } else {
            command += ' up';
        }

        if (detached) {
            command += ' -d';
        }

        if (services && services.length > 0) {
            command += " " + (services.join(' ')) + "";
        }

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(command);
            return {
                success: true,
                message: "Docker Compose services started successfully",
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: "Failed to start Docker Compose services: " + (error.message) + "",
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Stop Docker Compose services
     * Dừng các dịch vụ Docker Compose
     */
    private async composeDown(volumes: boolean = false, removeImages: string = 'none'): Promise<{ success: boolean; message: string; output: string }> {
        var command = 'docker compose -f "' + (this.composePath) + '" down';

        if (volumes) {
            command += ' -v';
        }

        if (removeImages !== 'none') {
            command += " --rmi " + (removeImages) + "";
        }

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(command);
            return {
                success: true,
                message: 'Docker Compose services stopped successfully',
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: "Failed to stop Docker Compose services: " + (error.message) + "",
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Restart Docker Compose services
     * Khởi động lại các dịch vụ Docker Compose
     */
    private async composeRestart(services?: string[]): Promise<{ success: boolean; message: string; output: string }> {
        var command = 'docker compose -f "' + (this.composePath) + '" restart';

        if (services && services.length > 0) {
            command += " " + (services.join(' ')) + "";
        }

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(command);
            return {
                success: true,
                message: 'Docker Compose services restarted successfully',
                output: stdout + stderr
            };
        } catch (error: any) {
            return {
                success: false,
                message: "Failed to restart Docker Compose services: " + (error.message) + "",
                output: error.stdout + error.stderr
            };
        }
    }

    /**
     * Get container logs
     * Lấy logs từ container
     */
    private async getLogs(container: string, tail: number = 100, follow: boolean = false): Promise<{ logs: string; container: string }> {
        var command = "docker logs --tail " + (tail) + "";

        if (follow) {
            command += ' -f';
        }

        command += " " + (container) + "";

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(command);
            return {
                container,
                logs: stdout + stderr
            };
        } catch (error: any) {
            throw new Error("Failed to get logs for container " + (container) + ": " + (error.message) + "");
        }
    }

    /**
     * Health check for all services
     * Kiểm tra sức khỏe của tất cả các dịch vụ
     */
    private async healthCheck(): Promise<{ services: Array<{ name: string; status: string; health: string }> }> {
        var containers = await.containers;this.listContainers(false);

        var services = containers.map(function container { return ({
            name: container.name,
            status: container.status,
            health: container.health
        }); });

        return { services };
    }

    /**
     * Execute command in container
     * Thực thi lệnh trong container
     */
    private async execCommand(container: string, command: string, interactive: boolean = false): Promise<{ output: string; container: string; command: string }> {
        var dockerCommand = 'docker exec';

        if (interactive) {
            dockerCommand += ' -it';
        }

        dockerCommand += " " + (container) + " " + (command) + "";

        try {
            var stdout = await.stdout;
var stderr = await.stderr;execAsync(dockerCommand);
            return {
                container,
                command,
                output: stdout + stderr
            };
        } catch (error: any) {
            throw new Error("Failed to execute command in container " + (container) + ": " + (error.message) + "");
        }
    }

    /**
     * Get container resource statistics
     * Lấy thống kê tài nguyên của container
     */
    private async getStats(containers?: string[]): Promise<{ stats: string }> {
        var command = 'docker stats --no-stream --format "table {{.Container}}\t{{.CPUPerc}}\t{{.MemUsage}}\t{{.NetIO}}\t{{.BlockIO}}"';

        if (containers && containers.length > 0) {
            command += " " + (containers.join(' ')) + "";
        }

        try {
            var stdout = await.stdout;execAsync(command);
            return { stats: stdout };
        } catch (error: any) {
            throw new Error("Failed to get container stats: " + (error.message) + "");
        }
    }

    /**
     * Parse container status from Docker output
     * Phân tích trạng thái container từ output của Docker
     */
    private parseContainerStatus(status: string): ContainerStatus['status'] {
        var statusLower = status.toLowerCase();

        if (statusLower.includes('up')) return 'running';
        if (statusLower.includes('exited')) return 'exited';
        if (statusLower.includes('created')) return 'created';
        if (statusLower.includes('restarting')) return 'restarting';
        if (statusLower.includes('removing')) return 'removing';
        if (statusLower.includes('paused')) return 'paused';
        if (statusLower.includes('dead')) return 'dead';

        return 'stopped';
    }

    /**
     * Check if Docker is available
     * Kiểm tra xem Docker có khả dụng không
     */
    async isDockerAvailable(): Promise<boolean> {
        try {
            await execAsync('docker --version');
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Check if Docker Compose is available
     * Kiểm tra xem Docker Compose có khả dụng không
     */
    async isDockerComposeAvailable(): Promise<boolean> {
        try {
            await execAsync('docker compose version');
            return true;
        } catch {
            return false;
        }
    }
}

var Notice = require('obsidian').Notice;

function copyImageToClipboard(svg: SVGElement) {
    const canvas = createCanvas(svg); 
    const img = generateImage(svg, canvas, function () { 
        canvas.toBlob((blob: any) => { 
            const item = new ClipboardItem({ "image/png": blob });
            navigator.clipboard.write([item]); 
            new Notice('Screenshot copied to the clipboard.')
        });
    });
}

function createCanvas(svg: SVGElement): HTMLCanvasElement {
    const canvas = document.createElement("canvas");
    canvas.width = svg.clientWidth;
    canvas.height = svg.clientHeight;
    return canvas;
}

function generateImage(svg: SVGElement, canvas: HTMLCanvasElement, callback: function () { return void; }): HTMLImageElement {
    var ctx = canvas.getContext("2d");
    return drawInlineSVG(ctx, svg, callback);
}

function drawInlineSVG(ctx: CanvasRenderingContext2D, svg: SVGElement, callback: function () { return void; }): HTMLImageElement {

    // get svg data
    const xml = new XMLSerializer().serializeToString(svg);

    // make it base64
    const svg64 = btoa(unescape(encodeURIComponent(xml)))

    const b64Start = 'data:image/svg+xml;base64,';

    // prepend a "header"
    const image64 = b64Start + svg64;

    const img = new Image();
    // set it as the source of the img element
    img.onload = function() {
        // draw the image onto the canvas
        ctx.drawImage(img, 0, 0);
        callback();
    }
    img.src = image64;
    return img;
}

var Vector = require('../math/vector').Vector;
var minus = require('../math/minus').minus;

const check = function (threshold: number, startI: number, endI: number, paths: number[]) {
	let max = 0;
	let maxI = 0;
	// 拿到基础向量
	const baseVector = new Vector(minus(paths[endI], paths[startI]), minus(paths[endI + 1], paths[startI + 1]));
	for (let i = startI + 2; i < endI; i += 2) {
		// 获取每个点基于起始和结束位置的向量
		const vectorToStart = new Vector(minus(paths[i], paths[startI]), minus(paths[i + 1], paths[startI + 1]));
		const vectorToEnd = new Vector(minus(paths[i], paths[endI]), minus(paths[i + 1], paths[endI + 1]));
		let distance = 0;
		// 与起始或结束点重合的点直接跳过
		if (!vectorToStart.isZero && !vectorToEnd.isZero) {
			// 边界情况：投影分量的模大于基础向量，说明途径点在起始点或结束点之外，不能单纯靠垂直分量来抽稀
			const prjToStart = Vector.projected(vectorToStart, baseVector);
			const prjToEnd = Vector.projected(vectorToEnd, baseVector);
			if (prjToStart.modulo > baseVector.modulo) {
				distance = prjToStart.modulo;
			} else if (prjToEnd.modulo > baseVector.modulo) {
				distance = prjToEnd.modulo;
			} else {
				distance = Vector.plumb(vectorToStart, baseVector).modulo;
			}
			if (distance > max) {
				max = distance;
				maxI = i;
			}
		}
	}
	if (max <= threshold) {
		paths.splice(startI + 2, endI - startI - 2);
	} else {
		if (maxI < endI - 2) {
			check(threshold, maxI, endI, paths);
		}
		if (maxI > startI + 2) {
			check(threshold, startI, maxI, paths);
		}
	}
};

const douglasPeucker = function (threshold: number, pathArr: number[]) {
	const pathCopy = pathArr.slice();
	check(threshold, 0, pathCopy.length - 2, pathCopy);
	return pathCopy;
};

var React = require('react');
var Link = require('react-router-dom').Link;
var useHistory = require('react-router-dom').useHistory;

var style = require('../style').style;

function pathnameToParams(pathname: string): [string, string][] {
  // Remove first empty string: "/connections" gets split to "" and "connections"
  const pathnameArray = pathname.split("/").slice(1);
  const params: [string, string][] = [];
  // Fill params array with pairs from pathnameArray
  // Even numbers are keys and odd ones are values
  pathnameArray.forEach(function (key, i, pathnameArray) {
    const value = pathnameArray[i + 1];
    if (!key || !value) return;
    if (i % 2 === 0) {
      params.push([key, value]);
    }
  });

  return params;
}

function paramsToBreadcrumbs(params: [string, string][]): [string, string][] {
  if (params.length === 0) return [];

  const lastKey = params.slice(-1)[0][0];
  // Turn "connections" into "Connection"
  const label = lastKey.charAt(0).toUpperCase() + lastKey.slice(1, -1);
  // Join key and values to look like url
  const fullPath = "/" + params.flat().join("/");
  const newBreadcrumb: [string, string] = [label, fullPath];
  // Remove newBreadcrumb params from array
  const nextParams = params.slice(0, -1);

  return [...paramsToBreadcrumbs(nextParams), newBreadcrumb];
}

function Navigation(): JSX.Element {
  var pathname = useHistory.pathname;().location;
  const params = pathnameToParams(pathname);
  const breadcrumbs = paramsToBreadcrumbs(params);

  return (
    <nav className="my-5">
      <Link to="/" className={"" + (style.button) + " ml-0"}>
        Home
      </Link>
      {breadcrumbs.map(function ([label, path]) { return (
        <React.Fragment key={label}>
          <span className="mr-2">→</span>
          <Link to={path} className={style.button}>
            {label}
          </Link>
        </React.Fragment>
      ); })}
    </nav>
  );
}

var IInputs = require('./generated/ManifestTypes').IInputs;
var IOutputs = require('./generated/ManifestTypes').IOutputs;
var Injectable = require('@angular/core').Injectable;
