export * from './objects';

var resolve = require('path').resolve;
var basename = require('path').basename;
var fs = require('fs');
var os = require('os');
var parseEnv = require('parse-dotenv');
var globby = require('globby');
var pkgConf = require('pkg-conf');

const DEFAULT_ENV_PATH = resolve(process.cwd(), ".env");
const DEFAULT_SAMPLE_ENV = resolve(process.cwd(), ".env.example");

interface EnvObject {
	[key: string]: any;
}

interface Config {
	preserve?: [string];
	emptyLines?: boolean;
	comments?: boolean;
}

const fileExists = function (path: string) { return fs.existsSync(path); };

const getObjKeys = function (obj: object) { return Object.keys(obj); };

const envToString = function (parsed: EnvObject) { return getObjKeys(parsed)
		.map(key => "" + (key) + "=" + (parsed[key] || "") + "")
		.join(os.EOL)
		.replace(/(__\w+_\d+__=)/g, ""); };

const writeToSampleEnv = function (path: string, parsedEnv: object) {
	try {
		fs.writeFileSync(path, envToString(parsedEnv));
	} catch (e) {
		throw new Error("Sync failed. " + (e.message) + "");
	}
};

const emptyObjProps = function (obj: EnvObject) {
	const objCopy = { ...obj };
	Object.keys(objCopy).forEach(key => {
		if (objCopy[key].includes("#")) {
			if (objCopy[key].match(/(".*"|'.*')/g)) {
				const objArr = objCopy[key].split(/(".*"|'.*')/);
				objCopy[key] = objArr.slice(-1)[0].trim();
			} else {
				const objArr = objCopy[key].split("#");
				objCopy[key] = "#" + (objArr.slice(-1)[0]) + "";
			}

			return;
		}

		/* istanbul ignore else */
		if (!key.startsWith("__COMMENT_")) {
			objCopy[key] = "";
		}
	});

	return objCopy;
};

const getUniqueVarsFromEnvs = async function (
	env: EnvObject,
	envExample: EnvObject,
	config: Config = {}
) {
	let ignoreKeys = config.preserve || [];

	const uniqueKeys = new Set(getObjKeys(env));
	const uniqueKeysArray: Array<string> = Array.from(uniqueKeys);

	let uniqueFromSource = uniqueKeysArray.map((key: string) => {
		if (key.startsWith("__COMMENT_")) return { [key]: env[key] };
		return { [key]: envExample[key] || "" };
	});

	let presevedVars = getObjKeys(envExample)
		.map(key => ({ [key]: envExample[key] }))
		.filter(env => {
			return ignoreKeys.length && ignoreKeys.includes(getObjKeys(env)[0]);
		});

	return [...uniqueFromSource, ...presevedVars];
};

const syncWithSampleEnv = async function (
	envPath: string,
	envExamplePath: string,
	initialConfig?: Config
) {
	// We do this so we can pass it via test as well
	let config: Config = initialConfig || (await pkgConf("sync-dotenv")) as any;

	// Set defaults
	config.comments = typeof config.comments === 'undefined' ? true : config.comments;
	config.emptyLines = typeof config.emptyLines === 'undefined' ? true : config.comments;

	let sourceEnv = emptyObjProps(
		parseEnv(envPath, { emptyLines: !!config.emptyLines, comments: !!config.comments })
	);
	let targetEnv = parseEnv(envExamplePath);

	const uniqueVars = await getUniqueVarsFromEnvs(sourceEnv, targetEnv, config);
	let envCopy: EnvObject = {};
	uniqueVars.forEach(env => {
		let [key] = getObjKeys(env);
		envCopy[key] = env[key];
	});

	writeToSampleEnv(envExamplePath, envCopy);
};

const exit = function (message: string, code: number = 1) { return Promise.reject({ message, code }); };

const syncEnv = async (
	sampleEnv?: string,
	source?: string,
	samples?: string
): Promise<{ msg: string; code: number } | string> => {
	if (sampleEnv && (sampleEnv === ".env" || basename(sampleEnv) === ".env"))
		return exit("Cannot sync .env with .env");

	const SAMPLE_ENV_PATHS: string[] = !samples
		? [resolve(process.cwd(), sampleEnv || DEFAULT_SAMPLE_ENV)]
		: globby
			.sync(samples)
			.map(function (sample: string) { return resolve(process.cwd(), sample); });

	let envPath = source
		? fileExists(source)
			? source
			: null
		: DEFAULT_ENV_PATH;

	if (envPath === null) return exit("" + (source) + " not found");

	if (!source && !fileExists(envPath)) return exit(".env doesn't exists");

	if (!SAMPLE_ENV_PATHS.length)
		return exit("" + (samples) + " did not match any file");

	if (!fileExists(SAMPLE_ENV_PATHS[0]))
		return exit("" + (sampleEnv || basename(DEFAULT_SAMPLE_ENV)) + " not found");

	const sourcePath = envPath;

	for (let samplePath of SAMPLE_ENV_PATHS) {
		await syncWithSampleEnv(sourcePath, samplePath);
	}

	return Promise.resolve(SAMPLE_ENV_PATHS.join(" "));
};

var jwt = require('jsonwebtoken');
var AuthenticationError = require('apollo-server').AuthenticationError;
var ForbiddenError = require('apollo-server').ForbiddenError;

function getAppKey() {
  return process.env.APP_KEY
}

function initAuth({ req }, db) {
  const getUser = function (fail = false) { return getAuthUserFromReq(req, db, fail)

  return {
    getUser,
    getUserId: () => getUser().then(user => user.id),
    maybeGetUser: () => getUser(false),
    generateToken: generateToken
  }; }}

export async function getAuthUserFromReq(req: any, db: any, shouldFail = true) {
  var authorization = req.headers.authorization;const noAuthorization = !authorization || authorization.indexOf('Bearer') === -1

  if (noAuthorization && shouldFail) throw new AuthenticationError('You must supply a JWT for authorization!')
  else if (noAuthorization) return null 

  // cache user via req object in case there are repeat calls to $getUser
  if (req.user) return req.user 

  const token = authorization.replace('Bearer ', '')
  const user = await getAuthUser(db.$connection, token)
  req.user = user

  return req.user
}

export async function getAuthUser(connection: any, token: any) {
  let userId
  try {
    userId = jwt.verify(token, getAppKey()).userId
  } catch (err) {
    throw new ForbiddenError('You are not authorized.')
  }

  const user = await connection('users').where('id', userId).first()
  if (!user) throw new AuthenticationError('Encrypted user does not exist.')
  return user
}

function generateToken (userId) {
  return jwt.sign({ userId }, getAppKey())
}

var Injectable = require('@angular/core').Injectable;
var Firestore = require('@angular/fire/firestore').Firestore;
var collection = require('@angular/fire/firestore').collection;
var collectionData = require('@angular/fire/firestore').collectionData;
var addDoc = require('@angular/fire/firestore').addDoc;
var serverTimestamp = require('@angular/fire/firestore').serverTimestamp;
var doc = require('@angular/fire/firestore').doc;
var setDoc = require('@angular/fire/firestore').setDoc;
var getDoc = require('@angular/fire/firestore').getDoc;
var getDocs = require('@angular/fire/firestore').getDocs;
var deleteDoc = require('@angular/fire/firestore').deleteDoc;
var inject = require('@angular/core').inject;
var Observable = require('rxjs').Observable;
var Game = require('./game.service').Game;
var Round = require('./game.service').Round;
var Trick = require('./game.service').Trick;
var Card = require('./game.service').Card;
var Player = require('./game.service').Player;

//the code in this section was largely Composed with basic coding tools
// here is the link to the firbase project:
// https://console.firebase.google.com/u/0/project/lexemwellioeuchre/overview
@Injectable({
  providedIn: 'root'
})
class StorageService {
  firestore: Firestore = inject(Firestore);

  async saveGame(game: Game): Promise<void> {
    try {
      const gameCollection = collection(this.firestore, 'games');

      // Add the game document (basic game details)
      const gameDocRef = await addDoc(gameCollection, {
        roundCounter: game.roundCounter,
        score: game.score,
        timestamp: serverTimestamp(), // Add the timestamp
      });

      console.log('Game document created:', gameDocRef.id);

      // Save players as a subcollection
      const playersCollection = collection(gameDocRef, 'players');
      for (const player of game.players) {
        await setDoc(doc(playersCollection, player.index.toString()), {
          name: player.name,
          index: player.index,
        });
      }

      // Save the current round as a subcollection
      const roundsCollection = collection(gameDocRef, 'rounds');
      const roundDocRef = await addDoc(roundsCollection, {
        kittyCard: {
          suit: game.currentRound.kittyCard.suit,
          rank: game.currentRound.kittyCard.rank,
          photo: game.currentRound.kittyCard.photo,
        },
        dealer: {
          name: game.currentRound.dealer.name,
          index: game.currentRound.dealer.index,
        },
        caller: game.currentRound.caller
          ? {
              name: game.currentRound.caller.name,
              index: game.currentRound.caller.index,
            }
          : null,
        outPlayer: game.currentRound.outPlayer
          ? {
              name: game.currentRound.outPlayer.name,
              index: game.currentRound.outPlayer.index,
            }
          : null,
        trumpSuit: game.currentRound.trumpSuit,
        trickCounter: game.currentRound.trickCounter,
        tricksWon: game.currentRound.tricksWon,
        tricksWonPlayer: [...game.currentRound.tricksWonPlayer],
        passTrumpCount: game.currentRound.passTrumpCount,
        switchTime: game.currentRound.switchTime,
      });

      // Save the current trick as a subcollection
      const tricksCollection = collection(roundDocRef, 'tricks');
      await addDoc(tricksCollection, {
        leadPlayer: {
              name: game.currentRound.currentTrick.leadPlayer!.name,
              index: game.currentRound.currentTrick.leadPlayer!.index,
            },
        cardLed: game.currentRound.currentTrick.cardLed
          ? {
              suit: game.currentRound.currentTrick.cardLed.suit,
              rank: game.currentRound.currentTrick.cardLed.rank,
              photo: game.currentRound.currentTrick.cardLed.photo,
            }
          : null,
        cardsPlayed: game.currentRound.currentTrick.cardsPlayed.map(function (card) { return card
            ? {
                suit: card.suit,
                rank: card.rank,
                photo: card.photo,
              }
            : null; }),
        currentPlayer: {
              name: game.currentRound.currentTrick.currentPlayer!.name,
              index: game.currentRound.currentTrick.currentPlayer!.index,
            },
        playedCounter: game.currentRound.currentTrick.playedCounter,
      });

        // Save each player's hand as a document
      const handsCollection = collection(roundDocRef, 'hands');
      for (let playerIndex = 0; playerIndex < game.currentRound.hands.length; playerIndex++) {
        const playerHand = game.currentRound.hands[playerIndex];

        // Store the hand as a document containing a list of cards
        await setDoc(doc(handsCollection, playerIndex.toString()), {
          cards: playerHand.map(function (card) { return ({
            suit: card.suit,
            rank: card.rank,
            photo: card.photo,
          }); }),
        });
      }


      console.log('Game saved successfully.');
    } catch (error) {
      console.error('Error saving game:', error);
      throw error;
    }
  }

  async getGame(gameId: string): Promise<Game | null> {
    try {
      // Reference the game document
      const gameDocRef = doc(this.firestore, 'games', gameId);
      const gameDocSnap = await getDoc(gameDocRef);

      if (!gameDocSnap.exists()) {
        console.error('Game not found');
        return null;
      }

      // Basic game details
      const gameData = gameDocSnap.data();
      const game: Game = {
        players: [],
        roundCounter: gameData['roundCounter'],
        score: gameData['score'],
        currentRound: {} as Round, // Placeholder for now
        //winner: gameData['winner'], // added by EJW
      };

      // Fetch players subcollection
      const playersCollection = collection(gameDocRef, 'players');
      const playersSnap = await getDocs(playersCollection);
      const players: Player[] = playersSnap.docs.map(function (docSnap) {
        const playerData = docSnap.data();
        return {
          name: playerData['name'],
          index: playerData['index'],
          isBot: playerData['isBot'],
        };
      });
      game.players = players;

      // Fetch rounds subcollection
      const roundsCollection = collection(gameDocRef, 'rounds');
      const roundsSnap = await getDocs(roundsCollection);

      if (roundsSnap.empty) {
        console.error('No rounds found');
        return null;
      }

      const currentRoundDoc = roundsSnap.docs[roundsSnap.docs.length - 1]; // Assuming the current round is the latest round
      const roundData = currentRoundDoc.data();

      // Fetch tricks subcollection
      const tricksCollection = collection(currentRoundDoc.ref, 'tricks');
      const tricksSnap = await getDocs(tricksCollection);
      const trickData = tricksSnap.docs[0].data(); // Assuming only the current trick is stored

      // Map current trick
      const currentTrick: Trick = {
        cardsPlayed: trickData['cardsPlayed'].map(function (card: any) { return card
            ? {
                suit: card['suit'],
                rank: card['rank'],
                photo: card['photo'],
              }
            : null; }),
        leadPlayer:  {
              name: trickData['leadPlayer']['name'],
              index: trickData['leadPlayer']['index'],
              isBot: trickData['leadPlayer']['isBot'],
            },
        cardLed: trickData['cardLed']
          ? {
              suit: trickData['cardLed']['suit'],
              rank: trickData['cardLed']['rank'],
              photo: trickData['cardLed']['photo'],
            }
          : null,
        currentPlayer: {
              name: trickData['currentPlayer']['name'],
              index: trickData['currentPlayer']['index'],
              isBot: trickData['currentPlayer']['index'],
            },
        playedCounter: trickData['playedCounter'],
      };

      // Fetch hands collection
      const handsCollection = collection(currentRoundDoc.ref, 'hands');
      const handsSnap = await getDocs(handsCollection);

      const hands: [Card[], Card[], Card[], Card[]] = [[], [], [], []]; // Assuming 4 players
      handsSnap.docs.forEach(function (docSnap) {
        const playerIndex = parseInt(docSnap.id, 10);
        const handData = docSnap.data();
        hands[playerIndex] = handData['cards'].map((card: any) => ({
          suit: card['suit'],
          rank: card['rank'],
          photo: card['photo'],
        }));
      });

      // Assemble the current round
      game.currentRound = {
        hands,
        kittyCard: {
          suit: roundData['kittyCard']['suit'],
          rank: roundData['kittyCard']['rank'],
          photo: roundData['kittyCard']['photo'],
        },
        dealer: {
          name: roundData['dealer']['name'],
          index: roundData['dealer']['index'],
          isBot: roundData['dealer']['index'],
        },
        caller: roundData['caller']
          ? {
              name: roundData['caller']['name'],
              index: roundData['caller']['index'],
              isBot: roundData['dealer']['index'],
            }
          : null,
        outPlayer: roundData['outPlayer']
          ? {
              name: roundData['outPlayer']['name'],
              index: roundData['outPlayer']['index'],
              isBot: roundData['dealer']['index'],
            }
          : null,
        trumpSuit: roundData['trumpSuit'],
        trickCounter: roundData['trickCounter'],
        currentTrick,
        tricksWon: roundData['tricksWon'],
        tricksWonPlayer: roundData['tricksWonPlayer'],
        passTrumpCount: roundData['passTrumpCount'],
        switchTime: roundData['switchTime'],
      };

      // Delete all related documents and collections
      await Promise.all(playersSnap.docs.map(function (docSnap) { return deleteDoc(docSnap.ref); })); // Delete all players
      await Promise.all(
        roundsSnap.docs.map(async function (roundDoc) {
          // Delete tricks subcollection
          const tricksCollection = collection(roundDoc.ref, 'tricks');
          const tricksSnap = await getDocs(tricksCollection);
          await Promise.all(tricksSnap.docs.map((docSnap) => deleteDoc(docSnap.ref)));

          // Delete hands subcollection
          const handsCollection = collection(roundDoc.ref, 'hands');
          const handsSnap = await getDocs(handsCollection);
          await Promise.all(handsSnap.docs.map((docSnap) => deleteDoc(docSnap.ref)));

          // Delete the round document itself
          await deleteDoc(roundDoc.ref);
        })
      );

      // Finally, delete the main game document
      await deleteDoc(gameDocRef);

      console.log('Game and all related documents deleted successfully.');
      return game;
    } catch (error) {
      console.error('Error loading and deleting game:', error);
      throw error;
    }
  }


  async getAllGames(): Promise<{ gameId: string, timestamp: any, players: Player[] }[]> {
    try {
      // Reference to the 'games' collection
      const gamesCollection = collection(this.firestore, 'games');

      // Retrieve all game documents from Firestore
      const gamesSnapshot = await getDocs(gamesCollection);

      const gamesList: { gameId: string, timestamp: any, players: Player[] }[] = [];

      // Iterate through all the games in the snapshot
      for (const gameDoc of gamesSnapshot.docs) {
        const gameData = gameDoc.data();

        // Get the game ID
        const gameId = gameDoc.id;

        // Get the timestamp of the game
        const timestamp = gameData['timestamp'];

        // Retrieve players subcollection for each game
        const playersCollection = collection(gameDoc.ref, 'players');
        const playersSnapshot = await getDocs(playersCollection);

        const players: Player[] = [];
        playersSnapshot.forEach(function playerDoc {
          players.push(playerDoc.data() as Player);
        });

        // Add the game information to the list
        gamesList.push({ gameId, timestamp, players });
      }

      return gamesList;
    } catch (error) {
      console.error('Error retrieving games:', error);
      return [];
    }
  }

}

var GitHubApi = require('@octokit/rest');

const debug = require("debug")("git-commit-push-via-github-api");
const GITHUB_API_TOKEN = process.env.GITHUB_API_TOKEN;
const getReferenceCommit = function(github: GitHubApi, options: GitCommitPushOptions) {
    return new Promise(function (resolve, reject) {
        github.git.getRef(
            {
                owner: options.owner,
                repo: options.repo,
                ref: options.fullyQualifiedRef
            },
            (err, res) => {
                if (err) {
                    debug("getReferenceCommit Error", JSON.stringify(err, null, "  "));
                    return reject(err);
                }
                debug("getReferenceCommit Response: %O", res);
                return resolve({ referenceCommitSha: res.data.object.sha });
            }
        );
    });
};

const createTree = function(github: GitHubApi, options: GitCommitPushOptions, data: any) {
    return new Promise(function (resolve, reject) {
        const promises = options.files.map(file => {
            if (typeof file.path === "string" && typeof file.content === "string") {
                return github.git
                    .createBlob({
                        owner: options.owner,
                        repo: options.repo,
                        content: file.content,
                        encoding: "utf-8"
                    })
                    .then((blob: any) => {
                        return {
                            sha: blob.data.sha,
                            path: file.path,
                            mode: "100644",
                            type: "blob"
                        };
                    });
            } else if (typeof file.path === "string" && Buffer.isBuffer(file.content)) {
                return github.git
                    .createBlob({
                        owner: options.owner,
                        repo: options.repo,
                        content: file.content.toString("base64"),
                        encoding: "base64"
                    })
                    .then((blob: any) => {
                        return {
                            sha: blob.data.sha,
                            path: file.path,
                            mode: "100644",
                            type: "blob"
                        };
                    });
            }
            throw new Error("This file can not handled: " + (file) + "");
        });
        return Promise.all(promises).then(files => {
            debug("files: %O", files);
            // TODO: d.ts bug?
            github.git.createTree(
                {
                    owner: options.owner,
                    repo: options.repo,
                    tree: files,
                    base_tree: data.referenceCommitSha
                } as any,
                (err: any, res: any) => {
                    if (err) {
                        debug("createTree", JSON.stringify(err, null, "  "));
                        return reject(err);
                    }
                    debug("createTree Response: %O", res);
                    return resolve(Object.assign(data, { newTreeSha: res.data.sha }));
                }
            );
        });
    });
};

const createCommit = function(github: GitHubApi, options: GitCommitPushOptions, data: any) {
    return new Promise(function (resolve, reject) {
        github.git.createCommit(
            {
                owner: options.owner,
                repo: options.repo,
                message: options.commitMessage || "commit",
                tree: data.newTreeSha,
                parents: [data.referenceCommitSha]
            },
            (err, res) => {
                if (err) {
                    debug("createCommit", JSON.stringify(err, null, "  "));
                    return reject(err);
                }
                debug("createCommit Response: %O", res);
                return resolve(Object.assign(data, { newCommitSha: res.data.sha }));
            }
        );
    });
};

const updateReference = function(github: GitHubApi, options: GitCommitPushOptions, data: any) {
    return new Promise(function (resolve, reject) {
        github.git.updateRef(
            {
                owner: options.owner,
                repo: options.repo,
                ref: options.fullyQualifiedRef,
                sha: data.newCommitSha,
                force: options.forceUpdate
            },
            (err, data) => {
                if (err) {
                    debug("updateReference", JSON.stringify(err, null, "  "));
                    return reject(err);
                }
                debug("updateReference Response: %O", data);
                return resolve(data);
            }
        );
    });
};

export interface GitCommitPushOptions {
    owner: string;
    repo: string;
    files: {
        path: string;
        content: string | Buffer;
    }[];
    fullyQualifiedRef: string;
    forceUpdate?: boolean;
    commitMessage?: string;
    token?: string; // or process.env.GITHUB_API_TOKEN
}

const gitCommitPush = function (options: GitCommitPushOptions) {
    if (!options.owner || !options.repo || !options.files || !options.files.length) {
        return "";
    }
    const token = options.token || GITHUB_API_TOKEN;
    if (!token) {
        throw new Error("token is not defined");
    }
    const gitHub = new GitHubApi();
    if (token) {
        gitHub.authenticate({
            type: "oauth",
            token: token
        });
    }
    const filledOptions = {
        owner: options.owner,
        repo: options.repo,
        files: options.files,
        fullyQualifiedRef: options.fullyQualifiedRef || "heads/dev",
        forceUpdate: options.forceUpdate || false,
        commitMessage: options.commitMessage || "Commit - " + new Date().getTime().toString()
    };
    debug("options %O", options);
    return getReferenceCommit(gitHub, filledOptions)
        .then(data => createTree(gitHub, filledOptions, data))
        .then(data => createCommit(gitHub, filledOptions, data))
        .then(data => updateReference(gitHub, filledOptions, data));
};

