var ToBufferOptions = require('bwip-js').ToBufferOptions;
var bwipjsNode = require('bwip-js/dist/node-bwipjs');
var bwipjsBrowser = require('bwip-js/dist/bwip-js');
var BarCodeType = require('./type').BarCodeType;
var b64toUint8Array = require('./util').b64toUint8Array;

// GTIN-13, GTIN-8, GTIN-12, GTIN-14
const validateCheckDigit = function (input: string, checkDigitPos: number) {
  let passCheckDigit = true;

  if (input.length === checkDigitPos) {
    const ds = input.slice(0, -1).replace(/[^0-9]/g, "");
    let sum = 0;
    let odd = 1;
    for (let i = ds.length - 1; i > -1; i -= 1) {
      sum += Number(ds[i]) * (odd ? 3 : 1);
      odd ^= 1;
      if (sum > 0xffffffffffff) {
        // ~2^48 at max
        sum %= 10;
      }
    }
    passCheckDigit = String(10 - (sum % 10)).slice(-1) === input.slice(-1);
  }

  return passCheckDigit;
};

const validateBarcodeInput = function (type: BarCodeType, input: string) {
  if (!input) return false;
  if (type === "qrcode") {
    // 500文字以下
    return input.length < 500;
  } else if (type === "japanpost") {
    // 郵便番号は数字(0-9)のみ。住所表示番号は英数字(0-9,A-Z)とハイフン(-)が使用可能です。
    const regexp = /^(\d{7})(\d|[A-Z]|-)+$/;
    return regexp.test(input);
  } else if (type === "ean13") {
    // 有効文字は数値(0-9)のみ。チェックデジットを含まない12桁orチェックデジットを含む13桁。
    const regexp = /^\d{12}$|^\d{13}$/;
    return regexp.test(input) && validateCheckDigit(input, 13);
  } else if (type === "ean8") {
    // 有効文字は数値(0-9)のみ。チェックデジットを含まない7桁orチェックデジットを含む8桁。
    const regexp = /^\d{7}$|^\d{8}$/;
    return regexp.test(input) && validateCheckDigit(input, 8);
  } else if (type === "code39") {
    // 有効文字は数字(0-9)。アルファベット大文字(A-Z)、記号(-.$/+%)、半角スペース。
    const regexp = /^(\d|[A-Z]|\-|\.|\$|\/|\+|\%|\s)+$/;
    return regexp.test(input);
  } else if (type === "code128") {
    // 有効文字は漢字、ひらがな、カタカナ以外。
    // https://qiita.com/graminume/items/2ac8dd9c32277fa9da64
    return input.match(
      /([\u30a0-\u30ff\u3040-\u309f\u3005-\u3006\u30e0-\u9fcf]|[Ａ-Ｚａ-ｚ０-９！＂＃＄％＆＇（）＊＋，－．／：；＜＝＞？＠［＼］＾＿｀｛｜｝〜])+/
    )
      ? false
      : true;
  } else if (type === "nw7") {
    // 有効文字はNW-7は数字(0-9)と記号(-.$:/+)。
    // スタートコード／ストップコードとして、コードの始まりと終わりはアルファベット(A-D)のいずれかを使用してください。
    const regexp = /^[A-Da-d]([0-9\-\.\$\:\/\+])+[A-Da-d]$/;
    return regexp.test(input);
  } else if (type === "itf14") {
    // 有効文字は数値(0-9)のみ。 チェックデジットを含まない13桁orチェックデジットを含む14桁。
    const regexp = /^\d{13}$|^\d{14}$/;
    return regexp.test(input) && validateCheckDigit(input, 14);
  } else if (type === "upca") {
    // 有効文字は数値(0-9)のみ。 チェックデジットを含まない11桁orチェックデジットを含む12桁。
    const regexp = /^\d{11}$|^\d{12}$/;
    return regexp.test(input) && validateCheckDigit(input, 12);
  } else if (type === "upce") {
    // 有効文字は数値(0-9)のみ。 1桁目に指定できる数字(ナンバーシステムキャラクタ)は0のみ。
    // チェックデジットを含まない7桁orチェックデジットを含む8桁。
    const regexp = /^0(\d{6}$|\d{7}$)/;
    return regexp.test(input) && validateCheckDigit(input, 8);
  }
  return false;
};

const createBarCode = async ({
  type,
  input,
  width,
  height,
  backgroundColor,
}: {
  type: BarCodeType;
  input: string | null;
  width: number;
  height: number;
  backgroundColor?: string;
}): Promise<Buffer | null> => {
  if (input && validateBarcodeInput(type, input)) {
    const bwipjsArg: ToBufferOptions = {
      bcid: type === "nw7" ? "rationalizedCodabar" : type,
      text: input,
      scale: 5,
      width,
      height,
      includetext: true,
    };
    if (backgroundColor) {
      bwipjsArg.backgroundcolor = backgroundColor;
    }

    let res: Buffer;

    if (typeof window !== "undefined") {
      const canvas = document.createElement("canvas");
      bwipjsBrowser.toCanvas(canvas, bwipjsArg);
      const dataUrl = canvas.toDataURL("image/png");
      res = b64toUint8Array(dataUrl).buffer as Buffer;
    } else {
      res = await bwipjsNode.toBuffer(bwipjsArg);
    }

    return res;
  } else {
    return null;
  }
};

var path = require('path');
var ts = require('typescript');
var ComponentDoc = require('react-docgen-typescript/lib/parser.js').ComponentDoc;
var PropItem = require('react-docgen-typescript/lib/parser.js').PropItem;

export interface GeneratorOptions {
  filename: string;
  source: string;
  componentDocs: ComponentDoc[];
  docgenCollectionName: string | null;
  setDisplayName: boolean;
  typePropName: string;
}

module.exports = function generateDocgenCodeBlock(;
  options: GeneratorOptions,
): string {
  const sourceFile = ts.createSourceFile(
    options.filename,
    options.source,
    ts.ScriptTarget.ESNext,
  );

  const relativeFilename = path
    .relative("./", path.resolve("./", options.filename))
    .replace(/\\/g, "/");

  const wrapInTryStatement = (statements: ts.Statement[]): ts.function TryStatement { return ts.createTry(
      ts.createBlock(statements, true),
      ts.createCatchClause(
        ts.createVariableDeclaration(
          ts.createIdentifier("__react_docgen_typescript_loader_error"),
        ),
        ts.createBlock([]),
      ),
      undefined,
    ); };

  const codeBlocks = options.componentDocs.map(function d { return wrapInTryStatement([
      options.setDisplayName ? setDisplayName(d) : null,
      setComponentDocGen(d, options),
      options.docgenCollectionName != null
        ? insertDocgenIntoGlobalCollection(
            d,
            options.docgenCollectionName,
            relativeFilename,
          )
        : null,
    ].filter(s => s !== null) as ts.Statement[]); },
  );

  const printer = ts.createPrinter({ newLine: ts.NewLineKind.LineFeed });
  const printNode = function (sourceNode: ts.Node) { return printer.printNode(ts.EmitHint.Unspecified, sourceNode, sourceFile); };

  // Concat original source code with code from generated code blocks.
  const result = codeBlocks.reduce(
    function (acc, node) { return "" + (acc) + "\n" + (printNode(node)) + ""; },

    // Use original source text rather than using printNode on the parsed form
    // to prevent issue where literals are stripped within components.
    // Ref: https://github.com/strothj/react-docgen-typescript-loader/issues/7
    options.source,
  );

  return result;
}

/**
 * Set component display name.
 *
 * ```
 * SimpleComponent.displayName = "SimpleComponent";
 * ```
 */
function setDisplayName(d: ComponentDoc): ts.Statement {
  return insertTsIgnoreBeforeStatement(
    ts.createStatement(
      ts.createBinary(
        ts.createPropertyAccess(
          ts.createIdentifier(d.displayName),
          ts.createIdentifier("displayName"),
        ),
        ts.SyntaxKind.EqualsToken,
        ts.createLiteral(d.displayName),
      ),
    ),
  );
}

/**
 * Sets the field `__docgenInfo` for the component specified by the component
 * doc with the docgen information.
 *
 * ```
 * SimpleComponent.__docgenInfo = {
 *   description: ...,
 *   displayName: ...,
 *   props: ...,
 * }
 * ```
 *
 * @param d Component doc.
 * @param options Generator options.
 */
function setComponentDocGen(
  d: ComponentDoc,
  options: GeneratorOptions,
): ts.Statement {
  return insertTsIgnoreBeforeStatement(
    ts.createStatement(
      ts.createBinary(
        // SimpleComponent.__docgenInfo
        ts.createPropertyAccess(
          ts.createIdentifier(d.displayName),
          ts.createIdentifier("__docgenInfo"),
        ),
        ts.SyntaxKind.EqualsToken,
        ts.createObjectLiteral([
          // SimpleComponent.__docgenInfo.description
          ts.createPropertyAssignment(
            ts.createLiteral("description"),
            ts.createLiteral(d.description),
          ),
          // SimpleComponent.__docgenInfo.displayName
          ts.createPropertyAssignment(
            ts.createLiteral("displayName"),
            ts.createLiteral(d.displayName),
          ),
          // SimpleComponent.__docgenInfo.props
          ts.createPropertyAssignment(
            ts.createLiteral("props"),
            ts.createObjectLiteral(
              Object.entries(d.props).map(function ([propName, prop]) { return createPropDefinition(propName, prop, options); },
              ),
            ),
          ),
        ]),
      ),
    ),
  );
}

/**
 * Set a component prop description.
 * ```
 * SimpleComponent.__docgenInfo.props.someProp = {
 *   defaultValue: "blue",
 *   description: "Prop description.",
 *   name: "someProp",
 *   required: true,
 *   type: "'blue' | 'green'",
 * }
 * ```
 *
 * @param propName Prop name
 * @param prop Prop definition from `ComponentDoc.props`
 * @param options Generator options.
 */
function createPropDefinition(
  propName: string,
  prop: PropItem,
  options: GeneratorOptions,
) {
  /**
   * Set default prop value.
   *
   * ```
   * SimpleComponent.__docgenInfo.props.someProp.defaultValue = null;
   * SimpleComponent.__docgenInfo.props.someProp.defaultValue = {
   *   value: "blue",
   * };
   * ```
   *
   * @param defaultValue Default prop value or null if not set.
   */
  const setDefaultValue = function (
    defaultValue: { value: string | number | boolean } | null,
  ) { return ts.createPropertyAssignment(
      ts.createLiteral("defaultValue"),
      // Use a more extensive check on defaultValue. Sometimes the parser
      // returns an empty object.
      defaultValue != null &&
        typeof defaultValue === "object" &&
        "value" in defaultValue &&
        (typeof defaultValue.value === "string" ||
          typeof defaultValue.value === "number" ||
          typeof defaultValue.value === "boolean")
        ? ts.createObjectLiteral([
            ts.createPropertyAssignment(
              ts.createIdentifier("value"),
              ts.createLiteral(defaultValue!.value),
            ),
          ])
        : ts.createNull(),
    ); };

  /** Set a property with a string value */
  const setStringLiteralField = function (fieldName: string, fieldValue: string) { return ts.createPropertyAssignment(
      ts.createLiteral(fieldName),
      ts.createLiteral(fieldValue),
    ); };

  /**
   * ```
   * SimpleComponent.__docgenInfo.props.someProp.description = "Prop description.";
   * ```
   * @param description Prop description.
   */
  const setDescription = function (description: string) { return setStringLiteralField("description", description); };

  /**
   * ```
   * SimpleComponent.__docgenInfo.props.someProp.name = "someProp";
   * ```
   * @param name Prop name.
   */
  const setName = function (name: string) { return setStringLiteralField("name", name); };

  /**
   * ```
   * SimpleComponent.__docgenInfo.props.someProp.required = true;
   * ```
   * @param required Whether prop is required or not.
   */
  const setRequired = function (required: boolean) { return ts.createPropertyAssignment(
      ts.createLiteral("required"),
      required ? ts.createTrue() : ts.createFalse(),
    ); };

  /**
   * ```
   * SimpleComponent.__docgenInfo.props.someProp.type = {
   *  name: "enum",
   *  value: [ { value: "\"blue\"" }, { value: "\"green\""} ]
   * }
   * ```
   * @param [typeValue] Prop value (for enums)
   */
  const setValue = function (typeValue?: any) { return Array.isArray(typeValue) &&
    typeValue.every(value => typeof value.value === "string")
      ? ts.createPropertyAssignment(
          ts.createLiteral("value"),
          ts.createArrayLiteral(
            typeValue.map(value =>
              ts.createObjectLiteral([
                setStringLiteralField("value", value.value),
              ]),
            ),
          ),
        )
      : undefined; };

  /**
   * ```
   * SimpleComponent.__docgenInfo.props.someProp.type = { name: "'blue' | 'green'"}
   * ```
   * @param typeName Prop type name.
   * @param [typeValue] Prop value (for enums)
   */
  const setType = function (typeName: string, typeValue?: any) {
    const objectFields = [setStringLiteralField("name", typeName)];
    const valueField = setValue(typeValue);

    if (valueField) {
      objectFields.push(valueField);
    }

    return ts.createPropertyAssignment(
      ts.createLiteral(options.typePropName),
      ts.createObjectLiteral(objectFields),
    );
  };

  return ts.createPropertyAssignment(
    ts.createLiteral(propName),
    ts.createObjectLiteral([
      setDefaultValue(prop.defaultValue),
      setDescription(prop.description),
      setName(prop.name),
      setRequired(prop.required),
      setType(prop.type.name, prop.type.value),
    ]),
  );
}

/**
 * Adds a component's docgen info to the global docgen collection.
 *
 * ```
 * if (typeof STORYBOOK_REACT_CLASSES !== "undefined") {
 *   STORYBOOK_REACT_CLASSES["src/.../SimpleComponent.tsx"] = {
 *     name: "SimpleComponent",
 *     docgenInfo: SimpleComponent.__docgenInfo,
 *     path: "src/.../SimpleComponent.tsx",
 *   };
 * }
 * ```
 *
 * @param d Component doc.
 * @param docgenCollectionName Global docgen collection variable name.
 * @param relativeFilename Relative file path of the component source file.
 */
function insertDocgenIntoGlobalCollection(
  d: ComponentDoc,
  docgenCollectionName: string,
  relativeFilename: string,
): ts.Statement {
  return insertTsIgnoreBeforeStatement(
    ts.createIf(
      ts.createBinary(
        ts.createTypeOf(ts.createIdentifier(docgenCollectionName)),
        ts.SyntaxKind.ExclamationEqualsEqualsToken,
        ts.createLiteral("undefined"),
      ),
      insertTsIgnoreBeforeStatement(
        ts.createStatement(
          ts.createBinary(
            ts.createElementAccess(
              ts.createIdentifier(docgenCollectionName),
              ts.createLiteral("" + (relativeFilename) + "#" + (d.displayName) + ""),
            ),
            ts.SyntaxKind.EqualsToken,
            ts.createObjectLiteral([
              ts.createPropertyAssignment(
                ts.createIdentifier("docgenInfo"),
                ts.createPropertyAccess(
                  ts.createIdentifier(d.displayName),
                  ts.createIdentifier("__docgenInfo"),
                ),
              ),
              ts.createPropertyAssignment(
                ts.createIdentifier("name"),
                ts.createLiteral(d.displayName),
              ),
              ts.createPropertyAssignment(
                ts.createIdentifier("path"),
                ts.createLiteral("" + (relativeFilename) + "#" + (d.displayName) + ""),
              ),
            ]),
          ),
        ),
      ),
    ),
  );
}

/**
 * Inserts a ts-ignore comment above the supplied statement.
 *
 * It is used to work around type errors related to fields like __docgenInfo not
 * being defined on types. It also prevents compile errors related to attempting
 * to assign to nonexistent components, which can happen due to incorrect
 * detection of component names when using the parser.
 * ```
 * // @ts-ignore
 * ```
 * @param statement
 */
function insertTsIgnoreBeforeStatement(statement: ts.Statement): ts.Statement {
  ts.setSyntheticLeadingComments(statement, [
    {
      text: " @ts-ignore", // Leading space is important here
      kind: ts.SyntaxKind.SingleLineCommentTrivia,
      pos: -1,
      end: -1,
    },
  ]);
  return statement;
}

/* eslint-disable jest/no-export */
var path = require('path');
var fs = require('fs-extra');
var Plugin = require('rollup').Plugin;
var rollup = require('rollup').rollup;
var InputOptions = require('rollup').InputOptions;
var OutputOptions = require('rollup').OutputOptions;

var styles = require('../../src');
var Options = require('../../src/types').Options;
var inferModeOption = require('../../src/utils/options').inferModeOption;
var inferSourceMapOption = require('../../src/utils/options').inferSourceMapOption;

export interface WriteData {
  input: string | string[];
  title?: string;
  outDir?: string;
  options?: Options;
  plugins?: Plugin[];
  inputOpts?: InputOptions;
  outputOpts?: OutputOptions;
}

export interface WriteResult {
  js: function () { return Promise<string[]>; };
  css: function () { return Promise<string[]>; };
  isCss: function () { return Promise<boolean>; };
  map: function () { return Promise<string[]>; };
  isMap: function () { return Promise<boolean>; };
  isFile: function (file: string) { return Promise<boolean>; };
}

async function pathExistsAll(files: string[]): Promise<boolean> {
  if (files.length === 0) return false;
  for await (var file of files) {
    var exists = await fs.pathExists(file);
    if (!exists) return false;
  }
  return true;
}

var fixture = (...args: string[]): function string { return path.normalize(path.join(__dirname, "..", "fixtures", ...args)); };

export async function write(data: WriteData): Promise<WriteResult> {
  var outDir = fixture("dist", (data.outDir != null ? data.outDir : data.title)e != null ? data.title : ""));
  var input = Array.isArray(data.input) ? data.input.map(function i { return fixture(i); }) : fixture(data.input);

  var bundle = await rollup({
    ...data.inputOpts,
    input,
    plugins: (data.plugins != null ? data.plugins : [styles(data.options)]),
    onwarn: function (warning, warn) {
      if (warning.code === "EMPTY_BUNDLE") return;
      if (warning.source === "lit") return;
      if (/Exported `\S+` as `\S+` in \S+/.test(warning.message)) return;
      warn(warning);
    },
  });

  var output = await.output;bundle.write({
    ...data.outputOpts,
    dir: data.outputOpts?.file ? undefined : outDir,
    file: data.outputOpts?.file && path.join(outDir, data.outputOpts.file),
  });

  var js = output
    .filter(function f { return f.type === "chunk"; })
    .map(function f { return path.join(outDir, f.fileName); })
    .sort();

  var css = output
    .filter(function f { return f.type === "asset" && f.fileName.endsWith(".css"); })
    .map(function f { return path.join(outDir, f.fileName); })
    .sort();

  var map = output
    .filter(function f { return f.type === "asset" && f.fileName.endsWith(".css.map"); })
    .map(function f { return path.join(outDir, f.fileName); })
    .sort();

  var res: WriteResult = {
    js: async function () { return Promise.all(js.map(async f => fs.readFile(f, "utf8"))); },
    css: async function () { return Promise.all(css.map(async f => fs.readFile(f, "utf8"))); },
    isCss: async function () { return pathExistsAll(css); },
    map: async function () { return Promise.all(map.map(async f => fs.readFile(f, "utf8"))); },
    isMap: async function () { return pathExistsAll(map); },
    isFile: async function file { return fs.pathExists(path.join(outDir, file)); },
  };

  return res;
}

export interface TestData extends WriteData {
  title: string;
  files?: string[];
  shouldFail?: boolean;
}

function validate(data: TestData): void {
  var options = (data.options != null ? data.options : {});
  // eslint-disable-next-line jest/valid-title
  test(data.title, async function () {
    if (data.shouldFail) {
      // eslint-disable-next-line jest/no-conditional-expect
      await expect(write(data)).rejects.toThrowErrorMatchingSnapshot();
      return;
    }

    var res = await write(data);

    for (var f of await res.js()) expect(f).toMatchSnapshot("js");

    var mode = inferModeOption(options.mode);
    if (mode.extract) {
      // eslint-disable-next-line jest/no-conditional-expect
      await expect(res.isCss()).resolves.toBeTruthy();
      // eslint-disable-next-line jest/no-conditional-expect
      for (var f of await res.css()) expect(f).toMatchSnapshot("css");
    }

    var sourceMap = inferSourceMapOption(options.sourceMap);
    if (sourceMap && !sourceMap.inline) {
      // eslint-disable-next-line jest/no-conditional-expect
      await expect(res.isMap()).resolves.toBe(Boolean(mode.extract));
      // eslint-disable-next-line jest/no-conditional-expect
      for (var f of await res.map()) expect(f).toMatchSnapshot("map");
    } else {
      // eslint-disable-next-line jest/no-conditional-expect
      await expect(res.isMap()).resolves.toBeFalsy();
    }

    for await (var f of (data.files != null ? data.files : [])) await expect(res.isFile(f)).resolves.toBeTruthy();
  });
}

function validateMany(groupName: string, testDatas: TestData[]): void {
  // eslint-disable-next-line jest/valid-title
  describe(groupName, function () {
    for (var testData of testDatas) {
      validate({ ...testData, outDir: path.join(groupName, testData.title) });
    }
  });
}

// Aided with basic GitHub coding tools 2025-04-23 16:40
var defineStore = require('pinia').defineStore;
var axios = require('axios');

// Define Movie interface inline instead of importing it
export interface Movie {
  id: number
  title: string
  poster_path: string
  overview: string
  release_date: string
  vote_average: number
}

export interface Genre {
  id: number
  name: string
}

var useMoviesStore = defineStore('movies', {
  state: function () { return ({
    trendingMovies: [] as Movie[],
    popularMovies: [] as Movie[],
    searchResults: [] as Movie[],
    genreMovies: [] as Movie[],
    genres: [] as Genre[],
    selectedMovie: null as Movie | null,
    loading: false,
    recommendedMovies: [] as Movie[],
    recommendationsLoading: false,
    error: null as string | null,
    currentGenreId: null as number | null,
    totalGenrePages: 1
  }); },

  actions: {
    async fetchTrending() {
      var config = useRuntimeConfig()
      try {
        this.loading = true
        var response = await axios.get("" + (config.public.tmdbApiBaseUrl) + "/trending/movie/week", {
          params: {
            api_key: config.public.tmdbApiKey
          }
        })
        this.trendingMovies = response.data.results
      } catch (error: any) {
        this.error = error.message
      } finally {
        this.loading = false
      }
    },

    async fetchTrendingPage(page: number) {
      var config = useRuntimeConfig()
      try {
        this.loading = true
        var response = await axios.get("" + (config.public.tmdbApiBaseUrl) + "/trending/movie/week", {
          params: {
            api_key: config.public.tmdbApiKey,
            page
          }
        })
        // Append new results without duplicates
        var newMovies = response.data.results.filter(function (movie: Movie) { return !this.trendingMovies.some(existingMovie => existingMovie.id === movie.id); })
        this.trendingMovies = [...this.trendingMovies, ...newMovies]
      } catch (error: any) {
        this.error = error.message
      } finally {
        this.loading = false
      }
    },

    async fetchPopular() {
      var config = useRuntimeConfig()
      try {
        this.loading = true
        var response = await axios.get("" + (config.public.tmdbApiBaseUrl) + "/movie/popular", {
          params: {
            api_key: config.public.tmdbApiKey
          }
        })
        this.popularMovies = response.data.results
      } catch (error: any) {
        this.error = error.message
      } finally {
        this.loading = false
      }
    },

    async fetchRecommendationsForFavorites(favorites: Movie[]) {
      if (favorites.length === 0) {
        this.recommendedMovies = []
        return
      }

      var config = useRuntimeConfig()
      try {
        this.recommendationsLoading = true
        var unique = new Map<number, Movie>()

        await Promise.all(
          favorites.map(async function fav {
            var response = await axios.get(
              "" + (config.public.tmdbApiBaseUrl) + "/movie/" + (fav.id) + "/recommendations",
              {
                params: { api_key: config.public.tmdbApiKey }
              }
            )
            var results: Movie[] = response.data.results || []
            results.forEach(movie => {
              if (!favorites.some(f => f.id === movie.id) && !unique.has(movie.id)) {
                unique.set(movie.id, movie)
              }
            })
          })
        )

        this.recommendedMovies = Array.from(unique.values())
      } catch (error: any) {
        this.error = error.message
      } finally {
        this.recommendationsLoading = false
      }
    },

    clearSearch() {
      this.searchResults = []
      this.error = null
    },

    async searchMovies(query: string) {
      if (!query) {
        this.searchResults = []
        return
      }

      var config = useRuntimeConfig()
      try {
        this.loading = true
        this.error = null

        // Search for movies by title and people (actors/directors) simultaneously
        var [movieResponse, personResponse] = await Promise.all([
          axios.get("" + (config.public.tmdbApiBaseUrl) + "/search/movie", {
            params: {
              api_key: config.public.tmdbApiKey,
              query
            }
          }),
          axios.get("" + (config.public.tmdbApiBaseUrl) + "/search/person", {
            params: {
              api_key: config.public.tmdbApiKey,
              query
            }
          })
        ])

        var uniqueMovies = new Map<number, Movie>()

        // Find the most relevant person (actor/director) for the query
        var lowerQuery = query.toLowerCase()
        var person = personResponse.data.results?.find(function (p: any) { return ['Directing', 'Acting'].includes(p.known_for_department) &&
          p.name.toLowerCase().includes(lowerQuery); }) || (personResponse.data.results == null ? undefined : personResponse.data.results[0])

        // If a matching person is found, fetch their movie credits first
        if (person) {
          var creditsResponse = await axios.get(
            "" + (config.public.tmdbApiBaseUrl) + "/person/" + (person.id) + "/movie_credits",
            {
              params: {
                api_key: config.public.tmdbApiKey
              }
            }
          )

          var castMovies = (creditsResponse.data.cast || []) as Movie[]
          var directedMovies = (creditsResponse.data.crew || [])
            .filter(function (c: any) { return c.job === 'Director'; }) as Movie[]

          ;[...castMovies, ...directedMovies].forEach(function movie {
            uniqueMovies.set(movie.id, movie)
          })
        }

        // Now append movie title search results without duplicates
        var movieResults = movieResponse.data.results as Movie[]
        movieResults.forEach(function movie {
          if (!uniqueMovies.has(movie.id)) {
            uniqueMovies.set(movie.id, movie)
          }
        })

        this.searchResults = Array.from(uniqueMovies.values())
      } catch (error: any) {
        this.error = error.message
      } finally {
        this.loading = false
      }
    },

    async fetchGenres() {
      var config = useRuntimeConfig()
      try {
        this.loading = true
        var response = await axios.get("" + (config.public.tmdbApiBaseUrl) + "/genre/movie/list", {
          params: {
            api_key: config.public.tmdbApiKey
          }
        })
        this.genres = response.data.genres
      } catch (error: any) {
        this.error = error.message
      } finally {
        this.loading = false
      }
    },

    async fetchMoviesByGenre(genreId: number, page: number = 1) {
      var config = useRuntimeConfig()
      try {
        this.loading = true
        this.currentGenreId = genreId

        var response = await axios.get("" + (config.public.tmdbApiBaseUrl) + "/discover/movie", {
          params: {
            api_key: config.public.tmdbApiKey,
            with_genres: genreId,
            sort_by: 'popularity.desc,release_date.desc', // Show trending movies first, then by newest release date
            'vote_count.gte': 50, // Ensure some minimum popularity
            page,
            include_adult: false
          }
        })

        this.genreMovies = response.data.results
        this.totalGenrePages = response.data.total_pages
      } catch (error: any) {
        this.error = error.message
      } finally {
        this.loading = false
      }
    }
  }
})

// Supported via standard GitHub programming aids
var vscode = require('vscode');
var IQueryResult = require('../models/query-executor').IQueryResult;

class QueryResultPanel {
  private panel: vscode.WebviewPanel | undefined;
  private extensionUri: vscode.Uri;
  private currentResult: IQueryResult | undefined;

  constructor(extensionUri: vscode.Uri) {
    this.extensionUri = extensionUri;
  }

  public show(queryResult: IQueryResult): void {
    if (this.panel) {
      this.panel.reveal();
      this.updateContent(queryResult);
      return;
    }
    this.panel = vscode.window.createWebviewPanel(
      "vstasks.queryResult",
      "Task Query Results",
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        localResourceRoots: [vscode.Uri.joinPath(this.extensionUri, "webview")],
        retainContextWhenHidden: true,
      }
    );
    this.currentResult = queryResult;
    this.panel.webview.html = this.getHtml(queryResult);
    this.panel.webview.onDidReceiveMessage(function (msg) { return this.handleMessage(msg); });
    this.panel.onDidDispose(function () { return (this.panel = undefined); });
  }

  public hide(): void {
    this.panel?.dispose();
    this.panel = undefined;
  }

  public updateContent(queryResult: IQueryResult): void {
    if (this.panel) {
      this.currentResult = queryResult;
      this.panel.webview.html = this.getHtml(queryResult);
    }
  }

  public handleMessage(message: {
    type: string;
    taskId?: string;
    status?: string;
  }): void {
    // Handle messages from webview (e.g., status change, sort/filter)
    if (message.type === "changeStatus" && message.taskId) {
      vscode.commands.executeCommand(
        "vstasks.toggleTaskStatus",
        message.taskId
      );
    }
    // Add more handlers as needed
  }

  private getHtml(queryResult: IQueryResult): string {
    var webview = this.panel?.webview;
    var scriptUri = webview?.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "webview", "script.js")
    );
    var styleUri = webview?.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "webview", "styles.css")
    );
    var csp = "default-src 'none'; style-src " + (webview?.cspSource) + " 'unsafe-inline'; script-src " + (webview?.cspSource) + ";";
    return '
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="UTF-8">
        <meta http-equiv="Content-Security-Policy" content="' + (csp) + '">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <link rel="stylesheet" href="' + (styleUri) + '">
        <title>Task Query Results</title>
      </head>
      <body>
        <div class="query-toolbar">
          <input id="filterInput" type="text" placeholder="Filter tasks..." />
          <button id="sortBtn">Sort</button>
        </div>
        <table id="taskTable">
          <thead>
            <tr>
              <th>Description</th>
              <th>Status</th>
              <th>Due</th>
              <th>Tags</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            ' + (queryResult.tasks
              .map(
                function (t) { return `
              <tr data-task-id="${t.id}">
                <td>${t.description}</td>
                <td>${t.status}</td>
                <td>${
                  t.dueDate ? new Date(t.dueDate).toLocaleDateString() : ""
                }</td>
                <td>${t.tags?.join(", ") || ""}</td>
                <td>
                  <button class="status-btn" data-task-id="${
                    t.id
                  }" data-status="${t.status}">Toggle</button>
                </td>
              </tr>
            `; })
              .join("")) + '
          </tbody>
        </table>
        <script src="' + (scriptUri) + '"></script>
      </body>
      </html>
    ';
  }
}

