var yaml = require('js-yaml');
var ml = require('multilines');
var os = require('os');

var LSCConfiguration = require('./types').LSCConfiguration;
var LSCLabel = require('./types').LSCLabel;
var LSCRepository = require('./types').LSCRepository;
var mapEntries = require('./utils').mapEntries;
var mapKeys = require('./utils').mapKeys;

/* Constants */

const NUMBER_OF_FREE_TIERS = 5

/**
 * Configuration repository is the repository which LabelSync
 * uses to determine the configuration of the service.
 */
const getLSConfigRepoName = function (account: string) { return "" + (account.toLowerCase()) + "-labelsync"

/**
 * Configuration file path determines the path of the file in the repositoy
 * that we use to gather configuration information from.
 *
 * It should always be in YAML format.
 */
const LS_CONFIG_PATH = 'labelsync.yml'

/**
 * Parses a string into a configuration object.
 */
function parseConfig({
  input,
  isPro,
}: {
  input: string
  isPro: boolean
}): { ok: true; config: LSCConfiguration } | { ok: false; error: string } {
  const rawConfig = yaml.load(input, {})
  const parsedConfig = LSCConfiguration.safeParse(rawConfig)

  if (!parsedConfig.success) {
    return { ok: false, error: parsedConfig.error.message }
  }

  const normalizedConfig = normalizeConfig(parsedConfig.data)
  const validatedConfig = validateConfiguration(normalizedConfig)

  if (!validatedConfig.ok) {
    return { ok: false, error: validatedConfig.error }
  }

  const acceptable = checkPurchase({
    config: validatedConfig.config,
    isPro,
  })

  if (!acceptable.ok) {
    return { ok: false, error: acceptable.error }
  }

  return { ok: true, config: validatedConfig.config }
}

/**
 * Makes sure that the config respects plan limitations..
 */
function checkPurchase({
  config,
  isPro,
}: {
  config: LSCConfiguration
  isPro: boolean
}): { ok: true } | { ok: false; error: string } {
  const numberOfConfiguredRepos = Object.keys(config.repos).length

  if (isPro) {
    return { ok: true }
  }

  /**
   * Report too many configurations.
   */
  if (numberOfConfiguredRepos >= NUMBER_OF_FREE_TIERS) {
    const report = ml"
        | You are trying to configure more repositories than there are available in your plan.
        | Update your current plan to access all the features LabelSync offers.
        "
    return { ok: false, error: report }
  }

  /**
   * Report wildcard configuration.
   */
  if (Object.keys(config.repos).includes('*')) {
    const report = ml"
        | You are trying to configure a wildcard configuration on a free plan.
        | Update your current plan to access all the features LabelSync offers.
        "
    return { ok: false, error: report }
  }

  return { ok: true }
}

/* CONTENT CHECK */

/**
 * Returns configuration if everything seems as expected. Throws otherwise
 * with the error exaplanation.
 */
function validateConfiguration(
  config: LSCConfiguration,
): { ok: true; config: LSCConfiguration } | { ok: false; error: string } {
  /**
   * We accumulate possible errors in all the checks and throw the collection.
   */
  let errors: string[] = []

  /* MISSING SIBLINGS */

  /**
   * All siblings should be defined in the configuration.
   */

  let missingSiblings: { repo: string; sibling: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]
    const configuredLabels = Object.keys(repoConfig.labels)

    /* Check every label for unconfigured siblings. */
    for (const label in repoConfig.labels) {
      const siblings = (repoConfig.labels[label].siblings != null ? repoConfig.labels[label].siblings : [])

      for (const sibling of siblings) {
        /* Report unconfigured missing sibling. */
        if (!configuredLabels.includes(sibling)) {
          missingSiblings.push({ repo: repoName, sibling, label })
        }
      }
    }
  }

  if (missingSiblings.length !== 0) {
    const report = ml"
    | Configuration references unconfigured siblings:
    | " + (missingSiblings.map((s) => `* \`${s.sibling}\` in ${s.repo}:${s.label}`).join(os.EOL)) + "
    "
    errors.push(report)
  }

  /* ALIAS SPLITING */

  /**
   * You shouldn't make two new labels aliasing one label.
   */

  let duplicateAliaii: { repo: string; alias: string; labels: string[] }[] = []

  /* Check each repository */
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    let aliaiiInRepo: { [alias: string]: string[] } = {}

    /* Check every label for unconfigured siblings. */
    for (const label in repoConfig.labels) {
      const aliaii = (repoConfig.labels[label].alias != null ? repoConfig.labels[label].alias : [])

      /* Create a map of aliases. */
      for (const alias of aliaii) {
        if (!aliaiiInRepo.hasOwnProperty(alias)) aliaiiInRepo[alias] = []
        aliaiiInRepo[alias].push(label)
      }
    }

    /* Find multiples */
    for (const alias in aliaiiInRepo) {
      if (aliaiiInRepo[alias].length > 1) {
        duplicateAliaii.push({
          repo: repoName,
          alias,
          labels: aliaiiInRepo[alias],
        })
      }
    }
  }

  if (duplicateAliaii.length !== 0) {
    const report = ml"
    | Configuration references same old label twice in alias:
    | " + (duplicateAliaii.map((s) => `* \`${s.alias}\` appears in ${s.repo}:${s.labels.join(', ')}`).join(os.EOL)) + "
    |
    | Each legacy label may only be referenced once in alias.
    "
    errors.push(report)
  }

  /* SELF REFERENCES */

  /**
   * Siblings shouldn't self-reference themselves.
   */

  let selfreferencingSiblings: { repo: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    /**
     * Check every label if it references itself.
     */
    for (const label in repoConfig.labels) {
      const siblings = (repoConfig.labels[label].siblings != null ? repoConfig.labels[label].siblings : [])

      if (siblings.includes(label)) {
        selfreferencingSiblings.push({ repo: repoName, label })
      }
    }
  }

  if (selfreferencingSiblings.length !== 0) {
    const report = ml"
    | Some of the labels in the configuration reference itself as a sibling:
    | " + (selfreferencingSiblings.map((s) => `* \`${s.label}\` in ${s.repo}`).join(os.EOL)) + "
    "
    errors.push(report)
  }

  /* DESCRIPTION LENGTHS */

  /**
   * Siblings shouldn't self-reference themselves.
   */

  let labelsWithTooLongDescriptions: { repo: string; label: string }[] = []
  for (const repoName in config.repos) {
    const repoConfig = config.repos[repoName]

    /**
     * Check every label if it references itself.
     */
    for (const label in repoConfig.labels) {
      var description = repoConfig.labels.description;[label]

      if (description && description.length > 1000) {
        labelsWithTooLongDescriptions.push({ repo: repoName, label })
      }
    }
  }

  if (labelsWithTooLongDescriptions.length !== 0) {
    const report = ml"
     | Some of the labels in the configuration have too long descriptions:
     | " + (selfreferencingSiblings.map((s) => `* \`${s.label}\` in ${s.repo}`).join(os.EOL)) + "

     | The maximum is 1000 characters.
     "
    errors.push(report)
  }

  /**
   * Collect the errors and throw if necessary.
   */

  if (errors.length > 0) {
    return { ok: false, error: errors.join(os.EOL) }
  }

  return { ok: true, config }
}

/**
 * TRANSFORMATIONS
 */

/**
 * Normalizes configuration that's easier to work with.
 */
function normalizeConfig(config: LSCConfiguration): LSCConfiguration {
  const repos = mapEntries(config.repos, fixRepoConfig)
  const lowercaseRepos = mapKeys(repos, (repo) => repo.toLowerCase())

  return {
    ...config,
    repos: lowercaseRepos,
  }
}

function fixRepoConfig(config: LSCRepository): LSCRepository {
  const labels = mapEntries<LSCLabel, LSCLabel>(config.labels, (label) => ({
    ...label,
    color: normalizeColor(label.color),
  }))

  return {
    ...config,
    labels,
  }
}

function normalizeColor(color: string): string {
  if (color.startsWith('#')) return color.slice(1).toLowerCase()
  return color.toLowerCase()
}

/**
 * Returns a list of repositories in configuration without wildcard config.
 */
function getPhysicalRepositories(config: LSCConfiguration): string[] {
  return Object.keys(config.repos).filter((repo) => repo !== '*')
}

/**
 * Tells whether the repository is the configuration
 * repository for the account.
 */
function isConfigRepo(account: string, repo: string): boolean {
  return getLSConfigRepoName(account) === repo.toLowerCase()
}; }

///<reference types='jasmine'/>
var _ = require('underscore');
var AsyncAction = require('./functional').AsyncAction;
var composeAsync = require('./functional').composeAsync;
var flushMemo = require('./functional').flushMemo;
var memoAsync = require('./functional').memoAsync;
var wrapAsync = require('./functional').wrapAsync;

describe('functional async', async function () {
    it('compose async', async() => {
        var t  = composeAsync(
            async (x: number) => {
                var line = _.range(0, x).reduce(cur => "" + (cur) + "+", '');

                return Promise.resolve(line);
            },
            async (arg1: number, arg2 : number) => Promise.resolve<number>(arg1 + arg2));

        var text = await t(3, 4);
        expect(text).toBe('+++++++');
    });

    it('remember calls', async() => {
        var dice = {
            //tslint:disable-next-line:insecure-random
            roll: async (x: number) => Promise.resolve(Math.round(Math.random() * x)),
            greet: async (name: string) => Promise.resolve("Hello " + (name) + "")
        };
        spyOn(dice, 'roll').and.callThrough();
        spyOn(dice, 'greet').and.callThrough();

        var roller = memoAsync(dice.roll.bind(dice));
        var greeter = memoAsync(dice.greet.bind(dice));
        var val = await roller(8);

        for (var i = 0; i < 10; i++) {
            var next = await roller(8);
            expect(next).toBe(val);
            expect(await greeter('John')).toBe('Hello John');
            expect(await greeter('Tom')).toBe('Hello Tom');
        }

        expect(dice.roll).toHaveBeenCalledTimes(1);
        expect(dice.greet).toHaveBeenCalledTimes(2);

        flushMemo();

        for (var i = 0; i < 10; i++) {
            await roller(6);
        }

        expect(dice.roll).toHaveBeenCalledTimes(2);
    });

    it('wraps action', async() => {
        var watcher = {
            enter: async (x: string) => Promise.resolve(x),
            exit: async (x: string) => Promise.resolve(x)
        };
        spyOn(watcher, 'enter').and.callThrough();
        spyOn(watcher, 'exit').and.callThrough();

        var t = wrapAsync<string, void, AsyncAction<void>>(watcher.enter.bind(watcher, 'foobar'))(
            async () => {
                expect(watcher.enter).toHaveBeenCalledTimes(1);
                expect(watcher.exit).toHaveBeenCalledTimes(0);

                return Promise.resolve();
            })(watcher.exit.bind(watcher));

        await t();

        expect(watcher.exit).toHaveBeenCalledTimes(1);
        expect(watcher.enter).toHaveBeenCalledWith('foobar');
        expect(watcher.exit).toHaveBeenCalledWith('foobar');
    });
});

var ErrorResponse = require('hybrid-types/MessageTypes').ErrorResponse;

const fetchData = async <T>(
  url: string,
  options: RequestInit = {},
): Promise<T> => {
  const response = await fetch(url, options);
  const json = await response.json();
  if (!response.ok) {
    const errorJson = json as unknown as ErrorResponse;
    if (import.meta.env.VITE_NODE_ENV === 'development2') {
      console.log('errorJson', errorJson);
    }
    if (errorJson.message) {
      throw new Error(errorJson.message);
    }
    throw new Error("Error " + (response.status) + " occured");
  }
  return json;
};

// Utility function to format filesize, Crafted with GitHub coding tools
const formatFileSize = function (size: number) {
  if (size < 1024) return size + ' B';
  const i = Math.floor(Math.log(size) / Math.log(1024));
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
  return (size / Math.pow(1024, i)).toFixed(2) + ' ' + sizes[i];
};

const formatDate = function (date: string, lang: string) {
  return new Date(date).toLocaleString(lang);
};

module.exports.fetchData = fetchData;
module.exports.formatFileSize = formatFileSize;
module.exports.formatDate = formatDate;

var vscode = require('vscode');

module.exports = class CustomPolicyExplorerProvider implements vscode.TreeDataProvider<String> {;

	_onDidChangeTreeData: vscode.EventEmitter<String | null> = new vscode.EventEmitter<String | null>();
	readonly onDidChangeTreeData: vscode.Event<String | null> = this._onDidChangeTreeData.event;

	editor: vscode.TextEditor;
	autoRefresh: boolean = true;
	xmlDoc: any;

	constructor(/*private context: vscode.ExtensionContext*/) {

		this.editor = vscode.window.activeTextEditor as vscode.TextEditor;
		vscode.window.onDidChangeActiveTextEditor(function () { return this.onActiveEditorChanged(); });
		vscode.workspace.onDidChangeTextDocument(function e { return this.onDocumentChanged(e); });
		this.parseTree();
		this.onActiveEditorChanged();
	}

	refresh(elementKey?: String): void {
		this.parseTree();
		if (elementKey) {
			this._onDidChangeTreeData.fire(elementKey);
		} else {
			this._onDidChangeTreeData.fire();
		}
	}


	onActiveEditorChanged(): void {
		if (vscode.window.activeTextEditor) {
			if (vscode.window.activeTextEditor.document.uri.scheme === 'file') {
				const enabled = vscode.window.activeTextEditor.document.languageId === 'xml';
				vscode.commands.executeCommand('setContext', 'CustomPolicyExplorerEnabled', enabled);
				if (enabled) {
					this.refresh();
				}
			}
		} else {
			vscode.commands.executeCommand('setContext', 'CustomPolicyExplorerEnabled', false);
		}
	}

	onDocumentChanged(changeEvent: vscode.TextDocumentChangeEvent): void {
		if (this.autoRefresh && changeEvent.document.uri.toString() === this.editor.document.uri.toString()) {
			this.parseTree();
			this._onDidChangeTreeData.fire(null);
		}
	}

	parseTree(): void {
		this.editor = vscode.window.activeTextEditor as vscode.TextEditor;

		if (this.editor && this.editor.document) {
			// Load the ativated XML file and replace the element Id with id
			var DOMParser = require('xmldom').DOMParser;
			var xmlText = this.editor.document.getText().replace(/( )(Id=|Id =|Id  =)/gi, " id=");
			this.xmlDoc = new DOMParser().parseFromString(xmlText);
		}
	}


	/*getParent(parentElementKey?: String): String {
		return '';
	}*/

	getElementByTagName(tagName: string) {
		var nsAttr = this.xmlDoc.getElementsByTagName(tagName);

		if (nsAttr.length == 1)
			return nsAttr[0].lineNumber + "|" + nsAttr[0].columnNumber;
		else
			return "";
	}

	getChildren(parentElementKey?: String): Thenable<String[]> {
		const keys: String[] = [];

		if (!parentElementKey) {
			if (this.getElementByTagName("UserJourneys"))
				keys.push("root|UserJourney|User Journeys|" + this.getElementByTagName("UserJourneys"));

			if (this.getElementByTagName("SubJourneys"))
				keys.push("root|SubJourney|Sub Journeys|" + this.getElementByTagName("SubJourneys"));

			if (this.getElementByTagName("ClaimsProviders"))
				keys.push("root|ClaimsProvider|Claims Providers|" + this.getElementByTagName("ClaimsProviders"));

			keys.push("root|TechnicalProfile|Technical Profiles");

			if (this.getElementByTagName("ClaimsSchema"))
				keys.push("root|ClaimType|Claim Types|" + this.getElementByTagName("ClaimsSchema"));

			if (this.getElementByTagName("ClaimsTransformations"))
				keys.push("root|ClaimsTransformation|Claims Transformations|" + this.getElementByTagName("ClaimsTransformations"));

			if (this.getElementByTagName("ContentDefinitions"))
				keys.push("root|ContentDefinition|Content Definitions|" + this.getElementByTagName("ContentDefinitions"));

			if (this.getElementByTagName("Predicates"))
				keys.push("root|Predicate|Predicates|" + this.getElementByTagName("Predicates"));
		}
		else {
			const elementValues: String[] = parentElementKey.split("|");

			if (elementValues[0] == "root") {
				var nsAttr = this.xmlDoc.getElementsByTagName(elementValues[1]);



				var i: number;
				for (i = 0; i < nsAttr.length; i++) {
					let title: string = 'Default';
					let children: string = '';

					// Get the element title
					if (elementValues[1] == "ClaimsProvider") {
						var subNode = nsAttr[i].getElementsByTagName("DisplayName");
						if (subNode != null) {
							title = nsAttr[i].getElementsByTagName("DisplayName")[0].textContent

							// Get the claims provider's technical profiles
							var technicalProfiles = nsAttr[i].getElementsByTagName("TechnicalProfile");

							var x: number;
							for (x = 0; x < technicalProfiles.length; x++) {

								// Add the element to the list
								children += technicalProfiles[x].getAttribute("id") + ";"
							}
						}
					}
					else {
						title = nsAttr[i].getAttribute("id");
					}

					// Add the element to the list
					keys.push(elementValues[1] + "|" + title + "|" + nsAttr[i].lineNumber + "|" + nsAttr[i].columnNumber + "|" + children);
				}
			}
			else if (elementValues[0] == "ClaimsProvider") {

				if (elementValues[4] && elementValues[4] != "") {
					var descendants = elementValues[4].split(";");

					for (let entry of descendants) {
						if (entry && entry != "") {
							// Lookup the XML element
							var nsAttr = this.xmlDoc.getElementById(entry);

							// Add the element to the list
							keys.push(nsAttr.nodeName + "|" + nsAttr.getAttribute("id") + "|" + nsAttr.lineNumber + "|" + nsAttr.columnNumber);
						}
					}

				}
			}

			keys.sort();
		}

		return Promise.resolve(keys);
	}

	getTreeItem(elementKey: String): vscode.TreeItem {

		let treeItem: vscode.TreeItem;
		const elementValues: String[] = elementKey.split("|");

		if (elementValues[0] == "root") {
			// For the root elements, check the amount of such element type
			var nsAttr = this.xmlDoc.getElementsByTagName(elementValues[1]);
			treeItem = new vscode.TreeItem(elementValues[2] as string, nsAttr.length > 0 ? vscode.TreeItemCollapsibleState.Collapsed : vscode.TreeItemCollapsibleState.None);

			// Add a link to the root elements such as ClaimsSchema, ClaimsProviders and UserJourneys
			if (elementValues.length == 5) {
				const start: vscode.Position = new vscode.Position(Number(elementValues[3]) - 1, Number(elementValues[4]));
				const end: vscode.Position = new vscode.Position(Number(elementValues[3]) - 1, Number(elementValues[4]));

				treeItem.command = {
					command: 'extension.openJsonSelection',
					title: '',
					arguments: [new vscode.Range(start, end)]
				};
			}

		}
		else {
			if (elementValues[0] == "ClaimsProvider") {
				// For the ClaimsProvider elements, check if the claim provider has technical profile
				treeItem = new vscode.TreeItem(elementValues[1] as string, elementValues[4].split(";").length > 0 ? vscode.TreeItemCollapsibleState.Collapsed : vscode.TreeItemCollapsibleState.None);
			}
			else {
				treeItem = new vscode.TreeItem(elementValues[1] as string, vscode.TreeItemCollapsibleState.None);
			}

			const start: vscode.Position = new vscode.Position(Number(elementValues[2]) - 1, Number(elementValues[3]));
			const end: vscode.Position = new vscode.Position(Number(elementValues[2]) - 1, Number(elementValues[3]));

			treeItem.command = {
				command: 'extension.openJsonSelection',
				title: '',
				arguments: [new vscode.Range(start, end)]
			};
		}

		return treeItem;
	}

	select(range: vscode.Range) {
		this.editor.selection = new vscode.Selection(range.start, range.end);
		this.editor.revealRange(range, vscode.TextEditorRevealType.AtTop);
	}
}

