// Helper functions
function extractCompanyFromTitle(title: string): string {
  // Try different patterns to extract company name
  var patterns = [
    /at\s+(.+?)(?:\s+\(|$|:)/i,
    /\|\s*(.+?)$/,
    /(.+?)\s*-\s*Remote/i,
    /^(.+?)\s*[:|-]/
  ]

  for (var pattern of patterns) {
    var match = title.match(pattern)
    if (match && match[1]) {
      return match[1].trim()
    }
  }

  return 'Unknown Company'
}

function extractCompanyFromDescription(description: string): string {
  // Remove HTML tags and try to extract company name
  var cleanDesc = description.replace(/<[^>]*>/g, ' ').trim()
  var patterns = [
    /<strong>(.+?)<\/strong>/,
    /Company:\s*(.+?)(?:\n|<br>)/i,
    /^(.+?)\s*is\s+/i
  ]

  for (var pattern of patterns) {
    var match = description.match(pattern)
    if (match && match[1]) {
      return match[1].trim()
    }
  }

  return 'Unknown Company'
}

function extractSalaryFromText(text: string): string | undefined {
  var salaryRegex = /\$[\d,]+(?:\s*-\s*\$[\d,]+)?(?:\s*(?:\/year|\/yr|annually|per year|k|K))?/i
  var match = text.match(salaryRegex)
  return match ? match[0] : undefined
}

// Helper function to extract skills from job text
function extractSkillsFromText(text: string): string[] {
  var commonSkills = [
    'JavaScript', 'TypeScript', 'React', 'Vue', 'Angular', 'Node.js', 'Python', 'Java', 'PHP', 'Ruby',
    'Go', 'Rust', 'C++', 'C#', 'Swift', 'Kotlin', 'Flutter', 'React Native', 'Docker', 'Kubernetes',
    'AWS', 'Azure', 'GCP', 'MongoDB', 'PostgreSQL', 'MySQL', 'Redis', 'GraphQL', 'REST API',
    'Git', 'CI/CD', 'DevOps', 'Agile', 'Scrum', 'TDD', 'Machine Learning', 'AI', 'Data Science',
    'HTML', 'CSS', 'SASS', 'SCSS', 'Webpack', 'Vite', 'Next.js', 'Nuxt.js', 'Express', 'FastAPI',
    'Django', 'Flask', 'Spring', 'Laravel', 'Rails', 'Terraform', 'Jenkins', 'GitHub Actions'
  ]

  var foundSkills = commonSkills.filter(function skill { return text.toLowerCase().includes(skill.toLowerCase()); })

  return foundSkills.slice(0, 10) // Limit to 10 skills
}

function cleanDescription(description: string): string {
  // Remove HTML tags but preserve line breaks
  return description
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 2000) // Limit description length
}

// Main RSS scraper function
export async function scrapeRSSFeeds(): Promise<{
  success: boolean
  jobs: any[]
  errors: string[]
  totalJobs: number
  sources: { [key: string]: number }
}> {
  var allJobs: any[] = []
  var errors: string[] = []
  var sources: { [key: string]: number } = {}

  console.log('Starting RSS feed scraping...')

  for (var feed of RSS_FEEDS) {
    if (!feed.enabled) {
      console.log("Skipping disabled feed: " + (feed.name) + "")
      sources[feed.name] = 0
      continue
    }

    try {
      console.log("Scraping RSS feed: " + (feed.name) + "")

      var response = await axios.get(feed.url, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
          'Accept': 'application/rss+xml, application/xml, text/xml, */*'
        },
        timeout: 15000, // 15 second timeout
        maxRedirects: 5
      })

      var xmlData = await parseXML(response.data) as any
      var items = xmlData?.rss?(.channel == null ? undefined : .channel[0])?.item || xmlData?.feed?.entry || []

      console.log("Found " + (items.length) + " items in " + (feed.name) + "")

      var feedJobCount = 0
      for (var item of items) {
        var job = feed.parser(item)
        if (job && job.title && job.link) {
          // Skip if job is too old (more than 30 days)
          var jobDate = new Date(job.pubDate || Date.now())
          var thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000)

          if (jobDate < thirtyDaysAgo) {
            continue
          }          // Convert RSS job to database format
          var dbJob = {
            title: job.title.trim(),
            description: cleanDescription(job.description || ''),
            company_name: job.company || 'Unknown Company',
            location: job.location || 'Remote',
            employment_type: 'full-time',
            remote_type: 'remote', // Use existing enum value
            skills: extractSkillsFromText(job.title + ' ' + job.description),
            apply_url: job.link,
            source: feed.name, // Will be ignored if column doesn't exist
            posted_at: new Date(job.pubDate || Date.now()).toISOString(),
            expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(), // 30 days from now
            is_active: false, // Require admin approval
            salary_text: extractSalaryFromText(job.title + ' ' + job.description), // Will be ignored if column doesn't exist
            feed_source: feed.name, // Store source info in temp field
            salary_info: extractSalaryFromText(job.title + ' ' + job.description) // Store salary info temporarily
          }

          allJobs.push(dbJob)
          feedJobCount++
        }
      }

      sources[feed.name] = feedJobCount
      console.log("Successfully scraped " + (feedJobCount) + " jobs from " + (feed.name) + "")

    } catch (error: any) {
      var errorMsg = "Error scraping " + (feed.name) + ": " + (error.message) + ""
      console.error(errorMsg)
      errors.push(errorMsg)
      sources[feed.name] = 0
    }
  }

  return {
    success: errors.length < RSS_FEEDS.filter(function f { return f.enabled; }).length, // Success if at least one feed works
    jobs: allJobs,
    errors,
    totalJobs: allJobs.length,
    sources
  }
}

// Function to get enabled RSS feeds (for admin configuration)
function getRSSFeeds(): RSSFeed[] {
  return RSS_FEEDS
}

// Function to update RSS feed configuration
function updateRSSFeedConfig(feedName: string, enabled: boolean): boolean {
  var feed = RSS_FEEDS.find(function f { return f.name === feedName; })
  if (feed) {
    feed.enabled = enabled
    return true
  }
  return false
}

// Matrix Droplets

var getRandomNumber = require('./utils').getRandomNumber;
var rotateArrayRight = require('./utils').rotateArrayRight;
import {
  ENGLISH_CHARACTER_CODE_START,
  ENGLISH_CHARACTER_CODE_END,
  getRandomCharacterCode
} from "./characters";
var GREEN = require('./ansi').GREEN;
var WHITE = require('./ansi').WHITE;
var printColor = require('./ansi').printColor;
var moveCursorToPosition = require('./ansi').moveCursorToPosition;

// Our Droplet Class
class Droplet {
  column: i32;
  row: i32;
  // Going to use a character code array here
  // instead of a string to fix memory issues
  characterCodeArray: Array<u8>;
  speed: i32;
  height: i32;
}

// Function to create a droplet
function createDroplet(column: i32, lines: i32): Droplet {
  // Create the droplet
  var droplet: Droplet = new Droplet();

  // Populate the droplet values
  droplet.column = column;
  droplet.row = getRandomNumber() % lines;
  droplet.height = (getRandomNumber() % (lines / 2)) + 3;
  droplet.speed = (getRandomNumber() % 2) + 1;

  // Create our initial string
  droplet.characterCodeArray = new Array<u8>(droplet.height);
  for (var i = 0; i < droplet.height; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }

  return droplet;
}

// "Moves" a droplet down the screen
function updateDroplet(droplet: Droplet, lines: i32): void {
  // Increase the droplet row
  droplet.row += droplet.speed;

  // Wrap the rows so it comes back from up top
  if (droplet.row >= droplet.height + lines) {
    droplet.row = 0 - droplet.height;
  }

  // Rotate down the old characters
  // How many characters to rotate
  for (var i = 0; i < droplet.speed; i++) {
    rotateArrayRight(droplet.characterCodeArray);
  }

  // Add some new characters
  // To replace the old rotated ones
  for (var i = 0; i < droplet.speed; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }
}

// Places a droplet (and its characters) onto the screen
function drawDroplet(droplet: Droplet, lines: i32): void {
  // Loop over our characters
  for (var i = 0; i < droplet.characterCodeArray.length; i++) {
    var cursorRow = droplet.row + i;

    if (cursorRow >= 0 && cursorRow <= lines) {
      // Move the cursor to the correct position
      moveCursorToPosition(droplet.column, cursorRow);

      // Get our color
      var color: string = GREEN;
      if (i === droplet.characterCodeArray.length - 1) {
        color = WHITE;
      }

      // Draw the character
      // TODO: Optimize this, and try to remove generating / manipulating.
      // Perhpas write the character Codes Array directly?
      printColor(String.fromCharCode(droplet.characterCodeArray[i]), color);
    }
  }
}

// Aided with basic GitHub coding tools April 23, 2025 19:35
var useTorrentClient = function () {
  var config = useRuntimeConfig()

  // Use proxy path instead of direct URL to avoid CORS issues
  var qb = $fetch.create({
    baseURL: '/qbittorrent/api/v2',
    credentials: 'include'
  })

  var login = async () => {
    await qb('/auth/login', {
      method: 'POST',
      body: new URLSearchParams({
        username: config.public.qBittorrentUsername || 'admin',
        password: config.public.qBittorrentPassword || ''
      })
    })
  }

  var add = async (url: string) => {
    var form = new FormData()
    form.append('urls', url)
    form.append('savepath', config.public.downloadsPath || '/downloads')
    await qb('/torrents/add', {
      method: 'POST',
      body: form
    })
  }

  return { login, add }
}

