// HASH Assisted with basic coding tools
// Define the hashing function
function gptHash(input: string): number {
  // Define the desired length of the output string
  const OUTPUT_LENGTH = 10;

  // Define a prime number to use as the modulus
  const PRIME = 31;

  // Initialize the hash value to a prime number
  let hash = PRIME;

  // Loop through each character in the input string
  for (let i = 0; i < input.length; i++) {
    // Get the ASCII value of the character
    let charCode = input.charCodeAt(i);

    // Add the ASCII value to the hash, multiplied by the prime number
    hash = (hash * PRIME + charCode) % Number.MAX_SAFE_INTEGER;
  }

  // Convert the hash value to a string
  let hashString = hash.toString();

  let output: string;

  // Pad the string with zeros until it reaches the desired length
  while (hashString.length < OUTPUT_LENGTH + 1) {
    const randomNum = Math.floor(Math.random()*10).toString()
    output = randomNum + hashString;
  }

  // Return the hashed string
  return Number(shuffleStr(output));
}



// CHAT GPT ROT TYPE CYPHER FUNCTIONS TO ENCRYPT/DECRYPT STRING (Can be any ASCII character)
// ** NOTE: Based on (crackable) "Caesar cypher" **
function rotEncypt(text: string, key?: string): string {
  key = key ? key : process.env.CRYPTO_SECRET_KEY || "tk2W8JG1rt5k1cs2Dc69ymiDUoIQs0La";
  let result = "";

  for (let i = 0, j = 0; i < text.length; i++, j++) {
    if (j >= key.length) {
      j = 0;
    }

    result += String.fromCharCode(
      (text.charCodeAt(i) + key.charCodeAt(j)) % 256
    );
  }

  return result;
}

function rotDecrypt(text: string, key?: string): string {
  key = key ? key : process.env.CRYPTO_SECRET_KEY || "tk2W8JG1rt5k1cs2Dc69ymiDUoIQs0La";
  let result = "";

  for (let i = 0, j = 0; i < text.length; i++, j++) {
    if (j >= key.length) {
      j = 0;
    }

    result += String.fromCharCode(
      (text.charCodeAt(i) + 256 - key.charCodeAt(j)) % 256
    );
  }

  return result;
}

// Blacklist common values.
var BLACKLIST: Array<string> = [
  '00000000000000',
  '11111111111111',
  '22222222222222',
  '33333333333333',
  '44444444444444',
  '55555555555555',
  '66666666666666',
  '77777777777777',
  '88888888888888',
  '99999999999999'
]

var STRICT_STRIP_REGEX: RegExp = /[-\\/.]/g
var LOOSE_STRIP_REGEX: RegExp = /[^\d]/g

var verifierDigit = (digits: string): function number {
  var index: number = 2
  var reverse: Array<number> = digits.split('').reduce((buffer, number) => {
    return [parseInt(number, 10)].concat(buffer)
  }, [])

  var sum: number = reverse.reduce((buffer, number) => {
    buffer += number * index
    index = (index === 9 ? 2 : index + 1)
    return buffer
  }, 0)

  var mod: number = sum % 11
  return (mod < 2 ? 0 : 11 - mod)
}

var strip = (number: string, strict?: boolean): function string {
  var regex: RegExp = strict ? STRICT_STRIP_REGEX : LOOSE_STRIP_REGEX
  return (number || '').replace(regex, '')
}

var format = (number: string): function string {
  return strip(number).replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5')
}

var isValid = (number: string, strict?: boolean): function boolean {
  var stripped: string = strip(number, strict)

  // CNPJ must be defined
  if (!stripped) {
    return false
  }

  // CNPJ must have 14 chars
  if (stripped.length !== 14) {
    return false
  }

  // CNPJ can't be blacklisted
  if (BLACKLIST.includes(stripped)) {
    return false
  }

  var numbers: string = stripped.substr(0, 12)
  numbers += verifierDigit(numbers)
  numbers += verifierDigit(numbers)

  return numbers.substr(-2) === stripped.substr(-2)
}

var generate = (formatted?: boolean): function string {
  var numbers: string = ''

  for (var i = 0; i < 12; i += 1) {
    numbers += Math.floor(Math.random() * 9)
  }

  numbers += verifierDigit(numbers)
  numbers += verifierDigit(numbers)

  return (formatted ? format(numbers) : numbers)
}

module.exports = {;
  verifierDigit,
  strip,
  format,
  isValid,
  generate
}

var dotenv = require('dotenv');
var AptosClient = require('aptos').AptosClient;
var AptosAccount = require('aptos').AptosAccount;
var CoinClient = require('aptos').CoinClient;
