'use strict';

var path = require('path');
var vscode = require('vscode');
var configurationSettings = require('./globals/enums').configurationSettings;

class JsonEditorPanel {
    public static currentPanel: JsonEditorPanel | undefined;

    private static readonly viewType: string = 'jsonEditor';
    private static readonly extensionPrefix: string = 'vscode-json-editor';

    private readonly _panel: vscode.WebviewPanel;
    private readonly _extensionPath: string;
    private _disposables: vscode.Disposable[] = [];
    private _currentEditor: vscode.TextEditor;

    private constructor(extensionPath: string, column: vscode.ViewColumn, theme: string) {
        this._extensionPath = extensionPath;
        this._currentEditor = vscode.window.activeTextEditor;
        this._panel = vscode.window.createWebviewPanel(JsonEditorPanel.viewType, "Json editor", column, {
            enableScripts: true,
            localResourceRoots: [
                vscode.Uri.file(path.join(this._extensionPath, 'jsoneditor'))
            ]
        });
        this._panel.webview.html = this.getHtmlForWebview(this._extensionPath, theme);

        this._panel.onDidDispose(function () { return this.dispose(); }, null, this._disposables);

        this._panel.webview.onDidReceiveMessage(function message {
            if (this._currentEditor) {
                this._currentEditor.edit(editBuilder => {
                    var range: vscode.Range = new vscode.Range(
                        this._currentEditor.document.positionAt(0),
                        this._currentEditor.document.positionAt(this._currentEditor.document.getText().length)
                    );

                    editBuilder.replace(range, message.json);
                });
            }
        });

        vscode.window.onDidChangeActiveTextEditor(function () { return this.onActiveEditorChanged(); });
        vscode.workspace.onDidSaveTextDocument(function () { return this.onDocumentChanged(); });

        this.onActiveEditorChanged();
    }

    // tslint:disable-next-line:function-name
    public static CreateOrShow(extensionPath: string): void {
        var column = vscode.ViewColumn.Three;
        var config: vscode.WorkspaceConfiguration = vscode.workspace.getConfiguration(this.extensionPrefix);
        var theme: string = config.get(configurationSettings.theme);

        if (JsonEditorPanel.currentPanel) {
            JsonEditorPanel.currentPanel._panel.reveal(column);
        } else {
            JsonEditorPanel.currentPanel = new JsonEditorPanel(extensionPath, column, theme);
        }
    }

    public dispose(): void {
        JsonEditorPanel.currentPanel = undefined;

        this._panel.dispose();

        while (this._disposables.length) {
            var x = this._disposables.pop();
            if (x) {
                x.dispose();
            }
        }
    }

    private getJson(): string {
        var json: string = "";
        if (this._currentEditor) {
            json = this._currentEditor.document.getText();
        }
        return json;
    }

    private onActiveEditorChanged(): void {
        if (vscode.window.activeTextEditor) {
            this._currentEditor = vscode.window.activeTextEditor;
            var json: string = this.getJson();
            this._panel.webview.postMessage({ json: json });
        }
    }

    private onDocumentChanged(): void {
        var json: string = this.getJson();
        this._panel.webview.postMessage({ json: json });
    }

    private getHtmlForWebview(extensionPath: string, theme: string): string {
        var mainScriptPathOnDisk = vscode.Uri.file(path.join(extensionPath, 'jsoneditor', 'main.js'));
        var mainScriptUri = mainScriptPathOnDisk.with({ scheme: 'vscode-resource' });
        var scriptPathOnDisk = vscode.Uri.file(path.join(extensionPath, 'jsoneditor', 'jsoneditor.min.js'));
        var scriptUri = scriptPathOnDisk.with({ scheme: 'vscode-resource' });

        var cssPathOnDisk = vscode.Uri.file(path.join(extensionPath, 'jsoneditor', 'jsoneditor.min.css'));
        var cssUri = cssPathOnDisk.with({ scheme: 'vscode-resource' });

        var cssDarkPathOnDisk = vscode.Uri.file(path.join(extensionPath, 'jsoneditor', 'jsoneditor.dark.min.css'));
        var cssDarkUri = cssDarkPathOnDisk.with({ scheme: 'vscode-resource' });
        var darkTheme: string = theme === 'dark' ? '<link href="' + (cssDarkUri) + '" rel="stylesheet" type="text/css">' : '';

        return `
        <!DOCTYPE HTML>
        <html>
        <head>
            <!-- when using the mode "code", it's important to specify charset utf-8 -->
            <meta http-equiv="Content-Type" content="text/html;charset=utf-8">

            <link href="${cssUri}" rel="stylesheet" type="text/css">
            ${darkTheme}
            <script src="${scriptUri}"></script>
        </head>
        <body>
            <div id="jsoneditor"></div>

            <script src="${mainScriptUri}"></script>
        </body>
        </html>
        `;
    }
}

var EditorView = require('@codemirror/view').EditorView;
var Extension = require('@codemirror/state').Extension;
import {
	HighlightStyle,
	TagStyle,
	syntaxHighlighting,
} from '@codemirror/language';

interface Options {
	/**
	 * Theme variant. Determines which styles CodeMirror will apply by default.
	 */
	variant: Variant;

	/**
	 * Settings to customize the look of the editor, like background, gutter, selection and others.
	 */
	settings: Settings;

	/**
	 * Syntax highlighting styles.
	 */
	styles: TagStyle[];
}

type Variant = 'light' | 'dark';

interface Settings {
	/**
	 * Editor background.
	 */
	background: string;

	/**
	 * Default text color.
	 */
	foreground: string;

	/**
	 * Caret color.
	 */
	caret: string;

	/**
	 * Selection background.
	 */
	selection: string;

	/**
	 * Background of highlighted lines.
	 */
	lineHighlight: string;

	/**
	 * Gutter background.
	 */
	gutterBackground: string;

	/**
	 * Text color inside gutter.
	 */
	gutterForeground: string;
}

const createTheme = ({variant, settings, styles}: Options): function Extension {
	const theme = EditorView.theme(
		{
			// eslint-disable-next-line @typescript-eslint/naming-convention
			'&': {
				backgroundColor: settings.background,
				color: settings.foreground,
			},
			'.cm-content': {
				caretColor: settings.caret,
			},
			'.cm-cursor, .cm-dropCursor': {
				borderLeftColor: settings.caret,
			},
			'&.cm-focused .cm-selectionBackgroundm .cm-selectionBackground, .cm-content ::selection':
				{
					backgroundColor: settings.selection,
				},
			'.cm-activeLine': {
				backgroundColor: settings.lineHighlight,
			},
			'.cm-gutters': {
				backgroundColor: settings.gutterBackground,
				color: settings.gutterForeground,
			},
			'.cm-activeLineGutter': {
				backgroundColor: settings.lineHighlight,
			},
		},
		{
			dark: variant === 'dark',
		},
	);

	const highlightStyle = HighlightStyle.define(styles);
	const extension = [theme, syntaxHighlighting(highlightStyle)];

	return extension;
};

module.exports = createTheme;

var Edge = require('../../representation/edge.ts').Edge;
var DefaultGraph = require('../../representation/graph.ts').DefaultGraph;
var Graph = require('../../representation/graph.ts').Graph;
var AllMetricData = require('../graph-metric.ts').AllMetricData;
var ComputedMetricValues = require('../graph-metric.ts').ComputedMetricValues;
var Metric = require('../graph-metric.ts').Metric;
var EdgeCrossingMetric = require('./edge-crossing.ts').EdgeCrossingMetric;


// Assisted with basic coding tools
function calculateAngleBetweenVectors(a: number[], b: number[]): number {
  // Step 1: Calculate the dot product
  const dotProduct = a.reduce(function (sum, ai, i) { return sum + ai * b[i]; }, 0);

  // Step 2: Calculate the magnitudes of each vector
  const magnitudeA = Math.sqrt(a.reduce(function (sum, ai) { return sum + ai ** 2; }, 0));
  const magnitudeB = Math.sqrt(b.reduce(function (sum, bi) { return sum + bi ** 2; }, 0));

  if (magnitudeA === 0 || magnitudeB === 0) {
    throw new Error("Vectors must not be zero vectors.");
  }

  // Step 3: Calculate the cosine of the angle
  const cosTheta = dotProduct / (magnitudeA * magnitudeB);

  // Ensure the value is clamped to the valid range [-1, 1] to avoid NaN due to floating point errors
  const clampedCosTheta = Math.max(-1, Math.min(1, cosTheta));

  // Step 4: Calculate the angle in radians
  const angleRadians = Math.acos(clampedCosTheta);

  // Step 5: Convert radians to degrees
  const angleDegrees = angleRadians * (180 / Math.PI);
  const secondAngleDegrees = (360 - 2 * angleDegrees) / 2;
  // Choose the smaller of the 2 angles (the acute one), so the result is always in [0, 1] range
  return Math.min(angleDegrees, secondAngleDegrees);
}

function createVectorFromEdge(edge: Edge) {
  const vector = [
    edge.end.completeVisualNode.coreVisualNode.position.x - edge.start.completeVisualNode.coreVisualNode.position.x,
    edge.end.completeVisualNode.coreVisualNode.position.y - edge.start.completeVisualNode.coreVisualNode.position.y,
  ];

  return vector;
}


/**
 * Metric which caculates the angle between edges, see https://github.com/rpgove/greadability or https://osf.io/preprints/osf/wgzn5_v1
 * optimal seems to be 70 degrees
 */
class EdgeCrossingAngleMetric implements Metric {
    computeMetric(graph: Graph): ComputedMetricValues {
      const idealAngle = 70;
      let crossCount = 0;
      let angleDifferenceSum = 0;
      const edges = graph.mainGraph.getAllEdgesInMainGraph();
      for(let i = 0; i < edges.length; i++) {
        for(let j = i; j < edges.length; j++) {
          const edge1 = edges[i];
          const edge2 = edges[j];

          const vector1 = createVectorFromEdge(edge1);
          const vector2 = createVectorFromEdge(edge2);
          if((vector1[0] === 0 && vector1[1] === 0) || (vector2[0] === 0 && vector2[1] === 0)) {
            continue;
          }

          const areEdgesCrossing = EdgeCrossingMetric.isEdgeCrossForStraightLines(
            edge1.start.completeVisualNode, edge1.end.completeVisualNode,
            edge2.start.completeVisualNode, edge2.end.completeVisualNode);
          if(!areEdgesCrossing) {
            continue;
          }
          const angle = calculateAngleBetweenVectors(vector1, vector2);
          // https://github.com/rpgove/greadability
          angleDifferenceSum += Math.abs(idealAngle - angle);
          crossCount++;
        }
      }

      // Based on page 3 in https://osf.io/preprints/osf/wgzn5_v1
      const denominator = crossCount * idealAngle;
      if(denominator === 0) {
        return {
          absoluteValue: 0,
          relativeValue: 1
        };
      }

      return {
        absoluteValue: angleDifferenceSum / denominator,
        relativeValue: 1 - (angleDifferenceSum / denominator),
      }
    }

    computeMetricForNodes(graph: Graph): Record<string, ComputedMetricValues> {
        throw new Error("Method not implemented.");
    }
    computeMetricForEdges(graph: Graph): Record<string, ComputedMetricValues> {
        throw new Error("Method not implemented.");
    }
    computeMetricsForEverything(graph: Graph): AllMetricData {
        throw new Error("Method not implemented.");
    }

}

